const TOP_LEVEL_FILTERS: [&str; 6] = [
    "annexB",
    "built-ins",
    "harness",
    "intl402",
    "language",
    "staging",
];
const MATRIX_SPLIT_FILTERS: [&str; 4] = ["built-ins", "intl402", "language", "staging"];
const SNAPSHOT_VERSION: u32 = 8;
/// Version 7 carries exact execution identity but no compiler binding.
const LEGACY_EXECUTION_IDENTITY_SNAPSHOT_VERSION: u32 = 7;
/// Snapshot version 4 predates per-failure outcome data and execution identity.
/// Its envelope may still be inspected as historical metadata, but path-only
/// case records cannot enter current status, backlog, comparison, or resume
/// state and are never assigned a guessed execution mode.
const LEGACY_PRE_OUTCOME_SNAPSHOT_VERSION: u32 = 4;
/// Snapshot version 5 has outcome data, but predates the explicit Scriptw
/// producer identity or execution identity. Like version 4 it is historical
/// metadata only: path-only case records cannot enter typed current state and
/// the artifact is never resumed, merged, rewritten, or published as current.
const LEGACY_PRE_SCRIPTW_SNAPSHOT_VERSION: u32 = 5;
/// Version 6 is the last Scriptw snapshot whose case identity was only a physical
/// path. Its envelope remains readable historical metadata where supported,
/// but it cannot enter any stateful path: a path does not say which of the
/// required sloppy/strict executions ran.
const LEGACY_PATH_ONLY_SNAPSHOT_VERSION: u32 = 6;
const MATRIX_STRATEGY_VERSION: u32 = 3;
// Keep matrix nodes small enough that slow semantic buckets like RegExp and
// Temporal checkpoint incrementally instead of monopolizing a whole run.
const MATRIX_RECURSION_THRESHOLD: usize = 500;
const MATRIX_CHUNK_SIZE: usize = 250;
// Checkpoint periodically so an interrupted first run or low-RAM resume never
// restarts a whole slow node, without paying the O(n)
// summarize/sort/fs::write cost after every single case (which made resume
// runs O(n^2) in the number of completed cases). A final checkpoint is always
// written after a resume run completes, so normal resume exits never lose
// progress; only an interrupt can lose up to
// `RESUME_CASE_CHECKPOINT_INTERVAL - 1` already-completed cases.
const RESUME_CASE_CHECKPOINT_INTERVAL: usize = 10;
/// Matches the stack required by Scriptw's Wasm-AOT current-thread execution
/// entry. Test262 workers persist for many cases, so this avoids a nested
/// worker spawn for each compile, emit, and execution phase.
const TEST262_WORKER_STACK_SIZE: usize = 64 * 1024 * 1024;
// The Store's execution deadline applies the configured timeout only after a
// Wasm-AOT module starts executing. An isolated child still needs a separate
// finite allowance for parsing, lowering, emission, and cold native compile.
const WASM_AOT_CHILD_COMPILE_ALLOWANCE_MS: u64 = 300_000;
const WASM_AOT_HOST_PRELUDE: &str = include_str!("../assets/local-harness/wasm-aot-host.js");
const WASM_AOT_INACTIVE_REALM_GLOBAL: &str = "  global: undefined,";
