#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SuiteConfig {
    pub suite_root: PathBuf,
    pub local_harness: LocalHarnessSource,
    pub snapshot_dir: PathBuf,
    pub timeout_ms: u64,
    pub worker_count: usize,
    /// Executable implementing the hidden `test262 __case-worker` route.
    /// Discovery does not require a worker; executing admitted cases does.
    pub case_runner_bin: Option<PathBuf>,
    /// Reuse at most 64 sequential requests per owned worker process. Every
    /// request still has a fresh Engine/Realm/Store and its own outer deadline.
    /// One-shot remains available for replay and arbitrary external workers.
    pub reuse_case_workers: bool,
    // The supervisor's output namespace survives replacement of snapshot_dir
    // with a worker's isolated result directory.
    source_output_root: Option<PathBuf>,
    execution_role: CaseExecutionRole,
}

impl SuiteConfig {
    /// Carries the supervisor's output role over the private worker protocol.
    #[doc(hidden)]
    pub fn inherit_case_output_root(&mut self, path: PathBuf) -> Result<(), String> {
        let mut candidate = self.clone();
        candidate.source_output_root = Some(path);
        suite_identity::owned_output_root(&candidate)?;
        *self = candidate;
        Ok(())
    }

    fn source_output_root(&self) -> &Path {
        self.source_output_root
            .as_deref()
            .unwrap_or(&self.snapshot_dir)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CaseExecutionRole {
    Supervisor,
    SingleCaseWorker(TestExecutionId),
    #[cfg(test)]
    FixtureWorker,
}

/// Checked once before scheduling. An absent worker never authorizes compilation.
#[derive(Clone)]
enum CaseExecutionDispatch {
    Supervised(PathBuf),
    Reused(PathBuf),
    Worker,
}

impl CaseExecutionDispatch {
    fn admit(config: &SuiteConfig, cases: &[TestCase]) -> Result<Self, String> {
        match &config.execution_role {
            CaseExecutionRole::SingleCaseWorker(expected) => {
                if cases.len() != 1 || cases[0].execution_id != *expected {
                    return Err(
                        "case worker must execute exactly its requested execution id".into(),
                    );
                }
                Ok(Self::Worker)
            }
            #[cfg(test)]
            CaseExecutionRole::FixtureWorker if config.case_runner_bin.is_none() => {
                Ok(Self::Worker)
            }
            CaseExecutionRole::Supervisor => Self::supervisor(config),
            #[cfg(test)]
            CaseExecutionRole::FixtureWorker => Self::supervisor(config),
        }
    }

    fn supervisor(config: &SuiteConfig) -> Result<Self, String> {
        if let Some(binary) = &config.case_runner_bin {
            if binary.as_os_str().is_empty() {
                return Err("Test262 supervisor requires a nonempty case worker executable".into());
            }
            return Ok(if config.reuse_case_workers {
                Self::Reused(binary.clone())
            } else {
                Self::Supervised(binary.clone())
            });
        }
        Err("Test262 execution requires a selected case worker executable; in-process compilation is reserved for the exact single-case worker entry".into())
    }
}

impl Default for SuiteConfig {
    fn default() -> Self {
        let root = PathBuf::from("test262");
        Self {
            suite_root: root.join("vendor").join("test262"),
            local_harness: LocalHarnessSource::EmbeddedSpecExec,
            snapshot_dir: root.join("snapshots"),
            // Keep this bound strict: it exists to turn hangs and pathological
            // Wasm-AOT stalls into a visible, bounded Timeout failure instead of
            // an unbounded multi-minute process stall. A correctness-green but
            // genuinely-this-slow case is itself performance debt (see
            // conformance area T25) and must not hide behind an inflated bound. A single
            // fresh Engine/Wasmtime bootstrap plus compile in an unoptimized
            // debug build costs roughly 15-30s even for a trivial script, so
            // this floor keeps headroom above that legitimate cost while
            // staying far tighter than the previous 240_000ms/500_000ms
            // stalls.
            timeout_ms: 60_000,
            worker_count: thread::available_parallelism()
                .map(|count| count.get().min(4))
                .unwrap_or(4),
            case_runner_bin: None,
            reuse_case_workers: false,
            source_output_root: None,
            execution_role: CaseExecutionRole::Supervisor,
        }
    }
}

/// The complete `negative.phase` domain admitted from Test262 frontmatter.
///
/// Discovery converts the wire spelling into this type once. Past that
/// boundary, adding a phase requires every routing decision to handle it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NegativePhase {
    Parse,
    Early,
    Resolution,
    Runtime,
}

impl NegativePhase {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Parse => "parse",
            Self::Early => "early",
            Self::Resolution => "resolution",
            Self::Runtime => "runtime",
        }
    }

    fn parse(value: &str) -> Result<Self, String> {
        match value {
            "parse" => Ok(Self::Parse),
            "early" => Ok(Self::Early),
            "resolution" => Ok(Self::Resolution),
            "runtime" => Ok(Self::Runtime),
            _ => Err(format!("unknown negative.phase `{value}`")),
        }
    }
}

impl fmt::Display for NegativePhase {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NegativeExpectation {
    pub phase: NegativePhase,
    pub error_type: String,
}

/// The complete execution-mode domain required by Test262's frontmatter.
///
/// This is the sole parse-goal and strictness authority. In particular there
/// is intentionally no `is_module` field beside it that could disagree.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum TestExecutionMode {
    SloppyScript,
    StrictScript,
    RawScript,
    Module,
    RawModule,
}

impl TestExecutionMode {
    pub const ALL: [Self; 5] = [
        Self::SloppyScript,
        Self::StrictScript,
        Self::RawScript,
        Self::Module,
        Self::RawModule,
    ];

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::SloppyScript => "sloppy-script",
            Self::StrictScript => "strict-script",
            Self::RawScript => "raw-script",
            Self::Module => "module",
            Self::RawModule => "raw-module",
        }
    }

    pub const fn is_module(self) -> bool {
        match self {
            Self::Module | Self::RawModule => true,
            Self::SloppyScript | Self::StrictScript | Self::RawScript => false,
        }
    }

    pub const fn is_raw(self) -> bool {
        match self {
            Self::RawScript | Self::RawModule => true,
            Self::SloppyScript | Self::StrictScript | Self::Module => false,
        }
    }

    pub const fn needs_strict_directive(self) -> bool {
        match self {
            Self::StrictScript => true,
            Self::SloppyScript | Self::RawScript | Self::Module | Self::RawModule => false,
        }
    }

    fn parse(value: &str) -> Result<Self, String> {
        match value {
            "sloppy-script" => Ok(Self::SloppyScript),
            "strict-script" => Ok(Self::StrictScript),
            "raw-script" => Ok(Self::RawScript),
            "module" => Ok(Self::Module),
            "raw-module" => Ok(Self::RawModule),
            _ => Err(format!("unknown Test262 execution mode `{value}`")),
        }
    }
}

impl fmt::Display for TestExecutionMode {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

/// A source file plus the mode of this particular Test262 execution.
///
/// Fields are private so a caller cannot manufacture an id whose path or mode
/// disagrees with a `TestCase`. The stable wire spelling is
/// `<mode>:<physical-path>`; the mode prefix makes parsing unambiguous even
/// when the path itself contains a colon.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct TestExecutionId {
    path: String,
    mode: TestExecutionMode,
}

impl TestExecutionId {
    fn new(path: impl Into<String>, mode: TestExecutionMode) -> Self {
        Self {
            path: path.into(),
            mode,
        }
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub const fn mode(&self) -> TestExecutionMode {
        self.mode
    }

    pub fn wire_key(&self) -> String {
        format!("{}:{}", self.mode.as_str(), self.path)
    }

    pub fn parse_wire_key(value: &str) -> Result<Self, String> {
        let Some((mode, path)) = value.split_once(':') else {
            return Err(format!(
                "invalid Test262 execution id `{value}` (expected <mode>:<path>)"
            ));
        };
        if path.is_empty() {
            return Err("Test262 execution id has an empty physical path".to_string());
        }
        Ok(Self::new(path, TestExecutionMode::parse(mode)?))
    }
}

impl fmt::Display for TestExecutionId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{} [{}]", self.path, self.mode)
    }
}

impl Serialize for TestExecutionId {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.wire_key())
    }
}

impl<'de> Deserialize<'de> for TestExecutionId {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let value = String::deserialize(deserializer)?;
        Self::parse_wire_key(&value).map_err(serde::de::Error::custom)
    }
}

/// The validated expansion of one physical file. Keeping the one- and
/// two-execution cases closed makes it impossible for discovery to produce an
/// empty plan or an accidental third variant.
enum TestExecutionPlan {
    One(TestExecutionMode),
    SloppyAndStrict,
}

impl TestExecutionPlan {
    fn from_flags(path: &str, flags: &BTreeSet<String>) -> Result<Self, String> {
        let only_strict = flags.contains("onlyStrict");
        let no_strict = flags.contains("noStrict");
        let raw = flags.contains("raw");
        let module = flags.contains("module");

        if only_strict && no_strict {
            return Err(format!(
                "invalid Test262 flags for {path}: onlyStrict and noStrict are mutually exclusive"
            ));
        }
        if raw && (only_strict || no_strict) {
            return Err(format!(
                "invalid Test262 flags for {path}: raw cannot be combined with onlyStrict or noStrict"
            ));
        }
        if module && (only_strict || no_strict) {
            return Err(format!(
                "invalid Test262 flags for {path}: module cannot be combined with onlyStrict or noStrict"
            ));
        }

        match (raw, module, only_strict, no_strict) {
            (true, true, false, false) => Ok(Self::One(TestExecutionMode::RawModule)),
            (true, false, false, false) => Ok(Self::One(TestExecutionMode::RawScript)),
            (false, true, false, false) => Ok(Self::One(TestExecutionMode::Module)),
            (false, false, true, false) => Ok(Self::One(TestExecutionMode::StrictScript)),
            (false, false, false, true) => Ok(Self::One(TestExecutionMode::SloppyScript)),
            (false, false, false, false) => Ok(Self::SloppyAndStrict),
            // Every invalid combination was rejected above. This exhaustive
            // arm documents that invariant without silently choosing a mode.
            (true, _, true, _)
            | (true, _, _, true)
            | (_, true, true, _)
            | (_, true, _, true)
            | (_, _, true, true) => unreachable!("invalid flag combinations were rejected"),
        }
    }

    fn modes(self) -> impl Iterator<Item = TestExecutionMode> {
        let modes = match self {
            Self::One(mode) => [Some(mode), None],
            Self::SloppyAndStrict => [
                Some(TestExecutionMode::SloppyScript),
                Some(TestExecutionMode::StrictScript),
            ],
        };
        modes.into_iter().flatten()
    }
}

