#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum PreludeHostOwnership {
    #[default]
    None,
    EmbeddedSpecExecSta,
    WasmAot(CompleteWasmAotHostPrelude),
}

mod complete_wasm_aot_host_prelude {
    use super::{
        WASM_AOT_ACTIVE_CREATE_REALM, WASM_AOT_ACTIVE_REALM_GLOBAL, WASM_AOT_HOST_PRELUDE,
        WASM_AOT_INACTIVE_CREATE_REALM, WASM_AOT_INACTIVE_REALM_GLOBAL, WasmAotRealmActivation,
    };

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(super) struct CompleteWasmAotHostPrelude {
        _validated: EmbeddedHostValidation,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct EmbeddedHostValidation;

    impl CompleteWasmAotHostPrelude {
        pub(super) fn load_embedded() -> Result<Self, String> {
            for marker in [
                WASM_AOT_INACTIVE_REALM_GLOBAL,
                WASM_AOT_INACTIVE_CREATE_REALM,
            ] {
                let occurrences = WASM_AOT_HOST_PRELUDE.match_indices(marker).count();
                if occurrences != 1 {
                    return Err(format!(
                        "embedded Wasm-AOT host prelude contains {occurrences} copies of required marker `{marker}`"
                    ));
                }
            }
            for marker in [WASM_AOT_ACTIVE_REALM_GLOBAL, WASM_AOT_ACTIVE_CREATE_REALM] {
                let occurrences = WASM_AOT_HOST_PRELUDE.match_indices(marker).count();
                if occurrences != 0 {
                    return Err(format!(
                        "embedded Wasm-AOT host prelude contains {occurrences} copies of active marker `{marker}`"
                    ));
                }
            }
            if !WASM_AOT_HOST_PRELUDE.ends_with('\n') {
                return Err("embedded Wasm-AOT host prelude must end with a newline".to_string());
            }
            Ok(Self {
                _validated: EmbeddedHostValidation,
            })
        }

        pub(super) fn render(self, realm: WasmAotRealmActivation) -> String {
            match realm {
                WasmAotRealmActivation::Dormant => WASM_AOT_HOST_PRELUDE.to_string(),
                WasmAotRealmActivation::Active => WASM_AOT_HOST_PRELUDE
                    .replacen(
                        WASM_AOT_INACTIVE_REALM_GLOBAL,
                        WASM_AOT_ACTIVE_REALM_GLOBAL,
                        1,
                    )
                    .replacen(
                        WASM_AOT_INACTIVE_CREATE_REALM,
                        WASM_AOT_ACTIVE_CREATE_REALM,
                        1,
                    ),
            }
        }
    }
}

use complete_wasm_aot_host_prelude::CompleteWasmAotHostPrelude;

