/// The canonical run context an in-progress direct checkpoint will eventually
/// become. Keeping kind and matrix path in one value prevents a full, shard,
/// or matrix checkpoint from being resumed or promoted in another context.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct CheckpointRunIdentity {
    terminal_run_kind: String,
    matrix_path: Vec<String>,
}

impl CheckpointRunIdentity {
    fn parse(terminal_run_kind: String, matrix_path: Vec<String>) -> Result<Self, String> {
        let is_canonical_shard = terminal_run_kind
            .strip_prefix("shard-")
            .and_then(|value| value.split_once('/'))
            .and_then(|(index, count)| {
                Some((index.parse::<usize>().ok()?, count.parse::<usize>().ok()?))
            })
            .is_some_and(|(index, count)| {
                index >= 1
                    && index <= count
                    && format!("shard-{index}/{count}") == terminal_run_kind
            });
        let is_valid = match terminal_run_kind.as_str() {
            "full" if matrix_path.is_empty() => true,
            "matrix-filter-leaf" | "matrix-chunk-leaf" if !matrix_path.is_empty() => true,
            _ if is_canonical_shard && matrix_path.is_empty() => true,
            _ => false,
        };
        if !is_valid {
            return Err(format!(
                "noncanonical checkpoint terminal identity: run_kind={} matrix_path=[{}]",
                terminal_run_kind,
                matrix_path.join(", ")
            ));
        }

        Ok(Self {
            terminal_run_kind,
            matrix_path,
        })
    }

    fn full() -> Self {
        Self {
            terminal_run_kind: "full".to_string(),
            matrix_path: Vec::new(),
        }
    }

    fn shard(index: usize, count: usize) -> Result<Self, String> {
        Self::parse(format!("shard-{index}/{count}"), Vec::new())
    }

    fn matrix(node_kind: MatrixNodeKind, matrix_path: &[String]) -> Result<Self, String> {
        Self::parse(
            format!("matrix-{}", node_kind.as_str()),
            matrix_path.to_vec(),
        )
    }

    fn terminal_run_kind(&self) -> &str {
        &self.terminal_run_kind
    }

    fn matrix_path(&self) -> &[String] {
        &self.matrix_path
    }

    #[cfg(test)]
    fn admitted_by_test(terminal_run_kind: impl Into<String>, matrix_path: &[String]) -> Self {
        Self::parse(terminal_run_kind.into(), matrix_path.to_vec())
            .expect("test checkpoint identity should be canonical")
    }
}

#[derive(Deserialize)]
struct CheckpointRunIdentityWire {
    terminal_run_kind: String,
    matrix_path: Vec<String>,
}

impl<'de> Deserialize<'de> for CheckpointRunIdentity {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = CheckpointRunIdentityWire::deserialize(deserializer)?;
        Self::parse(wire.terminal_run_kind, wire.matrix_path).map_err(serde::de::Error::custom)
    }
}

