/// The owner of one non-passing Test262 case.
///
/// The unclassified closure bucket is deliberately not a [`ConformanceOwner`]. Keeping
/// it as a separate variant prevents `T26-unclassified` from leaking into the
/// repository's closed task registry while preserving the stable artifact
/// spelling at the serde boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum BacklogOwner {
    Task(ConformanceOwner),
    Unclassified,
}

impl BacklogOwner {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Task(task) => task.as_str(),
            Self::Unclassified => "T26-unclassified",
        }
    }
}

impl fmt::Display for BacklogOwner {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

impl std::str::FromStr for BacklogOwner {
    type Err = String;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        if text == Self::Unclassified.as_str() {
            return Ok(Self::Unclassified);
        }

        text.parse::<ConformanceOwner>()
            .map(Self::Task)
            .map_err(|err| err.to_string())
    }
}

impl Serialize for BacklogOwner {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        serializer.serialize_str(self.as_str())
    }
}

impl<'de> Deserialize<'de> for BacklogOwner {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let text = String::deserialize(deserializer)?;
        text.parse().map_err(serde::de::Error::custom)
    }
}

/// Stable semantic family used to group an assigned backlog record.
///
/// `unclassified` is intentionally absent: that category exists only in the
/// [`BacklogOwnership::Unclassified`] variant, so a task cannot accidentally
/// be paired with the closure bucket (or vice versa).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum BacklogDebtCategory {
    #[serde(rename = "annexb")]
    AnnexB,
    #[serde(rename = "dynamic-source")]
    DynamicSource,
    #[serde(rename = "infrastructure")]
    Infrastructure,
    #[serde(rename = "intl402")]
    Intl402,
    #[serde(rename = "module")]
    Module,
    #[serde(rename = "parser")]
    Parser,
    #[serde(rename = "semantic")]
    Semantic,
}

impl BacklogDebtCategory {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::AnnexB => "annexb",
            Self::DynamicSource => "dynamic-source",
            Self::Infrastructure => "infrastructure",
            Self::Intl402 => "intl402",
            Self::Module => "module",
            Self::Parser => "parser",
            Self::Semantic => "semantic",
        }
    }
}

impl fmt::Display for BacklogDebtCategory {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

impl std::str::FromStr for BacklogDebtCategory {
    type Err = String;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        match text {
            "annexb" => Ok(Self::AnnexB),
            "dynamic-source" => Ok(Self::DynamicSource),
            "infrastructure" => Ok(Self::Infrastructure),
            "intl402" => Ok(Self::Intl402),
            "module" => Ok(Self::Module),
            "parser" => Ok(Self::Parser),
            "semantic" => Ok(Self::Semantic),
            _ => Err(format!("unknown backlog debt category `{text}`")),
        }
    }
}

/// A valid pairing of a backlog owner and its semantic category.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum BacklogOwnership {
    Assigned {
        task: ConformanceOwner,
        category: BacklogDebtCategory,
    },
    Unclassified,
}

impl BacklogOwnership {
    pub const fn assigned(task: ConformanceOwner, category: BacklogDebtCategory) -> Self {
        Self::Assigned { task, category }
    }

    pub const fn owner(self) -> BacklogOwner {
        match self {
            Self::Assigned { task, .. } => BacklogOwner::Task(task),
            Self::Unclassified => BacklogOwner::Unclassified,
        }
    }

    pub const fn category(self) -> Option<BacklogDebtCategory> {
        match self {
            Self::Assigned { category, .. } => Some(category),
            Self::Unclassified => None,
        }
    }

    pub const fn category_str(self) -> &'static str {
        match self {
            Self::Assigned { category, .. } => category.as_str(),
            Self::Unclassified => "unclassified",
        }
    }

    fn parse(owner: BacklogOwner, category: &str) -> Result<Self, String> {
        match (owner, category) {
            (BacklogOwner::Unclassified, "unclassified") => Ok(Self::Unclassified),
            (BacklogOwner::Unclassified, _) => Err(format!(
                "{} must use debt category `unclassified`, not `{category}`",
                owner.as_str()
            )),
            (BacklogOwner::Task(_), "unclassified") => Err(format!(
                "task owner {} cannot use the unclassified debt category",
                owner.as_str()
            )),
            (BacklogOwner::Task(task), category) => category
                .parse::<BacklogDebtCategory>()
                .map(|category| Self::assigned(task, category)),
        }
    }
}

impl Serialize for BacklogOwnership {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        use serde::ser::SerializeStruct;

        let mut state = serializer.serialize_struct("BacklogOwnership", 2)?;
        state.serialize_field("owner_task_id", &self.owner())?;
        state.serialize_field("debt_category", self.category_str())?;
        state.end()
    }
}

impl<'de> Deserialize<'de> for BacklogOwnership {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        struct Wire {
            owner_task_id: BacklogOwner,
            debt_category: String,
        }

        let wire = Wire::deserialize(deserializer)?;
        Self::parse(wire.owner_task_id, &wire.debt_category).map_err(serde::de::Error::custom)
    }
}

