fn pinned_revisions(config: &SuiteConfig) -> PinnedRevisions {
    PinnedRevisions {
        ecma262: source_pins::ecma262_revision().to_string(),
        test262: suite_test262_pin(config),
    }
}

fn discover_suite(config: &SuiteConfig, filter: Option<&str>) -> Result<SuiteManifest, String> {
    suite_identity::owned_output_root(config)?;
    let test_root = config.suite_root.join("test");
    if !test_root.exists() {
        return Err(format!(
            "vendored Test262 suite not found at {}",
            test_root.display()
        ));
    }

    let requested_execution = match filter {
        Some(value) if value.contains(':') => Some(
            TestExecutionId::parse_wire_key(value)
                .map_err(|err| format!("invalid Test262 execution selector `{value}`: {err}"))?,
        ),
        Some(_) | None => None,
    };
    let filter = filter.map(|value| {
        let value = requested_execution
            .as_ref()
            .map_or(value, TestExecutionId::path);
        value
            .trim_start_matches("test/")
            .trim_end_matches('/')
            .to_string()
    });
    let boundary_filter = filter
        .as_deref()
        .map(|filter| test_root.join(filter))
        .is_some_and(|path| path.is_file() || path.is_dir());
    let mut cases = Vec::new();
    scan_tests(
        &test_root,
        &test_root,
        filter.as_deref(),
        boundary_filter,
        &mut cases,
    )?;
    if let Some(requested_execution) = &requested_execution {
        cases.retain(|case| &case.execution_id == requested_execution);
        if cases.len() != 1 {
            return Err(format!(
                "Test262 execution {} resolved to {} cases; expected exactly one",
                requested_execution,
                cases.len()
            ));
        }
    }
    cases.sort_by(|left, right| left.execution_id.cmp(&right.execution_id));

    let pinned_revisions = pinned_revisions(config);
    let manifest_filter = requested_execution
        .as_ref()
        .map(TestExecutionId::wire_key)
        .or_else(|| filter.clone());
    let manifest_hash = hash_manifest(&pinned_revisions, &cases, manifest_filter.as_deref());

    Ok(SuiteManifest {
        pinned_revisions,
        manifest_hash,
        filter: manifest_filter,
        cases,
    })
}

fn load_preludes(config: &SuiteConfig) -> Result<PreludeStore, String> {
    let mut store = PreludeStore::default();

    let (merged, host_ownership): (Option<Cow<'static, str>>, PreludeHostOwnership) =
        match &config.local_harness {
            LocalHarnessSource::None => (None, PreludeHostOwnership::None),
            LocalHarnessSource::EmbeddedSpecExec => (
                Some(Cow::Borrowed(include_str!(
                    "../assets/local-harness/spec-exec.js"
                ))),
                PreludeHostOwnership::EmbeddedSpecExecSta,
            ),
            LocalHarnessSource::EmbeddedWasmAot => (
                Some(Cow::Borrowed(include_str!(
                    "../assets/local-harness/wasm-aot.js"
                ))),
                PreludeHostOwnership::WasmAot(CompleteWasmAotHostPrelude::load_embedded()?),
            ),
            LocalHarnessSource::EmbeddedWasmAotHostOnly => (
                None,
                PreludeHostOwnership::WasmAot(CompleteWasmAotHostPrelude::load_embedded()?),
            ),
            LocalHarnessSource::File(path) => (
                Some(Cow::Owned(fs::read_to_string(path).map_err(|err| {
                    format!("failed to read local harness {}: {err}", path.display())
                })?)),
                PreludeHostOwnership::None,
            ),
        };
    if let Some(merged) = merged {
        for section in merged.split("///").skip(1) {
            let mut lines = section.lines();
            let Some(name) = lines.next() else {
                continue;
            };
            let key = name.trim().to_string();
            let mut body = lines.collect::<Vec<_>>().join("\n");
            body.push('\n');
            store.insert(key, body, PreludeOrigin::LocalMerged);
        }
    }

    let vendored_harness_root = config.suite_root.join("harness");
    if vendored_harness_root.exists() {
        let mut files = Vec::new();
        scan_harness_files(&vendored_harness_root, &vendored_harness_root, &mut files)?;
        files.sort();
        for (name, path) in files {
            if store.contains(&name) {
                continue;
            }
            let contents = fs::read_to_string(&path).map_err(|err| {
                format!("failed to read vendored harness {}: {err}", path.display())
            })?;
            store.insert(
                name,
                format!("{contents}\n"),
                PreludeOrigin::VendoredHarness,
            );
        }
    }

    if host_ownership != PreludeHostOwnership::None {
        for required_name in ["assert.js", "sta.js"] {
            if !store.contains(required_name) {
                return Err(format!(
                    "Test262 prelude profile {} requires named prelude `{required_name}`, but {} does not provide it",
                    config.local_harness,
                    config.suite_root.join("harness").display()
                ));
            }
        }
    }
    store.host_ownership = host_ownership;

    Ok(store)
}

fn resolve_declared_preludes<'a>(
    case: &TestCase,
    preludes: &'a PreludeStore,
) -> Result<Vec<&'a PreludeEntry>, String> {
    let mut names = BTreeSet::new();
    let mut resolved = Vec::new();
    for include in &case.includes {
        if include.is_empty() || !names.insert(include.as_str()) {
            continue;
        }
        let prelude = preludes.get(include).ok_or_else(|| {
            format!(
                "Test262 case {} declares missing prelude `{include}`",
                case.execution_id()
            )
        })?;
        resolved.push(prelude);
    }
    Ok(resolved)
}

fn materialize_test(case: &TestCase, preludes: &PreludeStore) -> Result<MaterializedTest, String> {
    let mode = case.execution_mode();
    if mode.is_raw() {
        return Ok(MaterializedTest {
            execution_id: case.execution_id.clone(),
            source: case.original_source.to_string(),
            module_prelude: None,
            used_preludes: Vec::new(),
            negative: case.negative.clone(),
            agent_prelude: None,
        });
    }

    let mut source = String::new();
    let mut used_preludes = Vec::new();
    let mut agent_prelude = None;

    let included_preludes = resolve_declared_preludes(case, preludes)?;
    let host_requirement = test262_host_requirement(case, &included_preludes);
    let assert_prelude = preludes.get("assert.js").ok_or_else(|| {
        format!(
            "Test262 case {} requires named prelude `assert.js`, but this prelude profile does not provide it",
            case.execution_id()
        )
    })?;
    let assert_needs_test262_error = assert_prelude.contents.contains("Test262Error");
    let needs_test262_error_preamble =
        assert_needs_test262_error || case_needs_test262_error_prelude(case);

    let (wasm_aot_host_source, required_sta_prelude) = match host_requirement {
        Test262HostRequirement::None => (None, None),
        Test262HostRequirement::Complete {
            realm,
            agent_worker,
        } => {
            let full_assert = assert_prelude;
            let host = match preludes.host_ownership {
                PreludeHostOwnership::None => {
                    return Err(format!(
                        "Test262 case {} requires the complete `$262` host, but this prelude profile owns no host",
                        case.execution_id()
                    ));
                }
                PreludeHostOwnership::EmbeddedSpecExecSta => None,
                PreludeHostOwnership::WasmAot(host) => Some(host.render(realm)),
            };
            let sta = preludes
                .get("sta.js")
                .expect("host-owning PreludeStore must contain the validated sta.js");
            if agent_worker == AgentWorkerRequirement::Required {
                let mut worker_prelude = String::new();
                if let Some(host) = &host {
                    worker_prelude.push_str(host);
                }
                worker_prelude.push_str(&full_assert.contents);
                worker_prelude.push_str(&sta.contents);
                agent_prelude = Some(worker_prelude);
            }
            (host, Some(sta))
        }
    };

    if let Some(host) = &wasm_aot_host_source {
        source.push_str(host);
    }
    source.push_str(&assert_prelude.contents);
    used_preludes.push((assert_prelude.name.clone(), assert_prelude.origin));
    if let Some(prelude) = required_sta_prelude {
        source.push_str(&prelude.contents);
        used_preludes.push((prelude.name.clone(), prelude.origin));
    } else if needs_test262_error_preamble {
        if let Some(prelude) = preludes
            .get("sta-preamble.js")
            .or_else(|| preludes.get("sta.js"))
        {
            source.push_str(&prelude.contents);
            used_preludes.push((prelude.name.clone(), prelude.origin));
        }
    }

    if case.flags.contains("async") {
        if let Some(prelude) = preludes.get("doneprintHandle.js") {
            source.push_str(&prelude.contents);
            source.push_str(TEST262_ASYNC_DONE_GUARD_PRELUDE);
            used_preludes.push((prelude.name.clone(), prelude.origin));
        }
    }

    for prelude in included_preludes {
        let include = prelude.name.as_str();
        if include == "atomicsHelper.js" {
            source.push_str(WASM_AOT_AGENT_TIMER_PRELUDE);
        }
        source.push_str(&prelude.contents);
        used_preludes.push((prelude.name.clone(), prelude.origin));
    }
    // Harness code has its own Script grammar and strictness. In particular,
    // a strict test must not make lenient harness direct eval strict.
    let module_prelude = Some(std::mem::take(&mut source));
    if mode.needs_strict_directive() {
        source.push_str("\"use strict\";\n");
    }
    source.push_str(&case.original_source);

    Ok(MaterializedTest {
        execution_id: case.execution_id.clone(),
        source,
        module_prelude,
        used_preludes,
        negative: case.negative.clone(),
        agent_prelude,
    })
}

#[cfg(test)]
const TEST_TYPED_ARRAY_PRELUDE_FNV1A: u64 = 0x34b9_2946_b531_1336;

#[cfg(test)]
const PROPERTY_HELPER_PRELUDE_FNV1A: u64 = 0x97bb_d214_0c48_a37e;

#[cfg(test)]
const LOCAL_ASSERT_PRELUDE_FNV1A: u64 = 0x9559_0b7f_7e59_fee1;

#[cfg(test)]
const LOCAL_PROPERTY_HELPER_PRELUDE_FNV1A: u64 = PROPERTY_HELPER_PRELUDE_FNV1A;

#[cfg(test)]
const IS_CONSTRUCTOR_PRELUDE_FNV1A: u64 = 0x5815_595f_f0a9_9c34;

#[cfg(test)]
const RESIZABLE_ARRAY_BUFFER_UTILS_PRELUDE_FNV1A: u64 = 0x6466_6602_9ee8_9d5d;

#[cfg(test)]
fn fnv1a_extend(mut hash: u64, bytes: &[u8]) -> u64 {
    for byte in bytes {
        hash = (hash ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

#[cfg(test)]
fn fnv1a(source: &str) -> u64 {
    fnv1a_extend(0xcbf2_9ce4_8422_2325, source.as_bytes())
}

#[cfg(test)]
fn test_case_contract_fingerprint(case: &TestCase) -> u64 {
    let mut hash = fnv1a_extend(0xcbf2_9ce4_8422_2325, case.path.as_bytes());
    hash = fnv1a_extend(hash, &[0]);
    for include in &case.includes {
        hash = fnv1a_extend(hash, include.as_bytes());
        hash = fnv1a_extend(hash, &[0]);
    }
    hash = fnv1a_extend(hash, &[u8::MAX]);
    fnv1a_extend(hash, case.original_source.as_bytes())
}

#[cfg(test)]
fn test_typed_array_prelude_matches_vendored_contract(prelude: &PreludeEntry) -> bool {
    if prelude.name != "testTypedArray.js" || prelude.origin != PreludeOrigin::VendoredHarness {
        return false;
    }

    let fingerprint = prelude
        .contents
        .bytes()
        .fold(0xcbf2_9ce4_8422_2325, |hash, byte| {
            (hash ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01b3)
        });
    if fingerprint != TEST_TYPED_ARRAY_PRELUDE_FNV1A {
        return false;
    }

    [
        "var typedArrayCtorArgFactories = [makePassthrough, makeArray, makeArrayLike];",
        "function testWithAllTypedArrayConstructors(f, constructors, includeArgFactories, excludeArgFactories) {",
        "for (var k = 0; k < ctorArgFactories.length; ++k) {",
        "var boundArgFactory = argFactory.bind(undefined, constructor);",
        "e.message += \" (Testing with \" + constructor.name + \" and \" + argFactory.name + \".)\";",
        "var ctors = constructors || [BigInt64Array, BigUint64Array];",
    ]
    .iter()
        .all(|fragment| prelude.contents.contains(fragment))
}

const TEST262_ASYNC_DONE_GUARD_PRELUDE: &str = r#"
var __scriptwTest262AsyncDone = { active: true, called: false };
var __scriptwTest262OriginalDONE = $DONE;
$DONE = function $DONE(error) {
  if (__scriptwTest262AsyncDone.called) {
    var duplicate = new Error('host harness async $DONE called multiple times');
    __scriptwTest262OriginalDONE(duplicate);
    throw duplicate;
  }
  __scriptwTest262AsyncDone.called = true;
  return __scriptwTest262OriginalDONE(error);
};
globalThis.$DONE = $DONE;
"#;

fn case_needs_test262_error_prelude(case: &TestCase) -> bool {
    case.original_source.contains("Test262Error") || case.original_source.contains("$DONOTEVALUATE")
}

fn test262_host_requirement(
    case: &TestCase,
    included_preludes: &[&PreludeEntry],
) -> Test262HostRequirement {
    let sources = std::iter::once(case.original_source.as_ref()).chain(
        included_preludes
            .iter()
            .map(|prelude| prelude.contents.as_str()),
    );
    let mut requires_host = false;
    let mut realm = WasmAotRealmActivation::Dormant;
    for source in sources {
        if !source.contains("$262") {
            continue;
        }
        requires_host = true;
        if source_may_use_wasm_aot_realm_host(source) {
            realm = WasmAotRealmActivation::Active;
        }
    }
    if !requires_host {
        return Test262HostRequirement::None;
    }
    let agent_worker = if case.original_source.contains("$262.agent.start(") {
        AgentWorkerRequirement::Required
    } else {
        AgentWorkerRequirement::None
    };
    Test262HostRequirement::Complete {
        realm,
        agent_worker,
    }
}

fn source_may_use_wasm_aot_realm_host(source: &str) -> bool {
    const NON_REALM_USES: [&str; 7] = [
        ".AbstractModuleSource",
        ".IsHTMLDDA",
        ".agent",
        ".destroy",
        ".detachArrayBuffer",
        ".gc",
        " || typeof $262.detachArrayBuffer",
    ];

    let mut remaining = source;
    while let Some(index) = remaining.find("$262") {
        let after_host = &remaining[index + "$262".len()..];
        let is_non_realm_use = NON_REALM_USES.iter().any(|member| {
            let Some(after_member) = after_host.strip_prefix(member) else {
                return false;
            };
            !after_member.chars().next().is_some_and(|character| {
                character == '_' || character == '$' || character.is_alphanumeric()
            })
        });
        if !is_non_realm_use {
            return true;
        }
        remaining = after_host;
    }
    false
}

fn run_shard(config: &SuiteConfig, run_config: RunConfig) -> Result<ShardSummary, String> {
    let discovered = discover_suite(config, run_config.filter.as_deref())?;
    let preludes = load_preludes(config)?;
    let cases = shard_cases(
        &discovered.cases,
        run_config.shard_index,
        run_config.shard_count,
    )?;
    let checkpoint_run_identity =
        CheckpointRunIdentity::shard(run_config.shard_index + 1, run_config.shard_count)?;
    let run_kind = checkpoint_run_identity.terminal_run_kind().to_string();
    let manifest = manifest_for_selected_cases(&discovered, cases, &run_kind)?;
    let results = execute_cases(
        config,
        &manifest,
        &preludes,
        &manifest.cases,
        &run_config,
        &checkpoint_run_identity,
        ResumeCheckpointLoadPolicy::RequireExact,
    )?;
    let summary = summarize_results(&results);

    let snapshot =
        snapshot_from_summary(&manifest, run_kind, &summary, run_config.execution_backend)?;
    validate_case_snapshot_contract(
        &snapshot,
        &manifest
            .cases
            .iter()
            .map(|case| case.execution_id.clone())
            .collect::<Vec<_>>(),
        CaseSetRequirement::Exact,
        "completed shard snapshot",
    )?;
    write_snapshot(config, &snapshot, &run_config.snapshot_name)?;

    Ok(ShardSummary {
        shard_index: run_config.shard_index,
        shard_count: run_config.shard_count,
        total: summary.total,
        passed: summary.passed,
        failures: summary.failures,
    })
}

/// A nonempty set of exact mode/path identities, never a prefix or skip list.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TestExecutionList {
    requested: BTreeSet<TestExecutionId>,
}

impl TestExecutionList {
    pub fn parse(source: &str) -> Result<Self, String> {
        let mut requested = BTreeSet::new();
        for (index, line) in source.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let id = TestExecutionId::parse_wire_key(line)
                .map_err(|error| format!("execution list line {}: {error}", index + 1))?;
            if !requested.insert(id) {
                return Err(format!("execution list line {} repeats {line}", index + 1));
            }
        }
        if requested.is_empty() {
            return Err("execution list must contain at least one exact identity".into());
        }
        Ok(Self { requested })
    }

    fn into_manifest(self, discovered: &SuiteManifest) -> Result<SuiteManifest, String> {
        let discovered_ids = discovered
            .cases
            .iter()
            .map(|case| &case.execution_id)
            .collect::<BTreeSet<_>>();
        let missing = self
            .requested
            .iter()
            .filter(|id| !discovered_ids.contains(id))
            .map(TestExecutionId::wire_key)
            .collect::<Vec<_>>();
        if !missing.is_empty() {
            return Err(format!(
                "execution list identities absent from the selected suite: {}",
                missing.join(", ")
            ));
        }
        let cases = discovered
            .cases
            .iter()
            .filter(|case| self.requested.contains(&case.execution_id))
            .cloned()
            .collect();
        manifest_for_selected_cases(discovered, cases, "execution-list")
    }
}

/// Execute an exact cohort through the normal supervised runner and snapshots.
fn run_execution_list(
    config: &SuiteConfig,
    run_config: RunConfig,
    executions: TestExecutionList,
) -> Result<RunSummary, String> {
    if run_config.filter.is_some()
        || run_config.shard_index != 0
        || run_config.shard_count != 1
        || run_config.max_matrix_nodes.is_some()
    {
        return Err(
            "execution-list runs cannot also select a filter, shard or matrix ceiling".into(),
        );
    }
    let discovered = discover_suite(config, None)?;
    let manifest = executions.into_manifest(&discovered)?;
    run_full_with_manifest(config, run_config, manifest)
}

fn manifest_for_selected_cases(
    discovered: &SuiteManifest,
    cases: Vec<TestCase>,
    selection: &str,
) -> Result<SuiteManifest, String> {
    let discovered_ids = discovered
        .cases
        .iter()
        .map(|case| &case.execution_id)
        .collect::<BTreeSet<_>>();
    if discovered_ids.len() != discovered.cases.len() {
        return Err("discovered Test262 manifest contains duplicate execution ids".to_string());
    }
    let selected_ids = cases
        .iter()
        .map(|case| &case.execution_id)
        .collect::<BTreeSet<_>>();
    if selected_ids.len() != cases.len() || !selected_ids.is_subset(&discovered_ids) {
        return Err(format!(
            "Test262 {selection} selection must contain unique executions from the discovered manifest"
        ));
    }

    let filter = format!(
        "{}#{selection}",
        discovered.filter.as_deref().unwrap_or("<all>")
    );
    Ok(SuiteManifest {
        pinned_revisions: discovered.pinned_revisions.clone(),
        manifest_hash: hash_manifest(&discovered.pinned_revisions, &cases, Some(&filter)),
        filter: Some(filter),
        cases,
    })
}

/// Executes the exact single case inside an already supervised worker process.
/// This entry is for executable owners implementing `test262 __case-worker`.
/// Normal conformance execution must use `run_full`, `run_shard` or the matrix.
#[doc(hidden)]
pub fn run_case_worker(config: SuiteConfig, run_config: RunConfig) -> Result<RunSummary, String> {
    run_case_worker_with_preludes(config, run_config, None)
}

// Only the sequential server supplies a frozen, immutable harness store. A
// one-shot worker keeps the existing per-invocation loading behavior.
fn run_case_worker_with_preludes(
    mut config: SuiteConfig,
    run_config: RunConfig,
    preludes: Option<&PreludeStore>,
) -> Result<RunSummary, String> {
    if run_config.resume
        || run_config.shard_index != 0
        || run_config.shard_count != 1
        || run_config.max_matrix_nodes.is_some()
        || config.worker_count != 1
    {
        return Err(
            "case worker requires one fresh unsharded execution and one worker thread".into(),
        );
    }
    let requested = TestExecutionId::parse_wire_key(
        run_config
            .filter
            .as_deref()
            .ok_or("case worker requires an exact execution id")?,
    )?;
    let manifest = discover_suite(&config, Some(&requested.wire_key()))?;
    if manifest.cases.len() != 1 || manifest.cases[0].execution_id != requested {
        return Err("case worker selection must match exactly one requested execution id".into());
    }
    config.execution_role = CaseExecutionRole::SingleCaseWorker(requested);
    config.case_runner_bin = None;
    match preludes {
        Some(preludes) => run_full_with_manifest_and_preludes(&config, run_config, manifest, preludes),
        None => run_full_with_manifest(&config, run_config, manifest),
    }
}

/// Implements the versioned private sequential case worker protocol. Normal
/// callers continue to use the supervised run/shard/matrix entry points.
#[doc(hidden)]
pub fn run_case_worker_server(config: SuiteConfig, run_config: RunConfig) -> Result<(), String> {
    case_worker_server::serve(config, run_config)
}

fn run_full(config: &SuiteConfig, run_config: RunConfig) -> Result<RunSummary, String> {
    let manifest = discover_suite(config, run_config.filter.as_deref())?;
    run_full_with_manifest(config, run_config, manifest)
}

fn run_full_with_manifest(
    config: &SuiteConfig,
    run_config: RunConfig,
    manifest: SuiteManifest,
) -> Result<RunSummary, String> {
    let preludes = load_preludes(config)?;
    run_full_with_manifest_and_preludes(config, run_config, manifest, &preludes)
}

fn run_full_with_manifest_and_preludes(
    config: &SuiteConfig,
    run_config: RunConfig,
    manifest: SuiteManifest,
    preludes: &PreludeStore,
) -> Result<RunSummary, String> {
    let checkpoint_run_identity = CheckpointRunIdentity::full();
    let results = execute_cases(
        config,
        &manifest,
        preludes,
        &manifest.cases,
        &run_config,
        &checkpoint_run_identity,
        ResumeCheckpointLoadPolicy::RequireExact,
    )?;
    let summary = summarize_results(&results);

    let snapshot = snapshot_from_summary(
        &manifest,
        "full".to_string(),
        &summary,
        run_config.execution_backend,
    )?;
    validate_case_snapshot_contract(
        &snapshot,
        &manifest
            .cases
            .iter()
            .map(|case| case.execution_id.clone())
            .collect::<Vec<_>>(),
        CaseSetRequirement::Exact,
        "completed full-run snapshot",
    )?;
    write_snapshot(config, &snapshot, &run_config.snapshot_name)?;

    Ok(summary)
}

fn run_top_level_matrix(
    config: &SuiteConfig,
    run_config: RunConfig,
) -> Result<AggregateRunSummary, String> {
    if run_config.max_matrix_nodes == Some(0) {
        return Err("max_matrix_nodes must be at least 1".to_string());
    }
    let nodes = load_or_build_run_matrix(config, run_config.execution_backend)?;
    let current_node_ids = nodes
        .iter()
        .map(|node| node.node_id.clone())
        .collect::<BTreeSet<_>>();
    let aggregate_manifest_hash = hash_matrix_nodes(&nodes, run_config.execution_backend);
    let aggregate_snapshot_name = format!("{}-aggregate", run_config.snapshot_name);
    let pinned_revisions = pinned_revisions(config);
    let low_ram_resume = run_config.resume && run_config.max_matrix_nodes == Some(1);
    let checkpoint_load_policy = match low_ram_resume {
        true => ResumeCheckpointLoadPolicy::TreatStaleEnvelopeAsAbsent,
        false => ResumeCheckpointLoadPolicy::RequireExact,
    };

    let mut entries = Vec::new();
    let mut completed_nodes = BTreeSet::new();
    if run_config.resume {
        let mut aggregate_entries = BTreeMap::new();
        if let Some(snapshot) = load_resume_aggregate_snapshot(
            config,
            &aggregate_snapshot_name,
            aggregate_manifest_hash,
            run_config.execution_backend,
            &pinned_revisions,
        )? {
            if snapshot.run_kind == "aggregate-matrix" {
                if low_ram_resume {
                    entries = snapshot
                        .aggregate_entries
                        .into_iter()
                        .filter(|entry| current_node_ids.contains(&entry.node_id))
                        .collect::<Vec<_>>();
                } else {
                    aggregate_entries = snapshot
                        .aggregate_entries
                        .iter()
                        .cloned()
                        .map(|entry| (entry.node_id.clone(), entry))
                        .collect::<BTreeMap<_, _>>();
                }
            }
        }

        if low_ram_resume {
            let rebuilt_entries = rebuild_resume_entries_from_node_snapshots(
                config,
                &run_config.snapshot_name,
                &nodes,
                run_config.execution_backend,
                &pinned_revisions,
                checkpoint_load_policy,
            )?;
            entries = rebuilt_entries;
            completed_nodes = entries
                .iter()
                .map(|entry| entry.node_id.clone())
                .collect::<BTreeSet<_>>();
        }

        for node in &nodes {
            if completed_nodes.contains(&node.node_id) {
                continue;
            }

            let loaded = if let Some(entry) = aggregate_entries.get(&node.node_id) {
                load_resume_matrix_node_summary(
                    config,
                    &run_config.snapshot_name,
                    node,
                    Some(entry),
                    run_config.execution_backend,
                    &pinned_revisions,
                )
            } else {
                load_resume_matrix_node_summary_for_node(
                    config,
                    &run_config.snapshot_name,
                    node,
                    run_config.execution_backend,
                    &pinned_revisions,
                )
            };
            let resumed = checkpoint_load_policy.resolve(loaded)?;

            if let Some(summary) = resumed {
                completed_nodes.insert(node.node_id.clone());
                entries.push(summary);
            }
        }

        if !entries.is_empty() {
            let aggregate = aggregate_from_entries(&entries);
            let aggregate_snapshot = aggregate_snapshot(
                &pinned_revisions,
                aggregate_manifest_hash,
                &aggregate,
                run_config.execution_backend,
                "aggregate-matrix",
                vec!["top-level".to_string()],
                completed_nodes.iter().cloned().collect(),
            )?;
            write_snapshot(config, &aggregate_snapshot, &aggregate_snapshot_name)?;
        }
    }

    let mut processed_nodes = 0usize;
    for node in &nodes {
        if completed_nodes.contains(&node.node_id) {
            continue;
        }

        entries.push(run_matrix_node(
            config,
            node,
            &run_config,
            checkpoint_load_policy,
        )?);
        completed_nodes.insert(node.node_id.clone());

        let aggregate = aggregate_from_entries(&entries);
        let aggregate_snapshot = aggregate_snapshot(
            &pinned_revisions,
            aggregate_manifest_hash,
            &aggregate,
            run_config.execution_backend,
            "aggregate-matrix",
            vec!["top-level".to_string()],
            completed_nodes.iter().cloned().collect(),
        )?;
        write_snapshot(config, &aggregate_snapshot, &aggregate_snapshot_name)?;

        processed_nodes += 1;
        if let Some(limit) = run_config.max_matrix_nodes {
            if processed_nodes >= limit {
                break;
            }
        }
    }

    Ok(aggregate_from_entries(&entries))
}

fn rebuild_resume_entries_from_node_snapshots(
    config: &SuiteConfig,
    snapshot_name: &str,
    nodes: &[RunMatrixNode],
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
    checkpoint_load_policy: ResumeCheckpointLoadPolicy,
) -> Result<Vec<TopLevelRunSummary>, String> {
    let mut entries = Vec::new();
    for node in nodes {
        let loaded = load_resume_matrix_node_summary_for_node(
            config,
            snapshot_name,
            node,
            expected_backend,
            expected_pinned,
        );
        if let Some(summary) = checkpoint_load_policy.resolve(loaded)? {
            entries.push(summary);
        }
    }
    Ok(entries)
}

/// Controls whether a stale but well-formed checkpoint is a hard mismatch or
/// absent work. Only the top-level low-RAM matrix flow selects the latter; all
/// direct, child, shard, full, and public node entry points require exact
/// evidence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResumeCheckpointLoadPolicy {
    RequireExact,
    TreatStaleEnvelopeAsAbsent,
}

impl ResumeCheckpointLoadPolicy {
    fn resolve<T>(
        self,
        loaded: Result<Option<T>, ResumeCheckpointLoadError>,
    ) -> Result<Option<T>, String> {
        match (self, loaded) {
            (Self::RequireExact, Ok(value)) | (Self::TreatStaleEnvelopeAsAbsent, Ok(value)) => {
                Ok(value)
            }
            (Self::RequireExact, Err(ResumeCheckpointLoadError::StaleEnvelope(err))) => {
                Err(err.to_string())
            }
            (Self::RequireExact, Err(ResumeCheckpointLoadError::Integrity(err))) => Err(err),
            (
                Self::TreatStaleEnvelopeAsAbsent,
                Err(ResumeCheckpointLoadError::StaleEnvelope(_)),
            ) => Ok(None),
            (Self::TreatStaleEnvelopeAsAbsent, Err(ResumeCheckpointLoadError::Integrity(err))) => {
                Err(err)
            }
        }
    }
}

/// A node file found at the canonical resume path either belongs to an older
/// run envelope or is corrupt evidence for the current one. Only the former is
/// ignorable throughout the top-level low-RAM resume flow; string-prefix
/// matching made body hash corruption look stale and silently dropped it.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ResumeCheckpointLoadError {
    StaleEnvelope(StaleCheckpointEnvelope),
    Integrity(String),
}

// Only run-envelope fields can be stale. Manifest/case hashes and compiler
// provenance deliberately have no variant here: their corruption is fatal.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StaleEnvelopeField {
    ExecutionBackend,
    MatrixStrategy,
    Ecma262Revision,
    Test262Revision,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResumeEnvelopeKind {
    Node,
    Checkpoint,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StaleCheckpointEnvelope {
    context: ResumeEnvelopeKind,
    field: StaleEnvelopeField,
    path: PathBuf,
    expected: String,
    actual: String,
}

impl fmt::Display for StaleCheckpointEnvelope {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let context = match self.context {
            ResumeEnvelopeKind::Node => "resume node snapshot",
            ResumeEnvelopeKind::Checkpoint => "resume checkpoint",
        };
        let field = match self.field {
            StaleEnvelopeField::ExecutionBackend => "execution_backend",
            StaleEnvelopeField::MatrixStrategy => "matrix_strategy_version",
            StaleEnvelopeField::Ecma262Revision => "ecma262 revision",
            StaleEnvelopeField::Test262Revision => "test262 revision",
        };
        let equivalent = match self.field {
            StaleEnvelopeField::Test262Revision => {
                " (or a pin whose vendored suite content verifies as identical)"
            }
            StaleEnvelopeField::ExecutionBackend
            | StaleEnvelopeField::MatrixStrategy
            | StaleEnvelopeField::Ecma262Revision => "",
        };
        write!(
            formatter,
            "{context} mismatch for {field} in {}: expected {}{equivalent}, found {}",
            self.path.display(),
            self.expected,
            self.actual
        )
    }
}

impl ResumeCheckpointLoadError {
    fn stale(
        context: ResumeEnvelopeKind,
        field: StaleEnvelopeField,
        path: &Path,
        expected: impl ToString,
        actual: impl ToString,
    ) -> Self {
        Self::StaleEnvelope(StaleCheckpointEnvelope {
            context,
            field,
            path: path.to_owned(),
            expected: expected.to_string(),
            actual: actual.to_string(),
        })
    }

    fn integrity(message: impl Into<String>) -> Self {
        Self::Integrity(message.into())
    }

    fn into_message(self) -> String {
        match self {
            Self::StaleEnvelope(reason) => reason.to_string(),
            Self::Integrity(message) => message,
        }
    }
}

impl fmt::Display for ResumeCheckpointLoadError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::StaleEnvelope(reason) => fmt::Display::fmt(reason, formatter),
            Self::Integrity(message) => formatter.write_str(message),
        }
    }
}

fn load_resume_matrix_node_summary_for_node(
    config: &SuiteConfig,
    snapshot_name: &str,
    node: &RunMatrixNode,
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
) -> Result<Option<TopLevelRunSummary>, ResumeCheckpointLoadError> {
    load_resume_matrix_node_summary(
        config,
        snapshot_name,
        node,
        None,
        expected_backend,
        expected_pinned,
    )
}

fn load_resume_matrix_node_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    node: &RunMatrixNode,
    expected_entry: Option<&TopLevelRunSummary>,
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
) -> Result<Option<TopLevelRunSummary>, ResumeCheckpointLoadError> {
    let manifest_hash = expected_entry.map_or_else(
        || matrix_node_manifest_hash(expected_pinned, node),
        |entry| entry.manifest_hash,
    );
    let node_snapshot_name = format!(
        "{}-{}",
        snapshot_name,
        sanitize_filter_for_snapshot(&node.node_id)
    );
    let path = config
        .snapshot_dir
        .join(format!("{}-{}.json", node_snapshot_name, manifest_hash));
    let exists = path.try_exists().map_err(|err| {
        ResumeCheckpointLoadError::integrity(format!(
            "failed to inspect resume node snapshot {}: {err}",
            path.display()
        ))
    })?;
    if !exists {
        return Ok(None);
    }

    let file = read_snapshot_file(&path).map_err(ResumeCheckpointLoadError::integrity)?;
    let case_requirement = validate_resume_node_snapshot(
        config,
        &file,
        &path,
        node,
        manifest_hash,
        expected_backend,
        expected_pinned,
        &CompilerProvenance::current().map_err(ResumeCheckpointLoadError::integrity)?,
    )?;
    let snapshot = snapshot_from_file(file).map_err(ResumeCheckpointLoadError::integrity)?;
    validate_case_snapshot_contract(
        &snapshot,
        &node.case_ids,
        case_requirement,
        &format!(
            "matrix node checkpoint integrity failure in {}",
            path.display()
        ),
    )
    .map_err(ResumeCheckpointLoadError::integrity)?;
    if snapshot.completed_test_ids.len() < node.total_cases {
        if expected_entry.is_some() {
            return Err(ResumeCheckpointLoadError::integrity(format!(
                "matrix node checkpoint integrity failure in {}: aggregate entry marks node {} complete, but its checkpoint contains {} of {} executions",
                path.display(),
                node.node_id,
                snapshot.completed_test_ids.len(),
                node.total_cases
            )));
        }
        return Ok(None);
    }
    let actual_entry = TopLevelRunSummary {
        node_id: node.node_id.clone(),
        node_kind: node.node_kind,
        filter: node.filter.clone(),
        matrix_path: node.matrix_path.clone(),
        total: snapshot.total,
        passed: snapshot.passed,
        failed: snapshot.total.saturating_sub(snapshot.passed),
        counts_per_kind: snapshot.counts_per_kind.clone(),
        counts_per_outcome: snapshot.counts_per_outcome.clone(),
        counts_per_origin: counts_per_origin(&snapshot.failures),
        manifest_hash: snapshot.manifest_hash,
    };
    validate_complete_node_contract(
        &snapshot,
        node,
        expected_entry.unwrap_or(&actual_entry),
        &path,
    )
    .map_err(ResumeCheckpointLoadError::integrity)?;
    Ok(Some(actual_entry))
}

fn validate_resume_node_snapshot(
    config: &SuiteConfig,
    file: &AdmittedSnapshot,
    path: &Path,
    node: &RunMatrixNode,
    expected_manifest_hash: u64,
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
    expected_compiler: &CompilerProvenance,
) -> Result<CaseSetRequirement, ResumeCheckpointLoadError> {
    file.require_compiler(expected_compiler, path)
        .map_err(ResumeCheckpointLoadError::integrity)?;
    if file.execution_backend != expected_backend.as_str() {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Node,
            StaleEnvelopeField::ExecutionBackend,
            &path,
            &expected_backend.as_str(),
            &file.execution_backend,
        ));
    }
    if file.matrix_strategy_version != MATRIX_STRATEGY_VERSION {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Node,
            StaleEnvelopeField::MatrixStrategy,
            &path,
            &MATRIX_STRATEGY_VERSION,
            &file.matrix_strategy_version,
        ));
    }
    if file.pinned_revisions.ecma262 != expected_pinned.ecma262 {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Node,
            StaleEnvelopeField::Ecma262Revision,
            &path,
            &expected_pinned.ecma262,
            &file.pinned_revisions.ecma262,
        ));
    }
    let recorded_pinned = PinnedRevisions {
        ecma262: file.pinned_revisions.ecma262.clone(),
        test262: file.pinned_revisions.test262.clone(),
    };
    if !test262_pins_equivalent(config, &recorded_pinned, expected_pinned) {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Node,
            StaleEnvelopeField::Test262Revision,
            &path,
            &expected_pinned.test262,
            &file.pinned_revisions.test262,
        ));
    }
    if file.manifest_hash != expected_manifest_hash {
        return Err(ResumeCheckpointLoadError::integrity(format!(
            "resume node snapshot integrity failure for manifest_hash in {}: filename/selection expects {}, body records {}",
            path.display(),
            expected_manifest_hash,
            file.manifest_hash
        )));
    }
    let recomputed_manifest_hash = matrix_node_manifest_hash(&recorded_pinned, node);
    if file.manifest_hash != recomputed_manifest_hash {
        return Err(ResumeCheckpointLoadError::integrity(format!(
            "resume node snapshot integrity failure for manifest_hash in {}: accepted recorded pins and exact node execution set recompute to {}, body records {}",
            path.display(),
            recomputed_manifest_hash,
            file.manifest_hash
        )));
    }
    let checkpoint_run_identity = CheckpointRunIdentity::matrix(node.node_kind, &node.matrix_path)
        .map_err(ResumeCheckpointLoadError::integrity)?;
    direct_snapshot_case_requirement(
        DirectSnapshotKind::ResumeCheckpoint,
        &checkpoint_run_identity,
        &file.run_kind,
        file.checkpoint_identity.value(),
        &file.matrix_path,
    )
    .map_err(|err| {
        ResumeCheckpointLoadError::integrity(format!(
            "matrix node checkpoint integrity failure in {}: {err}",
            path.display()
        ))
    })
}

fn classify_failure(
    test_id: TestExecutionId,
    kind: FailureKind,
    detail: impl Into<String>,
) -> FailureRecord {
    let detail = detail.into();
    let outcome = classify_failure_outcome(kind, &detail);
    let origin = failure_origin_for_kind(kind);
    classify_failure_with_outcome(test_id, kind, outcome, origin, detail)
}

/// Origin for callers that hold only a `FailureKind` and a message. The
/// message is never inspected; only the host-harness kind is an attribution.
fn failure_origin_for_kind(kind: FailureKind) -> FailureOrigin {
    match kind {
        FailureKind::HostHarness => FailureOrigin::LocalHarness,
        FailureKind::Parser
        | FailureKind::EarlyError
        | FailureKind::Lowering
        | FailureKind::Runtime
        | FailureKind::WasmBackend
        | FailureKind::Unsupported => FailureOrigin::Unknown,
    }
}

fn classify_failure_with_outcome(
    test_id: TestExecutionId,
    kind: FailureKind,
    outcome: OutcomeKind,
    origin: FailureOrigin,
    detail: String,
) -> FailureRecord {
    let detail = format!("[origin:{}] {detail}", origin.as_str());
    FailureRecord {
        test_path: test_id.path().to_string(),
        test_id,
        kind,
        outcome,
        origin,
        detail_hash: hash_detail(&detail),
        detail,
        duration_ms: None,
    }
}

fn write_snapshot(
    config: &SuiteConfig,
    snapshot: &ProgressSnapshot,
    snapshot_name: &str,
) -> Result<SnapshotPaths, String> {
    snapshot.provenance.require_running("snapshot writer")?;
    let json_path = config
        .snapshot_dir
        .join(format!("{snapshot_name}-{}.json", snapshot.manifest_hash));
    let txt_path = config
        .snapshot_dir
        .join(format!("{snapshot_name}-{}.txt", snapshot.manifest_hash));

    if json_path
        .try_exists()
        .map_err(|err| format!("cannot inspect snapshot {}: {err}", json_path.display()))?
    {
        read_snapshot_file(&json_path)?.require_running(&json_path, "snapshot replacement")?;
    } else if txt_path
        .try_exists()
        .map_err(|err| format!("cannot inspect summary {}: {err}", txt_path.display()))?
    {
        return Err(format!(
            "snapshot family {} has an unbound summary without its JSON identity; retain it and use a fresh snapshot name",
            txt_path.display()
        ));
    }
    fs::create_dir_all(&config.snapshot_dir).map_err(|err| {
        format!(
            "failed to create snapshot dir {}: {err}",
            config.snapshot_dir.display()
        )
    })?;

    // Publish each complete file by rename. JSON alone owns resume state;
    // interruption while preparing either replacement leaves valid JSON.
    let json = render_snapshot_json(snapshot);
    let text = render_human_summary(snapshot);
    snapshot_publication::write_snapshot_file(&json_path, json.as_bytes())
        .map_err(|err| format!("failed to write snapshot {}: {err}", json_path.display()))?;
    snapshot_publication::write_snapshot_file(&txt_path, text.as_bytes())
        .map_err(|err| format!("failed to write summary {}: {err}", txt_path.display()))?;

    Ok(SnapshotPaths {
        json_path,
        txt_path,
    })
}

fn hash_matrix_cache_key(
    pinned_revisions: &PinnedRevisions,
    execution_backend: ExecutionBackend,
) -> u64 {
    let mut hasher = DefaultHasher::new();
    SNAPSHOT_VERSION.hash(&mut hasher);
    MATRIX_STRATEGY_VERSION.hash(&mut hasher);
    execution_backend.as_str().hash(&mut hasher);
    pinned_revisions.ecma262.hash(&mut hasher);
    pinned_revisions.test262.hash(&mut hasher);
    TOP_LEVEL_FILTERS.hash(&mut hasher);
    MATRIX_SPLIT_FILTERS.hash(&mut hasher);
    MATRIX_RECURSION_THRESHOLD.hash(&mut hasher);
    MATRIX_CHUNK_SIZE.hash(&mut hasher);
    hasher.finish()
}

fn matrix_cache_path(
    config: &SuiteConfig,
    pinned_revisions: &PinnedRevisions,
    execution_backend: ExecutionBackend,
) -> PathBuf {
    let cache_hash = hash_matrix_cache_key(pinned_revisions, execution_backend);
    config.snapshot_dir.join(format!(
        "matrix-cache-{}-{cache_hash}.json",
        execution_backend.as_str()
    ))
}

fn load_cached_run_matrix(
    config: &SuiteConfig,
    pinned_revisions: &PinnedRevisions,
    execution_backend: ExecutionBackend,
) -> Result<Option<Vec<RunMatrixNode>>, String> {
    let path = matrix_cache_path(config, pinned_revisions, execution_backend);
    if !path.exists() {
        return Ok(None);
    }

    let file = fs::File::open(&path)
        .map_err(|err| format!("failed to open matrix cache {}: {err}", path.display()))?;
    let file = std::io::BufReader::new(file);
    let cache = serde_json::from_reader::<_, MatrixCacheFile>(file)
        .map_err(|err| format!("failed to parse matrix cache {}: {err}", path.display()))?;
    let artifact_kind = SnapshotArtifactKind::decode(cache.snapshot_version, cache.producer)
        .map_err(|err| format!("invalid matrix cache schema in {}: {err}", path.display()))?;
    if !artifact_kind.is_current() {
        return Ok(None);
    }
    if cache.matrix_strategy_version != MATRIX_STRATEGY_VERSION
        || cache.execution_backend != execution_backend.as_str()
        || cache.pinned_revisions.ecma262 != pinned_revisions.ecma262
        || cache.pinned_revisions.test262 != pinned_revisions.test262
    {
        return Ok(None);
    }

    Ok(Some(cache.nodes))
}

fn write_run_matrix_cache(
    config: &SuiteConfig,
    pinned_revisions: &PinnedRevisions,
    execution_backend: ExecutionBackend,
    nodes: &[RunMatrixNode],
) -> Result<(), String> {
    fs::create_dir_all(&config.snapshot_dir).map_err(|err| {
        format!(
            "failed to create matrix cache dir {}: {err}",
            config.snapshot_dir.display()
        )
    })?;
    let path = matrix_cache_path(config, pinned_revisions, execution_backend);
    let unique_suffix = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    let temp_path = config.snapshot_dir.join(format!(
        ".{}.tmp-{}-{unique_suffix}",
        path.file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("matrix-cache"),
        std::process::id(),
    ));
    let file = fs::File::create(&temp_path).map_err(|err| {
        format!(
            "failed to create matrix cache temp file {}: {err}",
            temp_path.display()
        )
    })?;
    let file = std::io::BufWriter::new(file);
    let cache = MatrixCacheFile {
        snapshot_version: SNAPSHOT_VERSION,
        producer: Some(ArtifactProducer::CURRENT),
        matrix_strategy_version: MATRIX_STRATEGY_VERSION,
        execution_backend: execution_backend.as_str().to_string(),
        pinned_revisions: SnapshotPinnedRevisions {
            ecma262: pinned_revisions.ecma262.clone(),
            test262: pinned_revisions.test262.clone(),
        },
        nodes: nodes.to_vec(),
    };
    serde_json::to_writer_pretty(file, &cache).map_err(|err| {
        format!(
            "failed to write matrix cache temp file {}: {err}",
            temp_path.display()
        )
    })?;
    fs::rename(&temp_path, &path).map_err(|err| {
        format!(
            "failed to finalize matrix cache {} from {}: {err}",
            path.display(),
            temp_path.display()
        )
    })
}

fn build_run_matrix_uncached(config: &SuiteConfig) -> Result<Vec<RunMatrixNode>, String> {
    let mut nodes = Vec::new();
    for root in TOP_LEVEL_FILTERS {
        let manifest = discover_suite(config, Some(root))?;
        nodes.extend(build_matrix_nodes_for_root(
            root,
            &manifest.cases,
            MATRIX_RECURSION_THRESHOLD,
            MATRIX_CHUNK_SIZE,
        ));
    }
    nodes.sort_by(|left, right| left.node_id.cmp(&right.node_id));
    Ok(nodes)
}

fn load_or_build_run_matrix(
    config: &SuiteConfig,
    execution_backend: ExecutionBackend,
) -> Result<Vec<RunMatrixNode>, String> {
    let pinned = pinned_revisions(config);
    if let Some(nodes) = load_cached_run_matrix(config, &pinned, execution_backend)? {
        return Ok(nodes);
    }
    let nodes = build_run_matrix_uncached(config)?;
    write_run_matrix_cache(config, &pinned, execution_backend, &nodes)?;
    Ok(nodes)
}

fn build_run_matrix(config: &SuiteConfig) -> Result<Vec<RunMatrixNode>, String> {
    build_run_matrix_uncached(config)
}

fn select_run_matrix_node<'a>(
    nodes: &'a [RunMatrixNode],
    node_selector: &str,
) -> Result<&'a RunMatrixNode, String> {
    let matching_nodes = nodes
        .iter()
        .filter(|node| node.node_id == node_selector || node.filter == node_selector)
        .collect::<Vec<_>>();
    match matching_nodes.as_slice() {
        [node] => Ok(*node),
        [] => Err(format!(
            "matrix node selector {node_selector} does not identify an executable leaf; use an exact node_id or leaf filter from the run matrix"
        )),
        _ => Err(format!(
            "matrix node selector {node_selector} is ambiguous; use an exact node_id from the run matrix"
        )),
    }
}

fn run_selected_matrix_node(
    config: &SuiteConfig,
    node_selector: &str,
    run_config: RunConfig,
) -> Result<RunSummary, String> {
    let nodes = load_or_build_run_matrix(config, run_config.execution_backend)?;
    let node = select_run_matrix_node(&nodes, node_selector)?;
    let (_, summary) = execute_matrix_node(
        config,
        node,
        &run_config,
        ResumeCheckpointLoadPolicy::RequireExact,
    )?;
    Ok(summary)
}

fn group_cases_by_segment(
    cases: &[TestCase],
    segment_index: usize,
) -> BTreeMap<String, Vec<TestCase>> {
    let mut groups = BTreeMap::<String, Vec<TestCase>>::new();
    for case in cases {
        let segments = case.path.split('/').collect::<Vec<_>>();
        let Some(segment) = segments.get(segment_index) else {
            continue;
        };
        groups
            .entry((*segment).to_string())
            .or_default()
            .push(case.clone());
    }
    groups
}

fn group_cases_by_directory_segment(
    cases: &[TestCase],
    segment_index: usize,
) -> BTreeMap<String, Vec<TestCase>> {
    let mut groups = BTreeMap::<String, Vec<TestCase>>::new();
    for case in cases {
        let segments = case.path.split('/').collect::<Vec<_>>();
        if segments.len() <= segment_index + 1 {
            continue;
        }
        let Some(segment) = segments.get(segment_index) else {
            continue;
        };
        groups
            .entry((*segment).to_string())
            .or_default()
            .push(case.clone());
    }
    groups
}

fn build_matrix_nodes_for_root(
    root: &str,
    cases: &[TestCase],
    recursion_threshold: usize,
    chunk_size: usize,
) -> Vec<RunMatrixNode> {
    let filter = root.to_string();
    let matrix_path = vec![filter.clone()];
    if !MATRIX_SPLIT_FILTERS.contains(&root) || cases.is_empty() {
        let mut ordered = cases.to_vec();
        ordered.sort_by(|left, right| left.execution_id.cmp(&right.execution_id));
        return vec![RunMatrixNode {
            node_id: filter.clone(),
            node_kind: MatrixNodeKind::FilterLeaf,
            filter,
            matrix_path,
            total_cases: ordered.len(),
            case_ids: ordered.into_iter().map(|case| case.execution_id).collect(),
        }];
    }

    let child_groups = group_cases_by_segment(cases, 1);
    if child_groups.is_empty() {
        return finalize_matrix_nodes(
            filter,
            matrix_path,
            cases.to_vec(),
            recursion_threshold,
            chunk_size,
        );
    }

    let mut nodes = Vec::new();
    for (child, child_cases) in child_groups {
        let child_filter = format!("{root}/{child}");
        let child_path = vec![root.to_string(), child.clone()];
        if child_cases.len() > recursion_threshold {
            let grandchild_groups = group_cases_by_directory_segment(&child_cases, 2);
            if !grandchild_groups.is_empty() {
                let grandchild_case_ids = grandchild_groups
                    .values()
                    .flat_map(|group| group.iter().map(|case| case.execution_id.clone()))
                    .collect::<BTreeSet<_>>();
                let residual_cases = child_cases
                    .iter()
                    .filter(|case| !grandchild_case_ids.contains(&case.execution_id))
                    .cloned()
                    .collect::<Vec<_>>();
                if !residual_cases.is_empty() {
                    nodes.extend(finalize_matrix_nodes(
                        child_filter.clone(),
                        child_path.clone(),
                        residual_cases,
                        recursion_threshold,
                        chunk_size,
                    ));
                }
                for (grandchild, grandchild_cases) in grandchild_groups {
                    nodes.extend(finalize_matrix_nodes(
                        format!("{child_filter}/{grandchild}"),
                        vec![root.to_string(), child.clone(), grandchild],
                        grandchild_cases,
                        recursion_threshold,
                        chunk_size,
                    ));
                }
                continue;
            }
        }
        nodes.extend(finalize_matrix_nodes(
            child_filter,
            child_path,
            child_cases,
            recursion_threshold,
            chunk_size,
        ));
    }
    nodes
}

fn finalize_matrix_nodes(
    filter: String,
    matrix_path: Vec<String>,
    mut cases: Vec<TestCase>,
    recursion_threshold: usize,
    chunk_size: usize,
) -> Vec<RunMatrixNode> {
    cases.sort_by(|left, right| left.execution_id.cmp(&right.execution_id));
    if cases.len() > recursion_threshold {
        let total_chunks = cases.len().div_ceil(chunk_size);
        return cases
            .chunks(chunk_size)
            .enumerate()
            .map(|(index, chunk)| {
                let node_id = format!(
                    "{filter}@chunk-{chunk_index:04}-of-{total_chunks:04}",
                    chunk_index = index + 1
                );
                RunMatrixNode {
                    node_id,
                    node_kind: MatrixNodeKind::ChunkLeaf,
                    filter: filter.clone(),
                    matrix_path: matrix_path.clone(),
                    total_cases: chunk.len(),
                    case_ids: chunk.iter().map(|case| case.execution_id.clone()).collect(),
                }
            })
            .collect();
    }

    vec![RunMatrixNode {
        node_id: filter.clone(),
        node_kind: MatrixNodeKind::FilterLeaf,
        filter,
        matrix_path,
        total_cases: cases.len(),
        case_ids: cases.into_iter().map(|case| case.execution_id).collect(),
    }]
}

fn aggregate_from_entries(entries: &[TopLevelRunSummary]) -> AggregateRunSummary {
    let mut counts_per_kind = BTreeMap::new();
    let mut counts_per_outcome = empty_outcome_counts();
    let mut counts_per_origin = BTreeMap::new();
    for kind in FailureKind::ALL {
        counts_per_kind.insert(kind, 0);
    }
    for origin in FailureOrigin::ALL {
        counts_per_origin.insert(origin, 0);
    }

    let mut total = 0;
    let mut passed = 0;
    let mut ordered_entries = entries.to_vec();
    ordered_entries.sort_by(|left, right| left.node_id.cmp(&right.node_id));
    for entry in &ordered_entries {
        total += entry.total;
        passed += entry.passed;
        for kind in FailureKind::ALL {
            *counts_per_kind.entry(kind).or_insert(0) +=
                entry.counts_per_kind.get(&kind).copied().unwrap_or(0);
        }
        for outcome in OutcomeKind::ALL {
            *counts_per_outcome.entry(outcome).or_insert(0) +=
                entry.counts_per_outcome.get(&outcome).copied().unwrap_or(0);
        }
        for origin in FailureOrigin::ALL {
            *counts_per_origin.entry(origin).or_insert(0) +=
                entry.counts_per_origin.get(&origin).copied().unwrap_or(0);
        }
    }

    AggregateRunSummary {
        total,
        passed,
        failed: total.saturating_sub(passed),
        counts_per_kind,
        counts_per_outcome,
        counts_per_origin,
        entries: ordered_entries,
    }
}

fn hash_matrix_nodes(nodes: &[RunMatrixNode], execution_backend: ExecutionBackend) -> u64 {
    let mut hasher = DefaultHasher::new();
    MATRIX_STRATEGY_VERSION.hash(&mut hasher);
    execution_backend.as_str().hash(&mut hasher);
    for node in nodes {
        node.node_id.hash(&mut hasher);
        node.node_kind.hash(&mut hasher);
        node.filter.hash(&mut hasher);
        node.matrix_path.hash(&mut hasher);
        node.total_cases.hash(&mut hasher);
        node.case_ids.hash(&mut hasher);
    }
    hasher.finish()
}

fn sanitize_filter_for_snapshot(filter: &str) -> String {
    filter.replace('/', "_")
}

fn validate_manifest_execution_set(
    manifest: &SuiteManifest,
    cases: &[TestCase],
) -> Result<(), String> {
    let manifest_ids = manifest
        .cases
        .iter()
        .map(|case| &case.execution_id)
        .collect::<BTreeSet<_>>();
    let selected_ids = cases
        .iter()
        .map(|case| &case.execution_id)
        .collect::<BTreeSet<_>>();
    if manifest_ids.len() != manifest.cases.len() {
        return Err("Test262 manifest contains duplicate execution ids".to_string());
    }
    if selected_ids.len() != cases.len() {
        return Err("Test262 execution selection contains duplicate ids".to_string());
    }
    if selected_ids != manifest_ids {
        return Err(
            "Test262 execution selection does not exactly match its selected manifest".to_string(),
        );
    }
    Ok(())
}

fn execute_cases(
    config: &SuiteConfig,
    manifest: &SuiteManifest,
    preludes: &PreludeStore,
    cases: &[TestCase],
    run_config: &RunConfig,
    checkpoint_run_identity: &CheckpointRunIdentity,
    checkpoint_load_policy: ResumeCheckpointLoadPolicy,
) -> Result<Vec<TestResult>, String> {
    install_test262_panic_hook();
    validate_manifest_execution_set(manifest, cases)?;

    let previous = if run_config.resume {
        load_previous_snapshot(
            config,
            &run_config.snapshot_name,
            ResumeCheckpointIdentity::for_resume(
                manifest,
                run_config,
                checkpoint_run_identity.clone(),
            ),
            checkpoint_load_policy,
        )?
    } else {
        None
    };

    let mut completed = BTreeMap::new();
    if let Some(snapshot) = previous {
        let recorded_durations: BTreeMap<_, _> = snapshot.slowest_tests.into_iter().collect();
        for failure in snapshot.failures {
            let duration_ms = failure
                .duration_ms
                .or_else(|| recorded_durations.get(&failure.test_id).copied());
            completed.insert(
                failure.test_id.clone(),
                TestResult {
                    test_id: failure.test_id.clone(),
                    status: TestStatus::Failed(failure),
                    duration_ms,
                },
            );
        }
        for test_id in snapshot.completed_test_ids {
            let duration_ms = recorded_durations.get(&test_id).copied();
            completed.entry(test_id.clone()).or_insert(TestResult {
                test_id,
                status: TestStatus::Passed,
                duration_ms,
            });
        }
    }

    // The attempt journal is opened before anything is selected to run, and
    // charged before anything is scheduled, so that a case which killed the
    // previous process is accounted for even on a run that turns out to have
    // nothing left to do.
    let journal = AttemptJournal::open(
        attempt_journal_path(config, &run_config.snapshot_name, manifest.manifest_hash),
        run_config.resume,
        CrashStrikeLimit::DEFAULT,
        attempt_journal_identity(manifest, run_config)?,
    );
    let suspects = journal.charge_strikes_for_survivors()?;
    for suspect in &suspects {
        // Named on the same stream as `test262 checkpoint: N/M cases`. The
        // sweep log that motivated this module named no case at all, which is
        // why identifying the batch-4 poison case needed a snapshot diff.
        eprintln!(
            "test262 attempt journal: {} was in flight when a previous process died (strike {} of {})",
            suspect.test_id,
            suspect.strikes,
            journal.limit()
        );
    }

    let remaining = cases
        .iter()
        .filter(|case| !completed.contains_key(&case.execution_id))
        .cloned()
        .collect::<Vec<_>>();
    let remaining = if run_config.execution_backend == ExecutionBackend::WasmAot {
        schedule_cases_for_lifo_queue(remaining, |case| {
            wasm_aot_case_should_run_before_cache_misses(case, preludes)
        })
    } else {
        remaining
    };

    if remaining.is_empty() {
        // Nothing to attempt is a clean exit, so the journal goes with it —
        // otherwise a completed node keeps its `.attempts` file (and every
        // strike charged during it) for the next run at the same
        // `(snapshot_name, manifest_hash)` pair to inherit.
        journal.discard()?;
        let mut existing = completed.into_values().collect::<Vec<_>>();
        existing.sort_by(|left, right| left.test_id.cmp(&right.test_id));
        return Ok(existing);
    }

    let dispatch = CaseExecutionDispatch::admit(config, &remaining)?;

    // Resume mode used to run this loop fully single-threaded (ignoring
    // --threads / worker_count), which made resumed low-RAM matrix runs far
    // slower than fresh ones. It now shares the same worker pool as the
    // non-resume path; `resume` only controls which cases were skipped above.
    let previously_completed: Vec<TestResult> = completed.into_values().collect();

    let results = Arc::new(Mutex::new(Vec::new()));
    // `NonZeroUsize`, not `usize`, and the reason is the failure this batch is
    // about: a phase whose worker count is zero spawns no workers, its queue is
    // never drained, and every case in it disappears from `results` without a
    // record. That is a silent skip, which AGENTS.md bans outright. The `max(1)`
    // below already guaranteed it at run time; carrying the guarantee in the
    // type means `plan_run_phases` cannot hand a phase back with no way to run
    // it, and the literal `1` it uses for the serial suspect phase has to say so.
    let worker_count = NonZeroUsize::new(config.worker_count.max(1).min(cases.len().max(1)))
        .expect("worker count is clamped to at least 1 on the line above");
    // Guarded by the same mutex as `results` so the "did we cross a
    // checkpoint boundary" decision is race-safe: the length check happens
    // while still holding the lock that guards pushes into `results`.
    let checkpoint_error: Mutex<Option<String>> = Mutex::new(None);
    // An `admit` write that fails means a case would be attempted with no
    // durable record, so it fails the run rather than degrading it silently. A
    // failed `retire` is deliberately NOT fatal — see the retire arm below.
    let journal_error: Mutex<Option<String>> = Mutex::new(None);
    // Workers can finish later checkpoints before earlier workers finish
    // serializing theirs. Serialize checkpoint writes and retain the largest
    // completed count so an older snapshot can never clobber newer progress.
    let last_checkpoint_count = Mutex::new(0usize);

    // Usually one phase over everything. Two only when a previous death left
    // more than one case in flight, in which case the suspects run serially
    // first so the next death names exactly one of them.
    for phase in plan_run_phases(&suspects, remaining, worker_count) {
        let phase_worker_count = phase.worker_count().get();
        let queue = Arc::new(Mutex::new(phase.into_queue()));
        thread::scope(|scope| {
            for worker_slot in 0..phase_worker_count {
                let queue = Arc::clone(&queue);
                let results = Arc::clone(&results);
                let preludes = preludes.clone();
                let worker_config = config.clone();
                let dispatch = dispatch.clone();
                let worker_run_config = RunConfig {
                    filter: run_config.filter.clone(),
                    shard_index: 0,
                    shard_count: 1,
                    resume: false,
                    snapshot_name: String::new(),
                    execution_backend: run_config.execution_backend,
                    max_matrix_nodes: None,
                };
                let previously_completed = &previously_completed;
                let checkpoint_error = &checkpoint_error;
                let journal_error = &journal_error;
                let last_checkpoint_count = &last_checkpoint_count;
                let journal = &journal;
                thread::Builder::new()
                    .stack_size(TEST262_WORKER_STACK_SIZE)
                    .spawn_scoped(scope, move || {
                      let mut session = case_worker_server::Worker::default();
                      loop {
                        let maybe_case = {
                            let mut guard = queue.lock().expect("queue mutex poisoned");
                            guard.pop()
                        };
                        let Some(queued) = maybe_case else {
                            break;
                        };

                        // The only way to turn a queue pop into a runnable
                        // `TestCase`. It writes the durable in-flight record
                        // first, so a process death from here on is
                        // attributable to exactly this case.
                        let admission = match journal.admit(worker_slot, queued) {
                            Ok(admission) => admission,
                            Err(err) => {
                                let mut error_guard =
                                    journal_error.lock().expect("journal error mutex poisoned");
                                if error_guard.is_none() {
                                    *error_guard = Some(err);
                                }
                                break;
                            }
                        };

                        let result = match admission {
                            CaseAdmission::Run(admitted) => {
                                let admitted_path = admitted.case().path.clone();
                                let result = run_case_entry_with_dispatch(
                                    &dispatch,
                                    &mut session,
                                    &worker_config,
                                    &preludes,
                                    admitted,
                                    &worker_run_config,
                                );
                                // `run_case_entry` returns `TestResult`, not
                                // `Result<TestResult, _>`: it catches unwinding
                                // panics itself and turns them into a failure
                                // record. There is therefore no path from the
                                // line above to the line below that skips the
                                // retire, which is what makes a surviving
                                // journal entry mean "the process died" — a
                                // fact about the signature rather than about a
                                // test.
                                if let Err(err) = journal.retire(worker_slot) {
                                    // Loud, but NOT fatal, and the asymmetry
                                    // with `admit` above is deliberate. A
                                    // stale in-flight entry self-heals: the
                                    // next `admit` for this slot drops it, and
                                    // at worst it costs one bogus strike,
                                    // which a later completion now forgives.
                                    // Failing the run instead would let a full
                                    // `--snapshot-dir` produce a deterministic
                                    // non-zero exit on every supervisor
                                    // attempt — burning the whole retry budget
                                    // on a diagnostic subsystem, which is the
                                    // exact failure shape this module exists
                                    // to end.
                                    eprintln!(
                                        "test262 attempt journal: could not retire the entry for {} ({err}); attribution for this node is degraded but the run continues. If this repeats, delete the node's `.attempts` file in the snapshot directory and check for a full disk.",
                                        admitted_path
                                    );
                                }
                                result
                            }
                            CaseAdmission::Quarantined { test_id, strikes } => {
                                eprintln!(
                                    "test262 quarantine: {test_id} was in flight for {strikes} process death(s); recorded as outcome Crash and not run"
                                );
                                TestResult {
                                    test_id: test_id.clone(),
                                    status: TestStatus::Failed(quarantined_case_failure(
                                        test_id, strikes,
                                    )),
                                    duration_ms: None,
                                }
                            }
                        };

                        let checkpoint_snapshot = {
                            let mut guard = results.lock().expect("results mutex poisoned");
                            guard.push(result);
                            if guard.len() % RESUME_CASE_CHECKPOINT_INTERVAL == 0 {
                                let mut snapshot_results = previously_completed.clone();
                                snapshot_results.extend(guard.iter().cloned());
                                Some((snapshot_results.len(), snapshot_results))
                            } else {
                                None
                            }
                        };

                        if let Some((completed_count, mut snapshot_results)) = checkpoint_snapshot {
                            snapshot_results
                                .sort_by(|left, right| left.test_id.cmp(&right.test_id));
                            let mut last_written = last_checkpoint_count
                                .lock()
                                .expect("checkpoint count mutex poisoned");
                            if completed_count <= *last_written {
                                continue;
                            }
                            match write_resume_case_checkpoint(
                                &worker_config,
                                manifest,
                                &snapshot_results,
                                run_config,
                                checkpoint_run_identity,
                            ) {
                                Ok(()) => {
                                    *last_written = completed_count;
                                    eprintln!(
                                        "test262 checkpoint: {completed_count}/{} cases",
                                        cases.len()
                                    );
                                }
                                Err(err) => {
                                    let mut error_guard = checkpoint_error
                                        .lock()
                                        .expect("checkpoint error mutex poisoned");
                                    if error_guard.is_none() {
                                        *error_guard = Some(err);
                                    }
                                }
                            }
                        }
                      }
                      if let Err(err) = session.retire() {
                          let mut error_guard = checkpoint_error
                              .lock()
                              .expect("checkpoint error mutex poisoned");
                          if error_guard.is_none() {
                              *error_guard = Some(err);
                          }
                      }
                    })
                    .expect("worker thread should spawn");
            }
        });

        if journal_error
            .lock()
            .expect("journal error mutex poisoned")
            .is_some()
        {
            break;
        }
    }

    if let Some(err) = journal_error
        .into_inner()
        .expect("journal error mutex poisoned")
    {
        return Err(err);
    }

    if let Some(err) = checkpoint_error
        .into_inner()
        .expect("checkpoint error mutex poisoned")
    {
        return Err(err);
    }

    let mut all_results = previously_completed;
    all_results.extend(results.lock().expect("results mutex poisoned").clone());
    all_results.sort_by(|left, right| left.test_id.cmp(&right.test_id));

    // Always write a final checkpoint on a normal (non-interrupted) exit so
    // resume runs never lose completed work to the checkpoint interval, even
    // when the last worker's write happened before its case count crossed a
    // boundary.
    if run_config.resume {
        write_resume_case_checkpoint(
            config,
            manifest,
            &all_results,
            run_config,
            checkpoint_run_identity,
        )?;
    }

    // Last, and only on the success path: this run exited cleanly, so nothing
    // in the journal describes a death and nothing in it should survive into a
    // later run at the same `(snapshot_name, manifest_hash)` pair.
    journal.discard()?;

    Ok(all_results)
}

fn schedule_cases_for_lifo_queue(
    cases: Vec<TestCase>,
    mut should_run_first: impl FnMut(&TestCase) -> bool,
) -> Vec<TestCase> {
    let (priority_cases, mut deferred_cases): (Vec<_>, Vec<_>) =
        cases.into_iter().partition(|case| should_run_first(case));
    // Workers pop from the tail, so priority cases must be appended last.
    deferred_cases.extend(priority_cases);
    deferred_cases
}

fn wasm_aot_case_should_run_before_cache_misses(case: &TestCase, preludes: &PreludeStore) -> bool {
    if case_has_compile_only_negative(case) {
        return true;
    }

    let Ok(materialized) = materialize_test(case, preludes) else {
        return false;
    };
    let compile_options = compile_options_for_materialized_case(case, &materialized);
    if materialized.execution_mode().is_module() {
        wasm_aot_module_is_cached(&materialized.source, &compile_options)
    } else {
        wasm_aot_script_is_cached(&materialized.source, &compile_options)
    }
}

impl NegativePhase {
    /// Is this a rejection the compiler must produce **without executing user
    /// code**?
    ///
    /// `resolution` belongs here: 16.2.1.5 `InnerModuleLinking` /
    /// 16.2.1.6.4 `ResolveExport` fail before any module body evaluates, and an
    /// AOT compiler decides them at compile time. Reporting it as a runtime
    /// negative sent the case down the `detail.contains(&negative.error_type)`
    /// fallback against a message like `module ./dep.js does not export nope`,
    /// which contains no error name at all.
    const fn is_compile_only(self) -> bool {
        match self {
            Self::Parse | Self::Early | Self::Resolution => true,
            Self::Runtime => false,
        }
    }

    /// The failure family a mismatch is filed under.
    const fn failure_kind(self) -> FailureKind {
        match self {
            Self::Parse => FailureKind::Parser,
            // `resolution` negatives are module link failures, which this
            // compiler reports at compile time alongside early errors.
            Self::Early | Self::Resolution => FailureKind::EarlyError,
            Self::Runtime => FailureKind::Runtime,
        }
    }
}

fn case_has_compile_only_negative(case: &TestCase) -> bool {
    case.negative
        .as_ref()
        .is_some_and(|negative| negative.phase.is_compile_only())
}

fn language_features_for_case(case: &TestCase) -> scriptw_engine::LanguageFeaturePolicy {
    let mut policy = scriptw_engine::LanguageFeaturePolicy::default();
    if case.features.contains("nonextensible-applies-to-private") {
        policy = policy.with_private_element_extensibility(
            scriptw_engine::PrivateElementExtensibility::NonExtensibleAppliesToPrivate,
        );
    }
    policy
}

fn compile_options_for_case(case: &TestCase) -> CompileOptions {
    CompileOptions {
        filename: Some(case.source_path.display().to_string()),
        host_surface_policy: HostSurfacePolicy::Test262,
        language_features: language_features_for_case(case),
        // Entry Module completion has its own root; unrelated rejections use
        // the default ECMAScript host tracker in every source goal.
        promise_rejection_policy: PromiseRejectionPolicy::Ignore,
        ..CompileOptions::default()
    }
}

fn compile_options_for_materialized_case(
    case: &TestCase,
    materialized: &MaterializedTest,
) -> CompileOptions {
    CompileOptions {
        module_prelude: materialized.module_prelude.clone(),
        ..compile_options_for_case(case)
    }
}

/// The evidence dimensions a direct-run checkpoint must match before resume.
///
/// Keeping the pins, backend, exact selected ids, and intended terminal
/// kind/path beside the manifest hash makes it impossible to call the loader
/// with only a file-name identity. That former shape let foreign selections or
/// a completed SpecExec checkpoint enter another run and skip cases before the
/// result was relabelled.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ResumeCheckpointIdentity {
    manifest_hash: u64,
    manifest_filter: Option<String>,
    execution_backend: ExecutionBackend,
    pinned_revisions: PinnedRevisions,
    selected_test_ids: Vec<TestExecutionId>,
    kind: DirectSnapshotKind,
    checkpoint_run_identity: CheckpointRunIdentity,
}

impl ResumeCheckpointIdentity {
    fn for_resume(
        manifest: &SuiteManifest,
        run_config: &RunConfig,
        checkpoint_run_identity: CheckpointRunIdentity,
    ) -> Self {
        Self {
            manifest_hash: manifest.manifest_hash,
            manifest_filter: manifest.filter.clone(),
            execution_backend: run_config.execution_backend,
            pinned_revisions: manifest.pinned_revisions.clone(),
            selected_test_ids: manifest
                .cases
                .iter()
                .map(|case| case.execution_id.clone())
                .collect(),
            kind: DirectSnapshotKind::ResumeCheckpoint,
            checkpoint_run_identity,
        }
    }

    fn for_single_case_child(manifest: &SuiteManifest, run_config: &RunConfig) -> Self {
        let mut identity = Self::for_resume(manifest, run_config, CheckpointRunIdentity::full());
        identity.kind = DirectSnapshotKind::SingleCaseChild;
        identity
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DirectSnapshotKind {
    ResumeCheckpoint,
    SingleCaseChild,
}

fn direct_snapshot_case_requirement(
    kind: DirectSnapshotKind,
    expected_identity: &CheckpointRunIdentity,
    run_kind: &str,
    checkpoint_identity: Option<&CheckpointRunIdentity>,
    matrix_path: &[String],
) -> Result<CaseSetRequirement, String> {
    let expected_terminal_run_kind = expected_identity.terminal_run_kind();
    let expected_matrix_path = expected_identity.matrix_path();
    if run_kind == "resume-case-checkpoint" {
        if kind != DirectSnapshotKind::ResumeCheckpoint {
            return Err(
                "single-case child snapshot cannot be an in-progress resume checkpoint".to_string(),
            );
        }
        let checkpoint_identity = checkpoint_identity.ok_or_else(|| {
            "resume-case-checkpoint is missing its intended terminal run identity".to_string()
        })?;
        if checkpoint_identity != expected_identity {
            if checkpoint_identity.terminal_run_kind() != expected_terminal_run_kind {
                return Err(format!(
                    "resume-case-checkpoint expected terminal run_kind {expected_terminal_run_kind}, found {}",
                    checkpoint_identity.terminal_run_kind()
                ));
            }
            return Err(format!(
                "resume-case-checkpoint expected terminal matrix_path [{}], found [{}]",
                expected_matrix_path.join(", "),
                checkpoint_identity.matrix_path().join(", ")
            ));
        }
        if !matrix_path.is_empty() {
            return Err(format!(
                "resume-case-checkpoint must keep terminal matrix_path only in checkpoint_identity, found snapshot matrix_path [{}]",
                matrix_path.join(", ")
            ));
        }
        return Ok(CaseSetRequirement::UniqueSubset);
    }
    if checkpoint_identity.is_some() {
        return Err(format!(
            "terminal snapshot run_kind {run_kind} must not contain checkpoint_identity"
        ));
    }
    if run_kind != expected_terminal_run_kind {
        return Err(format!(
            "direct snapshot expected run_kind {expected_terminal_run_kind}, found {run_kind}"
        ));
    }
    if matrix_path != expected_matrix_path {
        return Err(format!(
            "direct snapshot expected matrix_path [{}], found [{}]",
            expected_matrix_path.join(", "),
            matrix_path.join(", ")
        ));
    }
    Ok(CaseSetRequirement::Exact)
}

fn write_resume_case_checkpoint(
    config: &SuiteConfig,
    manifest: &SuiteManifest,
    results: &[TestResult],
    run_config: &RunConfig,
    checkpoint_run_identity: &CheckpointRunIdentity,
) -> Result<(), String> {
    let mut snapshot = snapshot_from_summary(
        manifest,
        "resume-case-checkpoint".to_string(),
        &summarize_results(results),
        run_config.execution_backend,
    )?;
    snapshot.checkpoint_identity = Some(checkpoint_run_identity.clone());
    validate_case_snapshot_contract(
        &snapshot,
        &manifest
            .cases
            .iter()
            .map(|case| case.execution_id.clone())
            .collect::<Vec<_>>(),
        CaseSetRequirement::UniqueSubset,
        "resume checkpoint being written",
    )?;
    write_snapshot(config, &snapshot, &run_config.snapshot_name).map(|_| ())
}

fn snapshot_paths_for_name(
    config: &SuiteConfig,
    snapshot_name: &str,
    manifest_hash: u64,
) -> SnapshotPaths {
    SnapshotPaths {
        json_path: config
            .snapshot_dir
            .join(format!("{snapshot_name}-{manifest_hash}.json")),
        txt_path: config
            .snapshot_dir
            .join(format!("{snapshot_name}-{manifest_hash}.txt")),
    }
}

/// Where the attempt journal for one `(snapshot_name, manifest_hash)` pair
/// lives.
///
/// Derived from the snapshot's own JSON path rather than formatted
/// independently, so a journal can never key on a different pair than the
/// snapshot whose resume state it corrects. `execute_matrix_node` forms that
/// pair once, as `{snapshot_name}-{sanitized node_id}` plus the node manifest
/// hash, and both files follow it.
///
/// The extension is deliberately **not** `.json`, and that is not cosmetic:
/// `load_resume_aggregate_snapshot` collects every `*.json` file in the
/// snapshot directory whose name starts with `{snapshot_name}-` as a fallback
/// aggregate candidate and then reads it with `read_snapshot_file(&path)?` —
/// where a parse failure is propagated, not skipped. A journal named `.json`
/// would therefore turn every `report-all --resume` that has not yet written an
/// aggregate into a hard error, which is the opposite of this module's purpose.
fn attempt_journal_path(config: &SuiteConfig, snapshot_name: &str, manifest_hash: u64) -> PathBuf {
    snapshot_paths_for_name(config, snapshot_name, manifest_hash)
        .json_path
        .with_extension("attempts")
}

fn attempt_journal_identity(
    manifest: &SuiteManifest,
    run_config: &RunConfig,
) -> Result<AttemptJournalIdentity, String> {
    AttemptJournalIdentity::new(
        manifest.manifest_hash,
        run_config.execution_backend,
        manifest.cases.iter().map(|case| case.execution_id.clone()),
    )
}

/// The failure record for a quarantined case.
///
/// `OutcomeKind::Crash` is constructed **explicitly** here, never inferred.
/// `classify_failure_outcome` decides `Crash` by lowercase substring match over
/// the detail (`"crash"`, `"panic"`, `"trapped"`, `"timeout exceeded"`, ...), so
/// routing a quarantine through `classify_failure` would make the outcome
/// depend on a particular word surviving a future edit of this message. It
/// would also be the wrong reason: this process never observed the case crash.
/// It read that fact out of the attempt journal.
///
/// `FailureKind::WasmBackend` because the deaths this mechanism exists for
/// happen inside compilation or execution of the emitted module, and
/// `FailureOrigin::LocalHarness` because the *decision* not to run it is the
/// harness's own.
fn quarantined_case_failure(test_id: TestExecutionId, strikes: CaseStrikes) -> FailureRecord {
    let origin = FailureOrigin::LocalHarness;
    let detail = format!(
        "[origin:{}] process death while compiling or running this case ({} attempts); quarantined by report-all --resume",
        origin.as_str(),
        strikes.get()
    );
    FailureRecord {
        test_path: test_id.path().to_string(),
        test_id,
        kind: FailureKind::WasmBackend,
        outcome: OutcomeKind::Crash,
        origin,
        detail_hash: hash_detail(&detail),
        detail,
        duration_ms: None,
    }
}

fn single_case_manifest(config: &SuiteConfig, case: &TestCase) -> SuiteManifest {
    let cases = vec![case.clone()];
    let pinned = pinned_revisions(config);
    SuiteManifest {
        pinned_revisions: pinned.clone(),
        manifest_hash: hash_manifest(&pinned, &cases, Some(&case.execution_id.wire_key())),
        filter: Some(case.execution_id.wire_key()),
        cases,
    }
}

fn result_from_single_case_snapshot(
    case: &TestCase,
    snapshot: ProgressSnapshot,
    duration_ms: u128,
) -> Result<TestResult, String> {
    validate_case_snapshot_contract(
        &snapshot,
        std::slice::from_ref(&case.execution_id),
        CaseSetRequirement::Exact,
        &format!("single-case child snapshot for {}", case.execution_id),
    )?;

    if snapshot.passed == 1 && snapshot.failures.is_empty() {
        return Ok(TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Passed,
            duration_ms: Some(duration_ms),
        });
    }

    if snapshot.passed == 0 && snapshot.failures.len() == 1 {
        return Ok(TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Failed(snapshot.failures[0].clone()),
            duration_ms: Some(duration_ms),
        });
    }

    Err(format!(
        "single-case child snapshot for {} had inconsistent pass/failure counts",
        case.path
    ))
}

fn create_child_snapshot_directory(
    config: &SuiteConfig,
    case: &TestCase,
) -> Result<PathBuf, String> {
    static NEXT_DIRECTORY_ID: AtomicU64 = AtomicU64::new(0);

    let timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    loop {
        let directory_id = NEXT_DIRECTORY_ID.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "scriptw-test262-child-{}-{timestamp}-{directory_id}",
            std::process::id()
        ));
        // TMPDIR is caller-controlled. Reject a scratch namespace that would
        // become a new suite input before creating any directory or journal.
        suite_identity::validate_case_destination(config, &path)?;
        match fs::create_dir(&path) {
            Ok(()) => return Ok(path),
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(err) => {
                return Err(format!(
                    "failed to create child snapshot directory {} for {}: {err}",
                    path.display(),
                    case.path
                ));
            }
        }
    }
}

fn append_case_harness(command: &mut Command, harness: &LocalHarnessSource) {
    match harness {
        LocalHarnessSource::None => {
            command.arg("--case-harness").arg("none");
        }
        LocalHarnessSource::EmbeddedSpecExec => {
            command.arg("--case-harness").arg("spec-exec");
        }
        LocalHarnessSource::EmbeddedWasmAot => {
            command.arg("--case-harness").arg("wasm-aot");
        }
        LocalHarnessSource::EmbeddedWasmAotHostOnly => {
            command.arg("--case-harness").arg("wasm-aot-host-only");
        }
        LocalHarnessSource::File(path) => {
            command.arg("--case-harness-file").arg(path);
        }
    }
}

/// Keep the primary classified failure even when retirement/removal also fails.
/// A successful attempt never stays green after failed cleanup.
fn with_case_cleanup(
    case: &TestCase,
    result: Result<TestResult, String>,
    cleanup: Result<(), String>,
) -> Result<TestResult, String> {
    let Err(cleanup) = cleanup else {
        return result;
    };
    let mut result = match result {
        Ok(result) => result,
        Err(primary) => TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Failed(classify_failure(
                case.execution_id.clone(),
                FailureKind::HostHarness,
                primary,
            )),
            duration_ms: None,
        },
    };
    match &mut result.status {
        TestStatus::Passed => Err(cleanup),
        TestStatus::Failed(failure) => {
            failure
                .detail
                .push_str(&format!("; cleanup failed: {cleanup}"));
            failure.detail_hash = hash_detail(&failure.detail);
            Ok(result)
        }
    }
}

fn combine_cleanup_errors(
    first: Result<(), String>,
    second: Result<(), String>,
) -> Result<(), String> {
    match (first, second) {
        (Ok(()), Ok(())) => Ok(()),
        (Err(error), Ok(())) | (Ok(()), Err(error)) => Err(error),
        (Err(first), Err(second)) => Err(format!("{first}; {second}")),
    }
}

fn run_one_case_in_reused_process(
    binary: &Path,
    session: &mut case_worker_server::Worker,
    config: &SuiteConfig,
    case: &TestCase,
    run: &RunConfig,
) -> Result<TestResult, String> {
    let manifest = single_case_manifest(config, case);
    let directory = create_child_snapshot_directory(config, case)?;
    let name = format!(
        "{}-case-{}",
        run.snapshot_name,
        hash_case_path(&case.execution_id.wire_key())
    );
    let child_config = SuiteConfig {
        snapshot_dir: directory.clone(),
        source_output_root: Some(config.source_output_root().to_path_buf()),
        ..config.clone()
    };
    let result = (|| {
        let deadline = case_process::CaseDeadline::new(config.timeout_ms, run.execution_backend)?;
        let (outcome, retirement) = match session.request(
            binary,
            config,
            run,
            &case.execution_id,
            &directory,
            &name,
            deadline,
        ) {
            case_worker_server::RequestCompletion::Completed {
                outcome,
                retirement,
            } => (outcome, retirement),
            case_worker_server::RequestCompletion::TimedOut { retirement } => {
                let duration_ms = deadline.elapsed_ms();
                return with_case_cleanup(
                    case,
                    Ok(TestResult {
                        test_id: case.execution_id.clone(),
                        status: TestStatus::Failed(classify_failure(
                            case.execution_id.clone(),
                            FailureKind::Runtime,
                            format!("timeout exceeded after {duration_ms}ms"),
                        )),
                        duration_ms: Some(duration_ms),
                    }),
                    retirement,
                );
            }
            case_worker_server::RequestCompletion::Failed {
                primary,
                retirement,
            } => {
                return with_case_cleanup(case, Err(primary), retirement);
            }
        };
        // A valid terminal ACK owns a completed snapshot. Preserve its case
        // classification even if retiring the exhausted/suspect worker failed.
        let result = (|| {
            let snapshot = load_previous_snapshot(
                &child_config,
                &name,
                ResumeCheckpointIdentity::for_single_case_child(&manifest, run),
                ResumeCheckpointLoadPolicy::RequireExact,
            )?
            .ok_or("case worker responded without its exact completed snapshot")?;
            let result = result_from_single_case_snapshot(case, snapshot, deadline.elapsed_ms())?;
            if matches!(result.status, TestStatus::Passed)
                != (outcome == case_worker_server::Outcome::Passed)
            {
                return Err(
                    "case worker terminal verdict contradicts its validated snapshot".into(),
                );
            }
            Ok(result)
        })();
        with_case_cleanup(case, result, retirement)
    })();
    // A failed admission may leave a writer active. Retire it before unlinking
    // its snapshot directory, including errors after a valid terminal reply.
    let retirement = if result.is_err() {
        session.retire()
    } else {
        Ok(())
    };
    let cleanup = fs::remove_dir_all(&directory).map_err(|error| {
        format!(
            "cannot remove case snapshot directory {}: {error}",
            directory.display()
        )
    });
    let retirement = if cleanup.is_err() {
        combine_cleanup_errors(retirement, session.retire())
    } else {
        retirement
    };
    with_case_cleanup(case, result, combine_cleanup_errors(retirement, cleanup))
}

fn run_one_case_in_child_process(
    case_runner_bin: &Path,
    config: &SuiteConfig,
    case: &TestCase,
    run_config: &RunConfig,
) -> Result<TestResult, String> {
    let child_manifest = single_case_manifest(config, case);
    let child_snapshot_dir = create_child_snapshot_directory(config, case)?;
    run_one_case_in_child_snapshot_directory(
        case_runner_bin,
        config,
        case,
        run_config,
        child_manifest,
        child_snapshot_dir,
    )
}

fn run_one_case_in_child_snapshot_directory(
    case_runner_bin: &Path,
    config: &SuiteConfig,
    case: &TestCase,
    run_config: &RunConfig,
    child_manifest: SuiteManifest,
    child_snapshot_dir: PathBuf,
) -> Result<TestResult, String> {
    let child_snapshot_name = format!(
        "{}-case-{}",
        run_config.snapshot_name,
        hash_case_path(&case.execution_id.wire_key())
    );
    let child_config = SuiteConfig {
        snapshot_dir: child_snapshot_dir.clone(),
        source_output_root: Some(config.source_output_root().to_path_buf()),
        ..config.clone()
    };
    let child_snapshot_paths = snapshot_paths_for_name(
        &child_config,
        &child_snapshot_name,
        child_manifest.manifest_hash,
    );

    let child_result = (|| {
        let mut child = Command::new(case_runner_bin);
        child
            .arg("--jobs")
            .arg(compilation_jobs().to_string())
            .arg("test262")
            .arg("__case-worker")
            .arg(case.execution_id.wire_key())
            .arg("--suite-root")
            .arg(&config.suite_root)
            .arg("--snapshot-dir")
            .arg(&child_snapshot_dir)
            .arg("--snapshot-name")
            .arg(&child_snapshot_name)
            .arg("--case-suite-output")
            .arg(config.source_output_root())
            .arg("--threads")
            .arg("1")
            .arg("--timeout-ms")
            .arg(config.timeout_ms.to_string())
            .arg("--execution-backend")
            .arg(run_config.execution_backend.as_str())
            .stdout(Stdio::null())
            .stderr(Stdio::null());

        append_case_harness(&mut child, &config.local_harness);
        let budget =
            case_process::CaseDeadline::new(config.timeout_ms, run_config.execution_backend)?;
        if budget.expired() {
            return Ok(TestResult {
                test_id: case.execution_id.clone(),
                status: TestStatus::Failed(classify_failure(
                    case.execution_id.clone(),
                    FailureKind::Runtime,
                    format!(
                        "timeout exceeded after {}ms before worker spawn",
                        budget.elapsed_ms()
                    ),
                )),
                duration_ms: Some(budget.elapsed_ms()),
            });
        }
        let mut child = match case_process::CaseProcess::spawn(&mut child, budget) {
            Ok(child) => child,
            Err(_) if budget.expired() => {
                return Ok(TestResult {
                    test_id: case.execution_id.clone(),
                    status: TestStatus::Failed(classify_failure(
                        case.execution_id.clone(),
                        FailureKind::Runtime,
                        format!(
                            "timeout exceeded after {}ms before worker spawn",
                            budget.elapsed_ms()
                        ),
                    )),
                    duration_ms: Some(budget.elapsed_ms()),
                });
            }
            Err(error) => {
                return Err(format!(
                    "failed to spawn child case runner {} for {}: {error}",
                    case_runner_bin.display(),
                    case.path
                ));
            }
        };

        let status = child.wait_until_deadline();
        // Retirement precedes snapshot reads: no surviving writer may race
        // admission. Its diagnostic cannot replace a known timeout/poll error.
        let retirement = child.retire();
        let duration_ms = budget.elapsed_ms();
        let status = match status {
            Ok(None) => {
                return with_case_cleanup(
                    case,
                    Ok(TestResult {
                        test_id: case.execution_id.clone(),
                        status: TestStatus::Failed(classify_failure(
                            case.execution_id.clone(),
                            FailureKind::Runtime,
                            format!("timeout exceeded after {duration_ms}ms"),
                        )),
                        duration_ms: Some(duration_ms),
                    }),
                    retirement,
                );
            }
            Err(primary) => return with_case_cleanup(case, Err(primary), retirement),
            Ok(Some(status)) if !status.success() && status.code() != Some(1) => {
                return with_case_cleanup(
                    case,
                    Err(format!(
                        "child case runner crashed for {}: {status}",
                        case.path
                    )),
                    retirement,
                );
            }
            Ok(Some(status)) => {
                retirement?;
                status
            }
        };
        if !status.success() {
            // A failed case is intentionally exit 1, so accept only its exact
            // validated failure snapshot; a crash cannot turn a staged pass green.
            let snapshot = load_previous_snapshot(
                &child_config,
                &child_snapshot_name,
                ResumeCheckpointIdentity::for_single_case_child(&child_manifest, run_config),
                ResumeCheckpointLoadPolicy::RequireExact,
            )?
            .ok_or_else(|| {
                format!(
                    "child case runner failed for {} without a snapshot",
                    case.path
                )
            })?;
            let result = result_from_single_case_snapshot(case, snapshot, duration_ms)?;
            if matches!(result.status, TestStatus::Passed) {
                return Err(format!(
                    "child case runner failed for {} but reported success",
                    case.path
                ));
            }
            return Ok(result);
        }

        match load_previous_snapshot(
            &child_config,
            &child_snapshot_name,
            ResumeCheckpointIdentity::for_single_case_child(&child_manifest, run_config),
            ResumeCheckpointLoadPolicy::RequireExact,
        ) {
            Ok(Some(snapshot)) => result_from_single_case_snapshot(case, snapshot, duration_ms),
            Ok(None) => Err(format!(
                "child case runner exited for {} without writing snapshot {}",
                case.path,
                child_snapshot_paths.json_path.display()
            )),
            Err(err) => Err(err),
        }
    })();

    let cleanup = fs::remove_dir_all(&child_snapshot_dir).map_err(|err| {
        format!(
            "failed to remove child snapshot directory {} after running {}: {err}",
            child_snapshot_dir.display(),
            case.path
        )
    });

    with_case_cleanup(case, child_result, cleanup)
}

/// Runs one case that the attempt journal has admitted.
///
/// Consumes [`AdmittedCase`] rather than borrowing a `TestCase` on purpose: the worker
/// closure in `execute_cases` has the whole `&[TestCase]` in scope, so with a
/// bare `&TestCase` parameter `run_case_entry(.., &cases[0], ..)` compiled and
/// bypassed the quarantine check entirely. `AdmittedCase`'s field is private
/// and `AttemptJournal::admit` is its only non-test constructor. The admitted
/// proof is non-cloneable and transferred into this function, so one journal
/// admission cannot authorize a second execution.
#[cfg(test)]
fn run_case_entry(
    config: &SuiteConfig,
    preludes: &PreludeStore,
    admitted: AdmittedCase,
    run_config: &RunConfig,
) -> TestResult {
    let dispatch = CaseExecutionDispatch::admit(config, std::slice::from_ref(admitted.case()))
        .expect("test fixture must explicitly choose its execution role");
    run_case_entry_with_dispatch(
        &dispatch,
        &mut case_worker_server::Worker::default(),
        config,
        preludes,
        admitted,
        run_config,
    )
}

fn run_case_entry_with_dispatch(
    dispatch: &CaseExecutionDispatch,
    session: &mut case_worker_server::Worker,
    config: &SuiteConfig,
    preludes: &PreludeStore,
    admitted: AdmittedCase,
    run_config: &RunConfig,
) -> TestResult {
    let case = admitted.case();
    match dispatch {
        CaseExecutionDispatch::Supervised(binary) => {
            return run_one_case_in_child_process(binary, config, case, run_config).unwrap_or_else(
                |detail| TestResult {
                    test_id: case.execution_id.clone(),
                    status: TestStatus::Failed(classify_failure(
                        case.execution_id.clone(),
                        FailureKind::HostHarness,
                        detail,
                    )),
                    duration_ms: None,
                },
            );
        }
        CaseExecutionDispatch::Reused(binary) => {
            return run_one_case_in_reused_process(binary, session, config, case, run_config)
                .unwrap_or_else(|detail| TestResult {
                    test_id: case.execution_id.clone(),
                    status: TestStatus::Failed(classify_failure(
                        case.execution_id.clone(),
                        FailureKind::HostHarness,
                        detail,
                    )),
                    duration_ms: None,
                });
        }
        CaseExecutionDispatch::Worker => {}
    }

    panic::catch_unwind(AssertUnwindSafe(|| {
        run_one_case_on_persistent_worker(
            case,
            preludes,
            config.timeout_ms,
            run_config.execution_backend,
        )
    }))
    .unwrap_or_else(|panic_payload| TestResult {
        test_id: case.execution_id.clone(),
        status: TestStatus::Failed({
            let detail = format!("worker panic: {}", panic_message(&panic_payload));
            classify_failure_with_outcome(
                case.execution_id.clone(),
                FailureKind::Runtime,
                classify_failure_outcome(FailureKind::Runtime, &detail),
                FailureOrigin::LocalHarness,
                detail,
            )
        }),
        duration_ms: None,
    })
}

#[cfg(test)]
fn run_one_case(
    case: &TestCase,
    preludes: &PreludeStore,
    timeout_ms: u64,
    execution_backend: ExecutionBackend,
) -> TestResult {
    run_one_case_with_wasm_aot_execution(
        case,
        preludes,
        timeout_ms,
        execution_backend,
        WasmAotExecutionStack::DedicatedWorker,
    )
}

/// Runs one case on an `execute_cases` worker, which owns the large stack
/// required by the engine's current-thread Wasm-AOT entry points.
fn run_one_case_on_persistent_worker(
    case: &TestCase,
    preludes: &PreludeStore,
    timeout_ms: u64,
    execution_backend: ExecutionBackend,
) -> TestResult {
    run_one_case_with_wasm_aot_execution(
        case,
        preludes,
        timeout_ms,
        execution_backend,
        // execute_cases already owns the sized worker stack. The current-thread
        // entry retains immutable R code and bypasses unique P modules; every
        // invocation still creates its own Engine, Realm and Store.
        WasmAotExecutionStack::PersistentTest262Worker,
    )
}

enum WasmAotExecutionStack {
    #[cfg(test)]
    DedicatedWorker,
    PersistentTest262Worker,
}

fn run_one_case_with_wasm_aot_execution(
    case: &TestCase,
    preludes: &PreludeStore,
    timeout_ms: u64,
    execution_backend: ExecutionBackend,
    wasm_aot_execution_stack: WasmAotExecutionStack,
) -> TestResult {
    run_one_case_with_execution(
        case,
        preludes,
        timeout_ms,
        execution_backend,
        |engine, materialized, compile_options, run_options| {
            execute_materialized_case(
                engine,
                materialized,
                compile_options,
                run_options,
                wasm_aot_execution_stack,
            )
        },
    )
}

fn execute_materialized_case(
    engine: &Engine,
    materialized: &MaterializedTest,
    compile_options: CompileOptions,
    run_options: RunOptions,
    wasm_aot_execution_stack: WasmAotExecutionStack,
) -> Result<scriptw_engine::RunOutcome, EngineError> {
    let agent_prelude = materialized.agent_prelude.clone();

    match run_options.backend {
        ExecutionBackend::SpecExec => {
            if materialized.execution_mode().is_module() {
                engine.run_module(&materialized.source, compile_options, run_options)
            } else {
                engine.run_script(&materialized.source, compile_options, run_options)
            }
        }
        ExecutionBackend::WasmAot => match wasm_aot_execution_stack {
            WasmAotExecutionStack::PersistentTest262Worker => {
                match (materialized.execution_mode().is_module(), agent_prelude) {
                    (true, Some(_) | None) => engine.run_wasm_aot_module_on_current_thread(
                        &materialized.source,
                        compile_options,
                        run_options.timeout_ms,
                        run_options.can_block,
                    ),
                    (false, Some(prelude)) => engine
                        .run_wasm_aot_script_with_agents_on_current_thread(
                            &materialized.source,
                            compile_options,
                            run_options.timeout_ms,
                            run_options.can_block,
                            prelude,
                        ),
                    (false, None) => engine.run_wasm_aot_script_on_current_thread(
                        &materialized.source,
                        compile_options,
                        run_options.timeout_ms,
                        run_options.can_block,
                    ),
                }
            }
            #[cfg(test)]
            WasmAotExecutionStack::DedicatedWorker => {
                match (materialized.execution_mode().is_module(), agent_prelude) {
                    (true, Some(_) | None) => {
                        engine.run_module(&materialized.source, compile_options, run_options)
                    }
                    (false, Some(prelude)) => engine.run_wasm_aot_script_with_agents(
                        &materialized.source,
                        compile_options,
                        run_options.timeout_ms,
                        run_options.can_block,
                        prelude,
                    ),
                    (false, None) => {
                        engine.run_script(&materialized.source, compile_options, run_options)
                    }
                }
            }
        },
    }
}

// The runner classifies one Engine call; its wall time includes compilation.
// The Engine retains the separate execution limit in the owned RunOptions.
fn run_one_case_with_execution(
    case: &TestCase,
    preludes: &PreludeStore,
    timeout_ms: u64,
    execution_backend: ExecutionBackend,
    execute: impl FnOnce(
        &Engine,
        &MaterializedTest,
        CompileOptions,
        RunOptions,
    ) -> Result<scriptw_engine::RunOutcome, EngineError>,
) -> TestResult {
    let start = Instant::now();
    let outcome = (|| -> Result<(), FailureRecord> {
        let materialized = materialize_test(case, preludes).map_err(|detail| {
            classify_failure(case.execution_id.clone(), FailureKind::HostHarness, detail)
        })?;

        let async_output = (execution_backend == ExecutionBackend::WasmAot
            && case.flags.contains("async"))
        .then(|| Arc::new(Mutex::new(Vec::new())));
        let realm_builder = if let Some(lines) = async_output.as_ref() {
            RealmBuilder::new().with_host_hooks(Box::new(CapturingTest262Output {
                lines: Arc::clone(lines),
            }))
        } else {
            RealmBuilder::new()
        };
        let engine = Engine::new(realm_builder.build());
        let mut compile_options = compile_options_for_materialized_case(case, &materialized);
        if execution_backend == ExecutionBackend::WasmAot {
            // AOT cannot load at run time: declare every module the case can
            // name (fixtures beside it and their relative references).
            let goal = if materialized.execution_mode().is_module() {
                scriptw_engine::EmbeddedModuleGoal::Module
            } else {
                scriptw_engine::EmbeddedModuleGoal::Script
            };
            let catalog = module_catalog::declare(
                &case.source_path,
                goal,
                &materialized.source,
                &case.original_source,
            )
            .map_err(|detail| {
                classify_failure(case.execution_id.clone(), FailureKind::HostHarness, detail)
            })?;
            if let Some(catalog) = catalog {
                compile_options.filename = Some(catalog.graph.entry().identity().to_owned());
                compile_options.module_loading_policy =
                    ModuleLoadingPolicy::Embedded(catalog.graph);
            }
        }

        // Parse/early-negative tests use an explicit compile path. Wasm-AOT
        // rejects a successful compile without executing user code; SpecExec
        // deliberately falls through to its Boa oracle when our front-end
        // accepts the source, preserving differential syntax coverage. All
        // other cases go straight through run_script/run_module below: those
        // APIs perform the one necessary compile and, for Wasm-AOT, use the
        // whole-program cache.
        let compile_only_negative = case_has_compile_only_negative(case);
        // SpecExec historically preflighted every negative case with
        // Scriptw's compiler and surfaced its diagnostics before invoking the
        // Boa oracle. Keep that behavior for runtime/resolution negatives;
        // Wasm-AOT takes the cache-aware run path without this extra compile.
        let spec_exec_negative_preflight = execution_backend == ExecutionBackend::SpecExec
            && case.negative.is_some()
            && !compile_only_negative;
        if compile_only_negative || spec_exec_negative_preflight {
            let negative = case.negative.as_ref().expect("negative preflight exists");
            let negative_kind = classify_negative_phase(negative);
            let compile_result = if materialized.execution_mode().is_module() {
                engine.compile_module(&materialized.source, compile_options.clone())
            } else {
                engine.compile_script(&materialized.source, compile_options.clone())
            };
            match compile_result {
                Err(err) => {
                    if err.is_global_prelude_failure() {
                        return Err(classify_engine_failure(case.execution_id.clone(), &err));
                    }
                    if compile_only_negative && compile_negative_error_matches(&err, negative) {
                        return Ok(());
                    }
                    if !compile_only_negative {
                        return Err(classify_engine_failure(case.execution_id.clone(), &err));
                    }
                    let detail = compile_negative_error_detail(&err);
                    return Err(classify_failure(
                        case.execution_id.clone(),
                        negative_kind,
                        format!(
                            "negative test error mismatch: expected {}, got {}",
                            negative.error_type, detail
                        ),
                    ));
                }
                Ok(_) if execution_backend == ExecutionBackend::WasmAot => {
                    return Err(classify_failure(
                        case.execution_id.clone(),
                        negative_kind,
                        format!(
                            "negative test expected {} error but compile succeeded",
                            negative.phase
                        ),
                    ));
                }
                // The SpecExec backend deliberately lets the Boa oracle run
                // after Scriptw's front-end accepts a parse/early negative;
                // this catches syntax the oracle recognizes that our parser
                // does not. Preserve that differential behavior while keeping
                // Wasm-AOT negatives compile-only.
                Ok(_) => {}
            }
        }

        let run_options = RunOptions {
            backend: execution_backend,
            argv: Vec::new(),
            module_root: if materialized.execution_mode().is_module() {
                case.source_path
                    .parent()
                    .map(|path| path.display().to_string())
            } else {
                None
            },
            test_path: Some(case.source_path.display().to_string()),
            can_block: !case.flags.contains("CanBlockIsFalse"),
            // The Store's execution deadline bounds execution inside the
            // selected case worker. The supervisor still owns that child's process deadline;
            // neither source metadata nor this engine bound bypasses it.
            timeout_ms: Some(timeout_ms),
        };
        let run_result = execute(&engine, &materialized, compile_options, run_options);
        if let Err(err) = &run_result {
            if err.is_global_prelude_failure() {
                return Err(classify_engine_failure(case.execution_id.clone(), err));
            }
        }

        if let Some(lines) = &async_output {
            let lines = lines
                .lock()
                .expect("Test262 output capture lock should not be poisoned");
            let failures = lines
                .iter()
                .filter(|line| line.starts_with("Test262:AsyncTestFailure:"))
                .map(String::as_str)
                .collect::<Vec<_>>();
            if !failures.is_empty() {
                let mut detail = failures.join("; ");
                let outcome = match &run_result {
                    Ok(_) => OutcomeKind::Bug,
                    Err(err) => {
                        let execution_failure =
                            classify_engine_failure(case.execution_id.clone(), err);
                        detail.push_str("; ");
                        detail.push_str(err.message());
                        match execution_failure.outcome {
                            OutcomeKind::Crash => OutcomeKind::Crash,
                            OutcomeKind::Bug
                            | OutcomeKind::NotImplemented
                            | OutcomeKind::Success => OutcomeKind::Bug,
                        }
                    }
                };
                // Reported async failures survive even when the engine later
                // rejects execution or throws the expected negative exception.
                return Err(classify_failure_with_outcome(
                    case.execution_id.clone(),
                    FailureKind::Runtime,
                    outcome,
                    FailureOrigin::Unknown,
                    detail,
                ));
            }
        }

        if let Some(negative) = &case.negative {
            let negative_kind = classify_negative_phase(negative);
            return match run_result {
                Ok(_) => Err(classify_failure(
                    case.execution_id.clone(),
                    negative_kind,
                    format!(
                        "negative test expected {} error but execution succeeded",
                        negative.phase
                    ),
                )),
                Err(err) => {
                    if compile_only_negative {
                        // A successful Scriptw preflight may still be rejected by
                        // the selected oracle entry parser. Runtime throws,
                        // worker errors and diagnostic text cannot mint that
                        // phase provenance.
                        if execution_backend == ExecutionBackend::SpecExec
                            && err.is_oracle_entry_syntax_rejection()
                            && (negative.error_type.is_empty()
                                || negative.error_type == "SyntaxError")
                        {
                            return Ok(());
                        }
                        return Err(classify_failure(
                            case.execution_id.clone(),
                            negative_kind,
                            format!(
                                "negative test expected {} {} entry rejection, got a different phase or error: {}",
                                negative.phase, negative.error_type, err
                            ),
                        ));
                    }
                    // run_script/run_module can surface parser/IR diagnostics
                    // directly now that the redundant pre-compile is gone;
                    // those are compilation failures, not runtime negatives.
                    if !compile_only_negative
                        && (err.parse_diagnostic().is_some() || err.ir_diagnostic().is_some())
                    {
                        return Err(classify_engine_failure(case.execution_id.clone(), &err));
                    }
                    // Only the root JavaScript throw can satisfy a Wasm
                    // runtime negative; worker failures and host traps cannot
                    // acquire that meaning from an error name in their text.
                    if !compile_only_negative
                        && !is_expected_negative_exception(&err, execution_backend, negative.phase)
                    {
                        return Err(classify_engine_failure(case.execution_id.clone(), &err));
                    }
                    let detail = err.message().to_string();
                    let type_matches = negative.error_type.is_empty()
                        || match execution_backend {
                            ExecutionBackend::WasmAot => {
                                err.wasm_javascript_exception_constructor_name()
                                    == Some(negative.error_type.as_str())
                            }
                            ExecutionBackend::SpecExec => {
                                err.oracle_javascript_exception_constructor_name()
                                    == Some(negative.error_type.as_str())
                            }
                        };
                    if type_matches {
                        Ok(())
                    } else {
                        let (outcome, origin, mismatch) = match execution_backend {
                            ExecutionBackend::WasmAot => (
                                OutcomeKind::Bug,
                                FailureOrigin::Unknown,
                                format!(
                                    "negative test error mismatch: expected {}, got constructor {}: {}",
                                    negative.error_type,
                                    err.wasm_javascript_exception_constructor_name()
                                        .unwrap_or("<unavailable>"),
                                    detail
                                ),
                            ),
                            ExecutionBackend::SpecExec => {
                                let mismatch = format!(
                                    "negative test error mismatch: expected {}, got admitted constructor {}: {}",
                                    negative.error_type,
                                    err.oracle_javascript_exception_constructor_name()
                                        .unwrap_or("<unclassified>"),
                                    detail
                                );
                                (OutcomeKind::Bug, FailureOrigin::Unknown, mismatch)
                            }
                        };
                        Err(classify_failure_with_outcome(
                            case.execution_id.clone(),
                            negative_kind,
                            outcome,
                            origin,
                            mismatch,
                        ))
                    }
                }
            };
        }

        match run_result {
            Ok(_) => {
                if let Some(lines) = async_output {
                    let lines = lines
                        .lock()
                        .expect("Test262 output capture lock should not be poisoned");
                    let completions = lines
                        .iter()
                        .filter(|line| line.as_str() == "Test262:AsyncTestComplete")
                        .count();
                    if completions == 0 {
                        return Err(classify_failure(
                            case.execution_id.clone(),
                            FailureKind::HostHarness,
                            "host harness async $DONE was not called before the Wasm job queue drained",
                        ));
                    }
                    if completions != 1 {
                        return Err(classify_failure(
                            case.execution_id.clone(),
                            FailureKind::HostHarness,
                            format!(
                                "host harness async $DONE must complete exactly once, observed {completions} completions"
                            ),
                        ));
                    }
                }
                Ok(())
            }
            Err(err) => Err(classify_engine_failure(case.execution_id.clone(), &err)),
        }
    })();

    let duration_ms = start.elapsed().as_millis();
    // Wasm-AOT execution has already been bounded by the Store's execution
    // deadline. The elapsed wall time also includes parsing, lowering,
    // Wasm emission, and native compilation, so applying the execution limit
    // to it would turn a successful cold compile into a false runtime timeout
    // and prevent the compiled module from reaching the cache.
    if execution_backend != ExecutionBackend::WasmAot && duration_ms > u128::from(timeout_ms) {
        return TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Failed(classify_failure(
                case.execution_id.clone(),
                FailureKind::Runtime,
                format!("timeout exceeded after {}ms", duration_ms),
            )),
            duration_ms: Some(duration_ms),
        };
    }

    match outcome {
        Ok(()) => TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Passed,
            duration_ms: Some(duration_ms),
        },
        Err(failure) => TestResult {
            test_id: case.execution_id.clone(),
            status: TestStatus::Failed(failure),
            duration_ms: Some(duration_ms),
        },
    }
}

fn compile_negative_error_matches(
    err: &scriptw_engine::EngineError,
    negative: &NegativeExpectation,
) -> bool {
    if err.is_global_prelude_failure() {
        return false;
    }
    let expected = negative.phase;
    if let Some(diagnostic) = err.parse_diagnostic() {
        // Both sides are now closed domains, so the cross-product is spelled
        // out: a new `ParseDiagnosticPhase` or a new `NegativePhase` is E0004
        // here rather than a silently-false comparison.
        let phase_matches = match (diagnostic.phase(), expected) {
            (scriptw_front::ParseDiagnosticPhase::Parse, NegativePhase::Parse) => true,
            (
                scriptw_front::ParseDiagnosticPhase::Early,
                NegativePhase::Parse | NegativePhase::Early,
            ) => true,
            (scriptw_front::ParseDiagnosticPhase::Parse, NegativePhase::Early)
            | (
                scriptw_front::ParseDiagnosticPhase::Parse
                | scriptw_front::ParseDiagnosticPhase::Early,
                NegativePhase::Resolution | NegativePhase::Runtime,
            ) => false,
        };
        // `error_type()` is `None` for `ParseCode::UnsupportedParserFeature`,
        // the caught-panic case — a compiler gap, not a program ECMAScript
        // rejects. Requiring `Some` here (rather than only comparing when the
        // expectation names a type) is what stops a source that merely crashed
        // boa's parser from being scored as a pass for every `parse`/
        // `SyntaxError` negative: its phase is already `Parse`, so the phase
        // test alone admits it. Clause 17: an implementation must not treat
        // other kinds of error as early errors.
        return phase_matches
            && diagnostic
                .error_type()
                .is_some_and(|kind| negative.error_type.is_empty() || kind == negative.error_type);
    }
    if let Some(diagnostic) = err.ir_diagnostic() {
        let phase_matches = match (diagnostic.phase(), expected) {
            (IrDiagnosticPhase::Early, NegativePhase::Parse | NegativePhase::Early) => true,
            // A module link failure is what test262 spells `phase: resolution`.
            // An AOT compiler catches it at compile time instead of throwing
            // at runtime, which is honest about what this compiler is.
            (IrDiagnosticPhase::Resolution, NegativePhase::Resolution) => true,
            (
                IrDiagnosticPhase::Lowering,
                NegativePhase::Early | NegativePhase::Resolution | NegativePhase::Runtime,
            ) => true,
            (IrDiagnosticPhase::Early, NegativePhase::Resolution | NegativePhase::Runtime)
            | (
                IrDiagnosticPhase::Resolution,
                NegativePhase::Parse | NegativePhase::Early | NegativePhase::Runtime,
            )
            | (IrDiagnosticPhase::Lowering, NegativePhase::Parse) => false,
        };
        // `code().is_some()` is exactly "this is a spec rejection, not a
        // compiler gap" — the same predicate the old two-variant `matches!`
        // stated, said once and in terms of the thing that decides it.
        //
        // The error-type comparison must not go the other way round.
        // `NativeErrorKind::from_str(&negative.error_type)` returns `None` for a
        // `negative.error_type` outside the nine-name domain (`Test262Error`,
        // say), and `None == diagnostic.error_type()` would then turn an
        // unmatched expectation into a match.
        return phase_matches
            && diagnostic.code().is_some()
            && (negative.error_type.is_empty()
                || diagnostic
                    .error_type()
                    .is_some_and(|kind| kind.as_str() == negative.error_type));
    }

    // Only structured compiler phase/type evidence satisfies a compile
    // negative. Neither a familiar word nor an absent expected type converts
    // a host/compiler failure into an ECMAScript rejection.
    false
}

fn compile_negative_error_detail(err: &scriptw_engine::EngineError) -> String {
    // `NO_SPEC_ERROR_TYPE` names the *absence* of a spec error type: a compiler
    // gap (`Unsupported`, `Lowering`, or a caught parser abort), which by clause
    // 17 must not claim to be an early error.
    const NO_SPEC_ERROR_TYPE: &str = "-";
    if let Some(diagnostic) = err.parse_diagnostic() {
        return format!(
            "{} {} {}: {}",
            diagnostic.code.wire_name(),
            diagnostic.error_type().unwrap_or(NO_SPEC_ERROR_TYPE),
            diagnostic.message,
            err
        );
    }
    if let Some(diagnostic) = err.ir_diagnostic() {
        // `NO_EARLY_ERROR_CODE` names the *absence* of a code — an `Unsupported`
        // or `Lowering` diagnostic. It is spelled once, in
        // `scriptw_front::early_error_code`, beside the closed code domain it must
        // never collide with; assertion P5' proves no `wire_name()` equals it.
        // It must stay a distinct token rather than an `EarlyErrorCode`
        // variant: a code that named the absence of a code would let `Some(_)`
        // mean "none".
        let code = diagnostic.code().map_or(
            scriptw_front::NO_EARLY_ERROR_CODE,
            EarlyErrorCode::wire_name,
        );
        let error_type = diagnostic
            .error_type()
            .map_or(NO_SPEC_ERROR_TYPE, NativeErrorKind::as_str);
        return format!("{code} {error_type} {}: {err}", diagnostic.message);
    }
    err.message().to_string()
}

fn classify_negative_phase(negative: &NegativeExpectation) -> FailureKind {
    negative.phase.failure_kind()
}

fn failure_is_timeout(failure: &FailureRecord) -> bool {
    failure.detail.contains("timeout exceeded")
}

fn summarize_results(results: &[TestResult]) -> RunSummary {
    let mut counts = BTreeMap::new();
    for kind in FailureKind::ALL {
        counts.insert(kind, 0);
    }
    let mut outcome_counts = empty_outcome_counts();

    let mut failures = Vec::new();
    let mut completed_test_ids = Vec::new();
    let mut slowest = results
        .iter()
        .filter_map(|result| {
            result
                .duration_ms
                .map(|time| (result.test_id.clone(), time))
        })
        .collect::<Vec<_>>();
    slowest.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    slowest.truncate(10);

    let mut timeouts = Vec::new();
    let mut passed = 0;
    for result in results {
        completed_test_ids.push(result.test_id.clone());
        match &result.status {
            TestStatus::Passed => {
                passed += 1;
                *outcome_counts.entry(OutcomeKind::Success).or_insert(0) += 1;
            }
            TestStatus::Failed(failure) => {
                *counts.entry(failure.kind).or_insert(0) += 1;
                *outcome_counts.entry(failure.outcome).or_insert(0) += 1;
                if failure_is_timeout(failure) {
                    timeouts.push(failure.test_id.clone());
                }
                let mut failure = failure.clone();
                failure.duration_ms = result.duration_ms.or(failure.duration_ms);
                failures.push(failure);
            }
        }
    }

    RunSummary {
        total: results.len(),
        passed,
        counts_per_kind: counts,
        counts_per_outcome: outcome_counts,
        failures,
        timeouts,
        slowest_tests: slowest,
        completed_test_ids,
    }
}

fn execute_matrix_node(
    config: &SuiteConfig,
    node: &RunMatrixNode,
    run_config: &RunConfig,
    checkpoint_load_policy: ResumeCheckpointLoadPolicy,
) -> Result<(TopLevelRunSummary, RunSummary), String> {
    let manifest = discover_suite(config, Some(&node.filter))?;
    let preludes = load_preludes(config)?;
    let case_lookup = manifest
        .cases
        .iter()
        .cloned()
        .map(|case| (case.execution_id.clone(), case))
        .collect::<BTreeMap<_, _>>();
    let mut cases = Vec::with_capacity(node.case_ids.len());
    for test_id in &node.case_ids {
        let Some(case) = case_lookup.get(test_id) else {
            return Err(format!(
                "matrix node {} references missing execution {}",
                node.node_id, test_id
            ));
        };
        cases.push(case.clone());
    }

    let node_manifest = SuiteManifest {
        pinned_revisions: manifest.pinned_revisions.clone(),
        manifest_hash: matrix_node_manifest_hash(&manifest.pinned_revisions, node),
        filter: Some(node.node_id.clone()),
        cases: cases.clone(),
    };
    let checkpoint_run_identity = CheckpointRunIdentity::matrix(node.node_kind, &node.matrix_path)?;
    let terminal_run_kind = checkpoint_run_identity.terminal_run_kind().to_string();
    let timing = performance_evidence::NodeInvocationTimer::start(config, run_config);
    let summary = summarize_results(&execute_cases(
        config,
        &node_manifest,
        &preludes,
        &cases,
        &RunConfig {
            filter: Some(node.filter.clone()),
            shard_index: 0,
            shard_count: 1,
            resume: run_config.resume,
            snapshot_name: format!(
                "{}-{}",
                run_config.snapshot_name,
                sanitize_filter_for_snapshot(&node.node_id)
            ),
            execution_backend: run_config.execution_backend,
            max_matrix_nodes: None,
        },
        &checkpoint_run_identity,
        checkpoint_load_policy,
    )?);
    let timing = timing.finish();

    let mut snapshot = snapshot_from_summary(
        &node_manifest,
        terminal_run_kind,
        &summary,
        run_config.execution_backend,
    )?;
    snapshot.matrix_path = node.matrix_path.clone();
    let entry = TopLevelRunSummary {
        node_id: node.node_id.clone(),
        node_kind: node.node_kind,
        filter: node.filter.clone(),
        matrix_path: node.matrix_path.clone(),
        total: summary.total,
        passed: summary.passed,
        failed: summary.total.saturating_sub(summary.passed),
        counts_per_kind: summary.counts_per_kind.clone(),
        counts_per_outcome: summary.counts_per_outcome.clone(),
        counts_per_origin: counts_per_origin(&summary.failures),
        manifest_hash: node_manifest.manifest_hash,
    };
    let node_snapshot_name = format!(
        "{}-{}",
        run_config.snapshot_name,
        sanitize_filter_for_snapshot(&node.node_id)
    );
    let node_snapshot_path =
        snapshot_paths_for_name(config, &node_snapshot_name, node_manifest.manifest_hash).json_path;
    validate_complete_node_contract(&snapshot, node, &entry, &node_snapshot_path)?;
    let paths = write_snapshot(config, &snapshot, &node_snapshot_name)?;
    performance_evidence::write_timing(&paths.json_path, &snapshot, node, timing)?;

    Ok((entry, summary))
}

fn run_matrix_node(
    config: &SuiteConfig,
    node: &RunMatrixNode,
    run_config: &RunConfig,
    checkpoint_load_policy: ResumeCheckpointLoadPolicy,
) -> Result<TopLevelRunSummary, String> {
    execute_matrix_node(config, node, run_config, checkpoint_load_policy).map(|(entry, _)| entry)
}

fn counts_per_origin(failures: &[FailureRecord]) -> BTreeMap<FailureOrigin, usize> {
    let mut counts = BTreeMap::new();
    for origin in FailureOrigin::ALL {
        counts.insert(origin, 0);
    }
    for failure in failures {
        *counts.entry(failure.origin).or_insert(0) += 1;
    }
    counts
}

fn empty_outcome_counts() -> BTreeMap<OutcomeKind, usize> {
    let mut counts = BTreeMap::new();
    for outcome in OutcomeKind::ALL {
        counts.insert(outcome, 0);
    }
    counts
}

fn classify_failure_outcome(kind: FailureKind, detail: &str) -> OutcomeKind {
    let lower = detail.to_ascii_lowercase();
    if kind == FailureKind::Unsupported
        || lower.contains("not implemented")
        || lower.contains("unsupported")
        || lower.contains("not supported")
        || lower.contains("stub")
    {
        return OutcomeKind::NotImplemented;
    }

    if lower.contains("panic")
        || lower.contains("panicked")
        || lower.contains("crash")
        || lower.contains("segmentation fault")
        || lower.contains("wasm `unreachable`")
        || lower.contains("worker panic")
        || lower.contains("trapped")
        || lower.contains("timeout exceeded")
    {
        return OutcomeKind::Crash;
    }

    OutcomeKind::Bug
}

fn panic_message(payload: &Box<dyn core::any::Any + Send>) -> String {
    if let Some(message) = payload.downcast_ref::<&'static str>() {
        (*message).to_string()
    } else if let Some(message) = payload.downcast_ref::<String>() {
        message.clone()
    } else {
        "non-string panic payload".to_string()
    }
}

fn install_test262_panic_hook() {
    TEST262_PANIC_HOOK.call_once(|| {
        let default_hook = panic::take_hook();
        panic::set_hook(Box::new(move |info| {
            let message = if let Some(message) = info.payload().downcast_ref::<&'static str>() {
                *message
            } else if let Some(message) = info.payload().downcast_ref::<String>() {
                message.as_str()
            } else {
                ""
            };
            let is_boa_parser_abort = info
                .location()
                .is_some_and(|location| location.file().contains("boa_parser"))
                && message.contains("you cannot skip more than");
            if !is_boa_parser_abort {
                default_hook(info);
            }
        }));
    });
}

