fn is_expected_negative_exception(
    err: &EngineError,
    backend: ExecutionBackend,
    phase: NegativePhase,
) -> bool {
    if err.is_global_prelude_failure() {
        return false;
    }
    match backend {
        ExecutionBackend::WasmAot => {
            err.wasm_execution_failure_kind() == Some(WasmExecutionFailureKind::JavaScriptException)
        }
        ExecutionBackend::SpecExec => match phase {
            NegativePhase::Runtime => {
                err.oracle_javascript_exception_phase()
                    == Some(scriptw_engine::OracleExceptionPhase::Runtime)
            }
            NegativePhase::Resolution => {
                err.oracle_javascript_exception_phase()
                    == Some(scriptw_engine::OracleExceptionPhase::Resolution)
            }
            NegativePhase::Parse | NegativePhase::Early => false,
        },
    }
}

fn classify_engine_failure(test_id: TestExecutionId, err: &EngineError) -> FailureRecord {
    let (kind, outcome) = structured_engine_failure(err).unwrap_or_else(|| {
        let kind = classify_engine_error_message(err.message());
        (kind, classify_failure_outcome(kind, err.message()))
    });
    let (kind, origin) = if err.is_global_prelude_failure() {
        (FailureKind::HostHarness, FailureOrigin::LocalHarness)
    } else {
        (kind, classify_engine_failure_origin(err, kind))
    };
    classify_failure_with_outcome(test_id, kind, outcome, origin, err.to_string())
}

/// Engine-owned classifications take precedence over source/user-controlled
/// prose. Historical/unstructured records keep the legacy text classifier.
fn structured_engine_failure(err: &EngineError) -> Option<(FailureKind, OutcomeKind)> {
    if let Some(kind) = err.wasm_execution_failure_kind() {
        return Some(match kind {
            WasmExecutionFailureKind::DynamicSource
            | WasmExecutionFailureKind::SemanticGap
            | WasmExecutionFailureKind::UnavailableCapability => {
                (FailureKind::Unsupported, OutcomeKind::NotImplemented)
            }
            WasmExecutionFailureKind::Trap | WasmExecutionFailureKind::Timeout => {
                (FailureKind::Runtime, OutcomeKind::Crash)
            }
            WasmExecutionFailureKind::JavaScriptException
            | WasmExecutionFailureKind::IncompleteModuleEvaluation
            | WasmExecutionFailureKind::ConcurrentFailure => {
                (FailureKind::Runtime, OutcomeKind::Bug)
            }
        });
    }
    if let Some(diagnostic) = err.parse_diagnostic() {
        return Some(parse_failure_taxonomy(diagnostic));
    }
    if let Some(diagnostic) = err.ir_diagnostic() {
        if let Some(feature) = diagnostic.unsupported_feature() {
            return Some((
                classify_unsupported_feature(feature),
                OutcomeKind::NotImplemented,
            ));
        }
        return Some(match diagnostic.kind() {
            scriptw_ir::IrDiagnosticKind::EarlyError => (FailureKind::EarlyError, OutcomeKind::Bug),
            scriptw_ir::IrDiagnosticKind::LinkError | scriptw_ir::IrDiagnosticKind::Lowering => {
                (FailureKind::Lowering, OutcomeKind::Bug)
            }
            scriptw_ir::IrDiagnosticKind::Unsupported => {
                (FailureKind::Unsupported, OutcomeKind::NotImplemented)
            }
        });
    }
    if err.is_oracle_entry_syntax_rejection() {
        return Some((FailureKind::Parser, OutcomeKind::Bug));
    }
    if err.oracle_javascript_exception_phase().is_some() {
        return Some((FailureKind::Runtime, OutcomeKind::Bug));
    }
    if err.intl_artifact_identity_error().is_some()
        || err.wasm_gc_capability().is_some()
        || err.wasm_weak_reachability_capability().is_some()
    {
        return Some((FailureKind::WasmBackend, OutcomeKind::Bug));
    }
    None
}

fn parse_failure_taxonomy(
    diagnostic: &scriptw_front::ParseDiagnostic,
) -> (FailureKind, OutcomeKind) {
    match diagnostic.kind() {
        scriptw_front::ParseDiagnosticKind::UnsupportedParserFeature => {
            (FailureKind::Parser, OutcomeKind::NotImplemented)
        }
        scriptw_front::ParseDiagnosticKind::MalformedJavaScript => (
            match diagnostic.phase() {
                scriptw_front::ParseDiagnosticPhase::Parse => FailureKind::Parser,
                scriptw_front::ParseDiagnosticPhase::Early => FailureKind::EarlyError,
            },
            OutcomeKind::Bug,
        ),
    }
}

fn classify_unsupported_feature(feature: UnsupportedFeature) -> FailureKind {
    match feature {
        UnsupportedFeature::DynamicSource(_) => FailureKind::Unsupported,
    }
}

fn classify_engine_error_message(message: &str) -> FailureKind {
    let lower = message.to_ascii_lowercase();
    if lower.contains("local harness host") || lower.contains("host harness") {
        FailureKind::HostHarness
    } else if lower.contains("runtime execution for wasm is not implemented yet")
        || lower.contains("not supported in scriptw-spec-exec")
        || lower.contains("not supported in scriptw")
    {
        FailureKind::Unsupported
    } else if lower.contains("nul byte")
        || lower.contains("parse")
        || lower.contains("syntaxerror")
        || lower.contains("syntax error")
    {
        FailureKind::Parser
    } else if lower.contains("early error") {
        FailureKind::EarlyError
    } else if lower.contains("wasm") && lower.contains("not implemented") {
        FailureKind::WasmBackend
    } else if lower.contains("interpreter-in-wasm")
        || lower.contains("not implemented yet")
        || lower.contains("stub")
    {
        FailureKind::Unsupported
    } else {
        FailureKind::Runtime
    }
}

/// Origin from typed `EngineError` facts only; no message inspection.
fn classify_engine_failure_origin(err: &EngineError, kind: FailureKind) -> FailureOrigin {
    if let Some(failure) = err.wasm_execution_failure_kind() {
        // Wasm-AOT execution failures stay unattributed until each kind has an
        // owner; the exhaustive match forces that decision for new kinds.
        return match failure {
            WasmExecutionFailureKind::JavaScriptException
            | WasmExecutionFailureKind::IncompleteModuleEvaluation
            | WasmExecutionFailureKind::DynamicSource
            | WasmExecutionFailureKind::SemanticGap
            | WasmExecutionFailureKind::UnavailableCapability
            | WasmExecutionFailureKind::ConcurrentFailure
            | WasmExecutionFailureKind::Trap
            | WasmExecutionFailureKind::Timeout => FailureOrigin::Unknown,
        };
    }
    if err.intl_artifact_identity_error().is_some() {
        FailureOrigin::IcuIntl
    } else if err.wasm_gc_capability().is_some()
        || err.wasm_weak_reachability_capability().is_some()
    {
        FailureOrigin::WasmBackend
    } else if err.oracle_javascript_exception_phase().is_some() {
        FailureOrigin::BoaRuntime
    } else if err.is_oracle_entry_syntax_rejection() || err.parse_diagnostic().is_some() {
        FailureOrigin::BoaParser
    } else {
        failure_origin_for_kind(kind)
    }
}

fn snapshot_to_file(snapshot: &ProgressSnapshot) -> SnapshotFile {
    SnapshotFile {
        // The schema projects from the mandatory compiler binding; serialization
        // cannot relabel unbound history as a current compiler's execution.
        snapshot_version: snapshot.snapshot_version(),
        compiler_identity: snapshot.provenance.to_wire(),
        producer: (snapshot.snapshot_version() >= LEGACY_PATH_ONLY_SNAPSHOT_VERSION)
            .then_some(ArtifactProducer::CURRENT),
        matrix_strategy_version: snapshot.matrix_strategy_version,
        execution_backend: snapshot.execution_backend.as_str().to_string(),
        pinned_revisions: SnapshotPinnedRevisions {
            ecma262: snapshot.pinned_revisions.ecma262.clone(),
            test262: snapshot.pinned_revisions.test262.clone(),
        },
        manifest_hash: snapshot.manifest_hash,
        run_kind: snapshot.run_kind.clone(),
        checkpoint_identity: snapshot.checkpoint_identity.clone().map_or(
            WireCheckpointIdentity::Absent,
            WireCheckpointIdentity::present,
        ),
        total: snapshot.total,
        passed: snapshot.passed,
        counts_per_kind: complete_kind_counts(&snapshot.counts_per_kind),
        counts_per_outcome: Some(complete_outcome_counts(&snapshot.counts_per_outcome)),
        slowest_tests: snapshot
            .slowest_tests
            .iter()
            .map(|(test_id, duration_ms)| SnapshotSlowTest {
                test_id: Some(test_id.clone()),
                path: test_id.path().to_string(),
                duration_ms: *duration_ms,
            })
            .collect(),
        timeout_test_ids: WireIdentityList::present(snapshot.timeout_list.clone()),
        timeout_list: WireIdentityList::Absent,
        failures: snapshot
            .failures
            .iter()
            .map(|failure| SnapshotFailureRecord {
                test_id: Some(failure.test_id.clone()),
                test_path: failure.test_path.clone(),
                kind: failure.kind,
                outcome: Some(failure.outcome),
                origin: failure.origin,
                detail: failure.detail.clone(),
                detail_hash: failure.detail_hash,
                duration_ms: failure.duration_ms,
            })
            .collect(),
        completed_test_ids: WireIdentityList::present(snapshot.completed_test_ids.clone()),
        completed_paths: WireIdentityList::Absent,
        matrix_path: snapshot.matrix_path.clone(),
        completed_nodes: snapshot.completed_nodes.clone(),
        aggregate_counts_so_far: complete_kind_counts(&snapshot.aggregate_counts_so_far),
        aggregate_entries: snapshot
            .aggregate_entries
            .iter()
            .map(|entry| SnapshotAggregateEntry {
                node_id: entry.node_id.clone(),
                node_kind: entry.node_kind,
                filter: entry.filter.clone(),
                matrix_path: entry.matrix_path.clone(),
                total: entry.total,
                passed: entry.passed,
                failed: entry.failed,
                counts_per_kind: complete_kind_counts(&entry.counts_per_kind),
                counts_per_outcome: Some(complete_outcome_counts(&entry.counts_per_outcome)),
                counts_per_origin: complete_origin_counts(&entry.counts_per_origin),
                manifest_hash: entry.manifest_hash,
            })
            .collect(),
    }
}

fn parse_snapshot_execution_backend(value: &str) -> Result<ExecutionBackend, String> {
    match value {
        "spec-exec" => Ok(ExecutionBackend::SpecExec),
        "wasm-aot" => Ok(ExecutionBackend::WasmAot),
        _ => Err(format!(
            "snapshot contains unknown execution_backend `{value}`"
        )),
    }
}

fn validate_snapshot_checkpoint_identity(
    file: &SnapshotFile,
    artifact_kind: SnapshotArtifactKind,
) -> Result<(), String> {
    let version = file.snapshot_version;
    if !artifact_kind.has_execution_identity() {
        if file.checkpoint_identity.is_absent() {
            return Ok(());
        }
        return Err(format!(
            "snapshot version {} contains checkpoint_identity; legacy data cannot acquire a v7 terminal execution context",
            file.snapshot_version
        ));
    }

    if file.run_kind == "resume-case-checkpoint" {
        return match &file.checkpoint_identity {
            WireCheckpointIdentity::Absent => Err(format!(
                "snapshot version {version} resume-case-checkpoint is missing checkpoint_identity"
            )),
            WireCheckpointIdentity::Present(None) => Err(format!(
                "snapshot version {version} resume-case-checkpoint has null checkpoint_identity"
            )),
            WireCheckpointIdentity::Present(Some(_)) => Ok(()),
        };
    }

    if file.checkpoint_identity.is_absent() {
        Ok(())
    } else {
        Err(format!(
            "snapshot version {version} terminal run_kind {} must omit checkpoint_identity",
            file.run_kind
        ))
    }
}

fn snapshot_from_file(admitted: AdmittedSnapshot) -> Result<ProgressSnapshot, String> {
    let (file, artifact_kind, provenance) = admitted.into_parts();
    let version = file.snapshot_version;
    if artifact_kind.has_execution_identity() {
        if !file.completed_paths.is_absent() || !file.timeout_list.is_absent() {
            return Err(format!(
                "snapshot version {version} contains path-only completion or timeout identity"
            ));
        }
        if file.completed_test_ids.values().is_none() || file.timeout_test_ids.values().is_none() {
            return Err(format!(
                "snapshot version {version} is missing typed completion or timeout identity fields"
            ));
        }
    } else if !file.failures.is_empty()
        || !file.completed_test_ids.is_absent()
        || !file.completed_paths.is_absent()
        || !file.slowest_tests.is_empty()
        || !file.timeout_test_ids.is_absent()
        || !file.timeout_list.is_absent()
    {
        return Err(format!(
            "snapshot version {} contains per-case evidence or checkpoint identity; legacy data cannot be upgraded or reinterpreted as a Test262 execution mode",
            file.snapshot_version
        ));
    }
    let failures = file
        .failures
        .into_iter()
        .map(|failure| -> Result<_, String> {
            let outcome = snapshot_failure_outcome(
                artifact_kind,
                &failure.test_path,
                failure.kind,
                failure.outcome,
                &failure.detail,
            )?;
            let test_id = failure.test_id.ok_or_else(|| {
                format!(
                    "snapshot version {version} failure {} is missing execution identity",
                    failure.test_path
                )
            })?;
            if test_id.path() != failure.test_path {
                return Err(format!(
                    "snapshot failure execution {} disagrees with physical path {}",
                    test_id, failure.test_path
                ));
            }
            Ok(FailureRecord {
                test_id,
                test_path: failure.test_path,
                kind: failure.kind,
                outcome,
                origin: failure.origin,
                detail: failure.detail,
                detail_hash: failure.detail_hash,
                duration_ms: failure.duration_ms,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let counts_per_outcome = snapshot_outcome_counts(
        artifact_kind,
        "snapshot",
        file.counts_per_outcome,
        file.passed,
        &failures,
    )?;
    let aggregate_entries = file
        .aggregate_entries
        .into_iter()
        .map(|entry| -> Result<_, String> {
            let context = format!("aggregate entry {}", entry.node_id);
            let counts_per_outcome = snapshot_outcome_counts(
                artifact_kind,
                &context,
                entry.counts_per_outcome,
                entry.passed,
                &[],
            )?;
            Ok(TopLevelRunSummary {
                node_id: entry.node_id,
                node_kind: entry.node_kind,
                filter: entry.filter,
                matrix_path: entry.matrix_path,
                total: entry.total,
                passed: entry.passed,
                failed: entry.failed,
                counts_per_kind: complete_kind_counts(&entry.counts_per_kind),
                counts_per_outcome,
                counts_per_origin: complete_origin_counts(&entry.counts_per_origin),
                manifest_hash: entry.manifest_hash,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;

    Ok(ProgressSnapshot {
        provenance,
        matrix_strategy_version: file.matrix_strategy_version,
        execution_backend: parse_snapshot_execution_backend(&file.execution_backend)?,
        pinned_revisions: PinnedRevisions {
            ecma262: file.pinned_revisions.ecma262,
            test262: file.pinned_revisions.test262,
        },
        manifest_hash: file.manifest_hash,
        run_kind: file.run_kind,
        checkpoint_identity: file.checkpoint_identity.into_value(),
        total: file.total,
        passed: file.passed,
        counts_per_kind: complete_kind_counts(&file.counts_per_kind),
        counts_per_outcome,
        slowest_tests: file
            .slowest_tests
            .into_iter()
            .map(|entry| {
                let test_id = entry.test_id.ok_or_else(|| {
                    format!(
                        "snapshot version {version} slow-case record {} is missing execution identity",
                        entry.path
                    )
                })?;
                if test_id.path() != entry.path {
                    return Err(format!(
                        "snapshot slow-case execution {} disagrees with physical path {}",
                        test_id, entry.path
                    ));
                }
                Ok((test_id, entry.duration_ms))
            })
            .collect::<Result<Vec<_>, String>>()?,
        timeout_list: file.timeout_test_ids.into_values().unwrap_or_default(),
        failures,
        completed_test_ids: file.completed_test_ids.into_values().unwrap_or_default(),
        matrix_path: file.matrix_path,
        completed_nodes: file.completed_nodes,
        aggregate_counts_so_far: complete_kind_counts(&file.aggregate_counts_so_far),
        aggregate_entries,
    })
}

fn snapshot_failure_outcome(
    artifact_kind: SnapshotArtifactKind,
    test_path: &str,
    kind: FailureKind,
    outcome: Option<OutcomeKind>,
    detail: &str,
) -> Result<OutcomeKind, String> {
    match (artifact_kind, outcome) {
        (SnapshotArtifactKind::LegacyV4, None) => Ok(classify_failure_outcome(kind, detail)),
        (SnapshotArtifactKind::LegacyV4, Some(_)) => Err(format!(
            "snapshot version {LEGACY_PRE_OUTCOME_SNAPSHOT_VERSION} failure {test_path} must omit outcome data"
        )),
        (
            SnapshotArtifactKind::LegacyV5
            | SnapshotArtifactKind::LegacyPathOnlyV6
            | SnapshotArtifactKind::LegacyExecutionIdentityV7
            | SnapshotArtifactKind::CurrentScriptwV8,
            Some(outcome),
        ) => Ok(outcome),
        (SnapshotArtifactKind::LegacyV5 | SnapshotArtifactKind::LegacyPathOnlyV6, None) => {
            Err(format!(
                "snapshot version {LEGACY_PRE_SCRIPTW_SNAPSHOT_VERSION} failure {test_path} is missing required outcome data"
            ))
        }
        (SnapshotArtifactKind::LegacyExecutionIdentityV7, None) => Err(format!(
            "snapshot version {LEGACY_EXECUTION_IDENTITY_SNAPSHOT_VERSION} failure {test_path} is missing required outcome data"
        )),
        (SnapshotArtifactKind::CurrentScriptwV8, None) => Err(format!(
            "snapshot version {SNAPSHOT_VERSION} failure {test_path} is missing required outcome data"
        )),
    }
}

fn snapshot_outcome_counts(
    artifact_kind: SnapshotArtifactKind,
    context: &str,
    counts: Option<BTreeMap<OutcomeKind, usize>>,
    passed: usize,
    failures: &[FailureRecord],
) -> Result<BTreeMap<OutcomeKind, usize>, String> {
    match (artifact_kind, counts) {
        (SnapshotArtifactKind::LegacyV4, None) => {
            let mut counts = empty_outcome_counts();
            counts.insert(OutcomeKind::Success, passed);
            for failure in failures {
                *counts.entry(failure.outcome).or_insert(0) += 1;
            }
            Ok(counts)
        }
        (SnapshotArtifactKind::LegacyV4, Some(_)) => Err(format!(
            "snapshot version {LEGACY_PRE_OUTCOME_SNAPSHOT_VERSION} {context} must omit outcome counts"
        )),
        (
            SnapshotArtifactKind::LegacyV5
            | SnapshotArtifactKind::LegacyPathOnlyV6
            | SnapshotArtifactKind::LegacyExecutionIdentityV7
            | SnapshotArtifactKind::CurrentScriptwV8,
            Some(counts),
        ) => Ok(complete_outcome_counts(&counts)),
        (SnapshotArtifactKind::LegacyV5 | SnapshotArtifactKind::LegacyPathOnlyV6, None) => {
            Err(format!(
                "snapshot version {LEGACY_PRE_SCRIPTW_SNAPSHOT_VERSION} {context} is missing required outcome counts"
            ))
        }
        (SnapshotArtifactKind::LegacyExecutionIdentityV7, None) => Err(format!(
            "snapshot version {LEGACY_EXECUTION_IDENTITY_SNAPSHOT_VERSION} {context} is missing required outcome counts"
        )),
        (SnapshotArtifactKind::CurrentScriptwV8, None) => Err(format!(
            "snapshot version {SNAPSHOT_VERSION} {context} is missing required outcome counts"
        )),
    }
}

fn complete_kind_counts(counts: &BTreeMap<FailureKind, usize>) -> BTreeMap<FailureKind, usize> {
    FailureKind::ordered_counts(counts).collect()
}

fn complete_outcome_counts(counts: &BTreeMap<OutcomeKind, usize>) -> BTreeMap<OutcomeKind, usize> {
    OutcomeKind::ordered_counts(counts).collect()
}

fn complete_origin_counts(
    counts: &BTreeMap<FailureOrigin, usize>,
) -> BTreeMap<FailureOrigin, usize> {
    FailureOrigin::ordered_counts(counts).collect()
}

fn render_snapshot_json(snapshot: &ProgressSnapshot) -> String {
    serde_json::to_string_pretty(&snapshot_to_file(snapshot))
        .map(|json| format!("{json}\n"))
        .unwrap_or_else(|err| {
            format!(
                "{{\"snapshot_error\":\"{}\"}}\n",
                json_escape(&err.to_string())
            )
        })
}

fn render_human_summary(snapshot: &ProgressSnapshot) -> String {
    let failed = snapshot.total.saturating_sub(snapshot.passed);
    let mut out = String::new();
    writeln!(
        &mut out,
        "test262 {} summary (snapshot v{})",
        snapshot.run_kind,
        snapshot.snapshot_version()
    )
    .unwrap();
    writeln!(&mut out, "producer={}", ArtifactProducer::CURRENT.as_str()).unwrap();
    match &snapshot.provenance {
        SnapshotProvenance::Current(identity) => {
            writeln!(
                &mut out,
                "compiler_identity={}",
                serde_json::to_string(identity).expect("checked compiler identity serializes")
            )
            .unwrap();
        }
        SnapshotProvenance::LegacyUnbound(version) => {
            writeln!(
                &mut out,
                "compiler_identity=legacy-unbound-v{}",
                version.version()
            )
            .unwrap();
        }
    }
    writeln!(
        &mut out,
        "execution_backend={}",
        snapshot.execution_backend.as_str()
    )
    .unwrap();
    writeln!(
        &mut out,
        "matrix_strategy_version={}",
        snapshot.matrix_strategy_version
    )
    .unwrap();
    writeln!(
        &mut out,
        "pinned: ecma262={} test262={}",
        snapshot.pinned_revisions.ecma262, snapshot.pinned_revisions.test262
    )
    .unwrap();
    writeln!(
        &mut out,
        "total={} pass={} fail={}",
        snapshot.total, snapshot.passed, failed
    )
    .unwrap();
    for (kind, count) in FailureKind::ordered_counts(&snapshot.counts_per_kind) {
        writeln!(&mut out, "{}={}", kind.as_str(), count).unwrap();
    }
    for (outcome, count) in OutcomeKind::ordered_counts(&snapshot.counts_per_outcome) {
        writeln!(&mut out, "outcome_{}={}", outcome.as_str(), count).unwrap();
    }
    if !snapshot.timeout_list.is_empty() {
        let timeouts = snapshot
            .timeout_list
            .iter()
            .map(TestExecutionId::wire_key)
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(&mut out, "timeouts={timeouts}").unwrap();
    }
    if !snapshot.failures.is_empty() {
        writeln!(&mut out, "top_failures:").unwrap();
        for failure in snapshot.failures.iter().take(10) {
            writeln!(
                &mut out,
                "- {} [{}] {}",
                failure.test_id,
                format!(
                    "{}/{}/{}",
                    failure.outcome.as_str(),
                    failure.kind.as_str(),
                    failure.origin.as_str()
                ),
                failure.detail
            )
            .unwrap();
        }
    }
    out
}

fn load_resume_aggregate_snapshot(
    config: &SuiteConfig,
    snapshot_name: &str,
    expected_manifest_hash: u64,
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
) -> Result<Option<ProgressSnapshot>, String> {
    let exact_path = config
        .snapshot_dir
        .join(format!("{snapshot_name}-{expected_manifest_hash}.json"));
    let mut candidates = Vec::new();
    if exact_path.exists() {
        let file = read_snapshot_file(&exact_path)?;
        file.require_running(&exact_path, "resume aggregate snapshot")?;
        if file.matrix_strategy_version != MATRIX_STRATEGY_VERSION {
            return Err(format!(
                "resume snapshot mismatch for matrix_strategy_version in {}: expected {}, found {}",
                exact_path.display(),
                MATRIX_STRATEGY_VERSION,
                file.matrix_strategy_version
            ));
        }
        if file.run_kind != "aggregate-matrix" {
            return Err(format!(
                "resume snapshot mismatch for run_kind in {}: expected aggregate-matrix, found {}",
                exact_path.display(),
                file.run_kind
            ));
        }
        if validate_resume_aggregate_snapshot(
            config,
            &file,
            &exact_path,
            expected_manifest_hash,
            expected_backend,
            expected_pinned,
            &SnapshotUse::CurrentState,
        )
        .is_ok()
        {
            return snapshot_from_file(file).map(Some);
        }
        candidates.push(exact_path);
    }

    let prefix = format!("{snapshot_name}-");
    let mut fallback_candidates = fs::read_dir(&config.snapshot_dir)
        .ok()
        .into_iter()
        .flat_map(|entries| entries.filter_map(Result::ok))
        .map(|entry| entry.path())
        .filter(|path| {
            path.extension().and_then(|value| value.to_str()) == Some("json")
                && path
                    .file_name()
                    .and_then(|value| value.to_str())
                    .is_some_and(|name| name.starts_with(&prefix))
        })
        .collect::<Vec<_>>();
    fallback_candidates.sort();
    while let Some(path) = fallback_candidates.pop() {
        if !candidates.iter().any(|candidate| candidate == &path) {
            candidates.push(path);
        }
    }

    let mut candidates = candidates.into_iter();
    let Some(path) = candidates.next() else {
        return Ok(None);
    };
    let mut current = Some(path);
    while let Some(path) = current {
        let file = read_snapshot_file(&path)?;
        file.require_running(&path, "resume aggregate snapshot")?;
        if validate_resume_aggregate_snapshot(
            config,
            &file,
            &path,
            expected_manifest_hash,
            expected_backend,
            expected_pinned,
            &SnapshotUse::CurrentState,
        )
        .is_ok()
        {
            return snapshot_from_file(file).map(Some);
        }
        current = candidates.next();
    }
    Ok(None)
}

fn validate_resume_aggregate_snapshot(
    config: &SuiteConfig,
    file: &AdmittedSnapshot,
    path: &Path,
    expected_manifest_hash: u64,
    expected_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
    snapshot_use: &SnapshotUse,
) -> Result<(), String> {
    match snapshot_use {
        SnapshotUse::CurrentState => {
            file.require_running(path, "current aggregate snapshot")?;
        }
        SnapshotUse::ReadOnlyEvidence => {
            file.require_current(path, "read-only compiler-bound aggregate")?;
        }
    }
    if file.matrix_strategy_version != MATRIX_STRATEGY_VERSION {
        return Err(format!(
            "resume snapshot mismatch for matrix_strategy_version in {}: expected {}, found {}",
            path.display(),
            MATRIX_STRATEGY_VERSION,
            file.matrix_strategy_version
        ));
    }
    if file.execution_backend != expected_backend.as_str() {
        return Err(format!(
            "resume snapshot mismatch for execution_backend in {}: expected {}, found {}",
            path.display(),
            expected_backend.as_str(),
            file.execution_backend
        ));
    }
    if file.manifest_hash != expected_manifest_hash {
        return Err(format!(
            "resume snapshot mismatch for manifest_hash in {}: expected {}, found {}",
            path.display(),
            expected_manifest_hash,
            file.manifest_hash
        ));
    }
    if file.run_kind != "aggregate-matrix" {
        return Err(format!(
            "resume snapshot mismatch for run_kind in {}: expected aggregate-matrix, found {}",
            path.display(),
            file.run_kind
        ));
    }
    if file.pinned_revisions.ecma262 != expected_pinned.ecma262 {
        return Err(format!(
            "resume snapshot mismatch for ecma262 revision in {}: expected {}, found {}",
            path.display(),
            expected_pinned.ecma262,
            file.pinned_revisions.ecma262
        ));
    }
    let recorded_pinned = PinnedRevisions {
        ecma262: file.pinned_revisions.ecma262.clone(),
        test262: file.pinned_revisions.test262.clone(),
    };
    if !test262_pins_equivalent(config, &recorded_pinned, expected_pinned) {
        return Err(format!(
            "resume snapshot mismatch for test262 revision in {}: expected {} (or a pin whose vendored suite content verifies as identical), found {}",
            path.display(),
            expected_pinned.test262,
            file.pinned_revisions.test262
        ));
    }
    Ok(())
}

fn load_previous_snapshot(
    config: &SuiteConfig,
    snapshot_name: &str,
    identity: ResumeCheckpointIdentity,
    checkpoint_load_policy: ResumeCheckpointLoadPolicy,
) -> Result<Option<ProgressSnapshot>, String> {
    checkpoint_load_policy.resolve(load_previous_snapshot_checked(
        config,
        snapshot_name,
        &identity,
    ))
}

fn load_previous_snapshot_checked(
    config: &SuiteConfig,
    snapshot_name: &str,
    identity: &ResumeCheckpointIdentity,
) -> Result<Option<ProgressSnapshot>, ResumeCheckpointLoadError> {
    let path = config
        .snapshot_dir
        .join(format!("{snapshot_name}-{}.json", identity.manifest_hash));
    let exists = path.try_exists().map_err(|err| {
        ResumeCheckpointLoadError::integrity(format!(
            "failed to inspect resume checkpoint {}: {err}",
            path.display()
        ))
    })?;
    if !exists {
        return Ok(None);
    }
    let file = read_snapshot_file(&path).map_err(ResumeCheckpointLoadError::integrity)?;
    // Resume merges new results into the snapshot, so a legacy artifact is a
    // hard boundary rather than an absent checkpoint. Treating it as absent
    // would let the next checkpoint overwrite evidence in place.
    file.require_running(&path, "resume checkpoint")
        .map_err(ResumeCheckpointLoadError::integrity)?;
    if file.execution_backend != identity.execution_backend.as_str() {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Checkpoint,
            StaleEnvelopeField::ExecutionBackend,
            &path,
            &identity.execution_backend.as_str(),
            &file.execution_backend,
        ));
    }
    if file.matrix_strategy_version != MATRIX_STRATEGY_VERSION {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Checkpoint,
            StaleEnvelopeField::MatrixStrategy,
            &path,
            &MATRIX_STRATEGY_VERSION,
            &file.matrix_strategy_version,
        ));
    }
    if file.pinned_revisions.ecma262 != identity.pinned_revisions.ecma262 {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Checkpoint,
            StaleEnvelopeField::Ecma262Revision,
            &path,
            &identity.pinned_revisions.ecma262,
            &file.pinned_revisions.ecma262,
        ));
    }
    let recorded_pinned = PinnedRevisions {
        ecma262: file.pinned_revisions.ecma262.clone(),
        test262: file.pinned_revisions.test262.clone(),
    };
    if !test262_pins_equivalent(config, &recorded_pinned, &identity.pinned_revisions) {
        return Err(ResumeCheckpointLoadError::stale(
            ResumeEnvelopeKind::Checkpoint,
            StaleEnvelopeField::Test262Revision,
            &path,
            &identity.pinned_revisions.test262,
            &file.pinned_revisions.test262,
        ));
    }
    if file.manifest_hash != identity.manifest_hash {
        return Err(ResumeCheckpointLoadError::integrity(format!(
            "resume checkpoint mismatch for manifest_hash in {}: expected {}, found {}",
            path.display(),
            identity.manifest_hash,
            file.manifest_hash
        )));
    }
    let recomputed_manifest_hash = hash_manifest_execution_ids(
        &recorded_pinned,
        &identity.selected_test_ids,
        identity.manifest_filter.as_deref(),
    );
    if file.manifest_hash != recomputed_manifest_hash {
        return Err(ResumeCheckpointLoadError::integrity(format!(
            "resume checkpoint integrity failure for manifest_hash in {}: accepted recorded pins and exact selected execution set recompute to {}, body records {}",
            path.display(),
            recomputed_manifest_hash,
            file.manifest_hash
        )));
    }
    let case_requirement = direct_snapshot_case_requirement(
        identity.kind,
        &identity.checkpoint_run_identity,
        &file.run_kind,
        file.checkpoint_identity.value(),
        &file.matrix_path,
    )
    .map_err(|err| {
        ResumeCheckpointLoadError::integrity(format!(
            "resume checkpoint mismatch in {}: {err}",
            path.display()
        ))
    })?;
    let snapshot = snapshot_from_file(file).map_err(ResumeCheckpointLoadError::integrity)?;
    validate_case_snapshot_contract(
        &snapshot,
        &identity.selected_test_ids,
        case_requirement,
        &format!("resume checkpoint {}", path.display()),
    )
    .map_err(ResumeCheckpointLoadError::integrity)?;
    Ok(Some(snapshot))
}

struct ResolvedAggregateSnapshot {
    snapshot_name: String,
    snapshot_paths: SnapshotPaths,
    file: AdmittedSnapshot,
}

fn aggregate_snapshot_paths(
    config: &SuiteConfig,
    snapshot_name: &str,
    manifest_hash: u64,
) -> SnapshotPaths {
    SnapshotPaths {
        json_path: config
            .snapshot_dir
            .join(format!("{snapshot_name}-aggregate-{manifest_hash}.json")),
        txt_path: config
            .snapshot_dir
            .join(format!("{snapshot_name}-aggregate-{manifest_hash}.txt")),
    }
}

/// Honest aggregate snapshot resolution.
///
/// When the requested snapshot name has an aggregate file for the current
/// matrix, that exact file is used and must validate. When it does not, the
/// snapshot directory is searched for aggregates of the *same* matrix (same
/// manifest hash) published under other names; a candidate is only usable if
/// it fully validates (backend, versions, run kind, verified pin
/// equivalence). The requested name resolves to such a candidate only when it
/// is unambiguous; zero or multiple compatible candidates are explicit
/// errors, never a silent pick.
fn resolve_aggregate_snapshot(
    config: &SuiteConfig,
    snapshot_name: &str,
    manifest_hash: u64,
    execution_backend: ExecutionBackend,
    expected_pinned: &PinnedRevisions,
    snapshot_use: SnapshotUse,
    nodes: &[RunMatrixNode],
    evidence_requirement: AggregateEvidenceRequirement,
) -> Result<ResolvedAggregateSnapshot, AggregateLoadError> {
    let exact_paths = aggregate_snapshot_paths(config, snapshot_name, manifest_hash);
    if exact_paths.json_path.try_exists().map_err(|error| {
        format!(
            "cannot inspect aggregate {}: {error}",
            exact_paths.json_path.display()
        )
    })? {
        let file = read_snapshot_file(&exact_paths.json_path)?;
        validate_resume_aggregate_snapshot(
            config,
            &file,
            &exact_paths.json_path,
            manifest_hash,
            execution_backend,
            expected_pinned,
            &snapshot_use,
        )?;
        return Ok(ResolvedAggregateSnapshot {
            snapshot_name: snapshot_name.to_string(),
            snapshot_paths: exact_paths,
            file,
        });
    }

    let suffix = format!("-aggregate-{manifest_hash}.json");
    let mut candidate_names = match fs::read_dir(&config.snapshot_dir) {
        Ok(entries) => entries
            .map(|entry| {
                entry.map_err(|error| {
                    format!(
                        "cannot enumerate aggregates in {}: {error}",
                        config.snapshot_dir.display()
                    )
                })
            })
            .collect::<Result<Vec<_>, _>>()?
            .into_iter()
            .filter_map(|entry| entry.file_name().to_str().map(str::to_string))
            .filter_map(|file_name| {
                file_name
                    .strip_suffix(&suffix)
                    .filter(|name| !name.is_empty() && *name != snapshot_name)
                    .map(str::to_string)
            })
            .collect::<Vec<_>>(),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(error) => {
            return Err(format!(
                "cannot read aggregate directory {}: {error}",
                config.snapshot_dir.display()
            )
            .into());
        }
    };
    candidate_names.sort();
    candidate_names.dedup();

    let mut compatible = Vec::new();
    let mut incompatible = Vec::new();
    for candidate_name in candidate_names {
        let candidate_paths = aggregate_snapshot_paths(config, &candidate_name, manifest_hash);
        let Ok(file) = read_snapshot_file(&candidate_paths.json_path) else {
            incompatible.push(candidate_name);
            continue;
        };
        let envelope = validate_resume_aggregate_snapshot(
            config,
            &file,
            &candidate_paths.json_path,
            manifest_hash,
            execution_backend,
            expected_pinned,
            &snapshot_use,
        );
        let candidate = ResolvedAggregateSnapshot {
            snapshot_name: candidate_name.clone(),
            snapshot_paths: candidate_paths,
            file,
        };
        let evidence = envelope.and_then(|()| match &evidence_requirement {
            AggregateEvidenceRequirement::Envelope => Ok(()),
            AggregateEvidenceRequirement::Complete => {
                load_and_validate_resolved_aggregate_evidence(
                    config,
                    &candidate,
                    nodes,
                    execution_backend,
                )
                .map_err(String::from)?;
                Ok(())
            }
        });
        match evidence {
            Ok(()) => compatible.push(candidate),
            Err(_) => incompatible.push(candidate_name),
        }
    }

    match compatible.len() {
        1 => Ok(compatible.remove(0)),
        0 => {
            let incompatible_note = if incompatible.is_empty() {
                String::new()
            } else {
                format!(
                    "; {} incompatible candidate(s) were rejected: [{}]",
                    incompatible.len(),
                    incompatible.join(", ")
                )
            };
            let detail = format!(
                "missing aggregate snapshot {}; no compatible {} aggregate snapshot for manifest hash {} exists in {}{}",
                exact_paths.json_path.display(),
                execution_backend.as_str(),
                manifest_hash,
                config.snapshot_dir.display(),
                incompatible_note,
            );
            Err(if incompatible.is_empty() {
                AggregateLoadError::Missing(detail)
            } else {
                AggregateLoadError::Invalid(detail)
            })
        }
        _ => Err(AggregateLoadError::Ambiguous(format!(
            "ambiguous aggregate snapshot {}; multiple compatible aggregate snapshots exist for manifest hash {}: [{}]; pass an explicit snapshot name to pick one",
            exact_paths.json_path.display(),
            manifest_hash,
            compatible
                .iter()
                .map(|candidate| candidate.snapshot_name.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        ))),
    }
}

fn checked_count_sum<'a>(
    counts: impl IntoIterator<Item = &'a usize>,
    context: &str,
) -> Result<usize, String> {
    counts.into_iter().try_fold(0usize, |total, count| {
        total
            .checked_add(*count)
            .ok_or_else(|| format!("{context} count overflow"))
    })
}

fn validate_summary_count_contract(
    context: &str,
    total: usize,
    passed: usize,
    failed: usize,
    counts_per_kind: &BTreeMap<FailureKind, usize>,
    counts_per_outcome: &BTreeMap<OutcomeKind, usize>,
    counts_per_origin: &BTreeMap<FailureOrigin, usize>,
) -> Result<(), String> {
    if passed > total || failed != total - passed {
        return Err(format!(
            "{context} has inconsistent total/passed/failed counts: total={total} passed={passed} failed={failed}"
        ));
    }

    let kind_total = checked_count_sum(counts_per_kind.values(), context)?;
    if kind_total != failed {
        return Err(format!(
            "{context} failure-kind counts sum to {kind_total}, expected {failed}"
        ));
    }

    let outcome_total = checked_count_sum(counts_per_outcome.values(), context)?;
    let success = counts_per_outcome
        .get(&OutcomeKind::Success)
        .copied()
        .unwrap_or(0);
    if outcome_total != total || success != passed {
        return Err(format!(
            "{context} outcome counts do not reconcile: sum={outcome_total} Success={success}, expected total={total} passed={passed}"
        ));
    }

    let origin_total = checked_count_sum(counts_per_origin.values(), context)?;
    if origin_total != failed {
        return Err(format!(
            "{context} failure-origin counts sum to {origin_total}, expected {failed}"
        ));
    }
    Ok(())
}

/// Prove that the persisted matrix itself covers the discovered suite once.
///
/// A cache key proves which pin and strategy produced a cache file; it does
/// not prove that the file was not truncated or hand-edited afterward. The
/// publication boundary therefore compares the matrix case union with a fresh
/// discovery before trusting an aggregate built from that matrix.
fn validate_run_matrix_contract(
    nodes: &[RunMatrixNode],
    suite_test_ids: &[TestExecutionId],
) -> Result<(), String> {
    let mut node_ids = BTreeSet::new();
    let mut matrix_ids = BTreeSet::new();
    for node in nodes {
        if !node_ids.insert(node.node_id.as_str()) {
            return Err(format!("run matrix has duplicate node id {}", node.node_id));
        }
        if node.total_cases != node.case_ids.len() {
            return Err(format!(
                "run matrix node {} declares {} cases but contains {} execution ids",
                node.node_id,
                node.total_cases,
                node.case_ids.len()
            ));
        }
        let mut node_test_ids = BTreeSet::new();
        for test_id in &node.case_ids {
            if !node_test_ids.insert(test_id) {
                return Err(format!(
                    "run matrix node {} contains duplicate execution {}",
                    node.node_id, test_id
                ));
            }
            if !matrix_ids.insert(test_id) {
                return Err(format!(
                    "run matrix assigns execution {} to more than one node",
                    test_id
                ));
            }
        }
    }

    let suite_ids = suite_test_ids.iter().collect::<BTreeSet<_>>();
    if suite_ids.len() != suite_test_ids.len() {
        return Err("discovered Test262 manifest contains duplicate execution ids".to_string());
    }
    if matrix_ids != suite_ids {
        let missing = suite_ids
            .difference(&matrix_ids)
            .take(5)
            .map(|id| id.to_string())
            .collect::<Vec<_>>();
        let extra = matrix_ids
            .difference(&suite_ids)
            .take(5)
            .map(|id| id.to_string())
            .collect::<Vec<_>>();
        return Err(format!(
            "run matrix does not cover the discovered Test262 manifest exactly: matrix={} suite={} missing=[{}] extra=[{}]",
            matrix_ids.len(),
            suite_ids.len(),
            missing.join(", "),
            extra.join(", ")
        ));
    }
    Ok(())
}

fn validate_complete_aggregate_contract(
    snapshot: &ProgressSnapshot,
    nodes: &[RunMatrixNode],
    snapshot_path: &Path,
) -> Result<(), AggregateLoadError> {
    let context = format!(
        "aggregate snapshot integrity failure in {}",
        snapshot_path.display()
    );
    if snapshot.matrix_path.len() != 1 || snapshot.matrix_path[0] != "top-level" {
        return Err(AggregateLoadError::Invalid(format!(
            "{context}: matrix_path must be exactly [top-level], found [{}]",
            snapshot.matrix_path.join(", ")
        )));
    }
    if !snapshot.failures.is_empty()
        || !snapshot.completed_test_ids.is_empty()
        || !snapshot.slowest_tests.is_empty()
        || !snapshot.timeout_list.is_empty()
    {
        return Err(AggregateLoadError::Invalid(format!(
            "{context}: aggregate-only snapshot fields must be empty"
        )));
    }

    let expected_nodes = nodes
        .iter()
        .map(|node| (node.node_id.as_str(), node))
        .collect::<BTreeMap<_, _>>();
    let completed_nodes = snapshot
        .completed_nodes
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    if completed_nodes.len() != snapshot.completed_nodes.len() {
        return Err(AggregateLoadError::Invalid(format!(
            "{context}: completed_nodes contains duplicates"
        )));
    }
    let expected_node_ids = expected_nodes.keys().copied().collect::<BTreeSet<_>>();
    let incomplete = if completed_nodes != expected_node_ids {
        let missing = expected_node_ids
            .difference(&completed_nodes)
            .take(5)
            .copied()
            .collect::<Vec<_>>();
        let extra = completed_nodes
            .difference(&expected_node_ids)
            .take(5)
            .copied()
            .collect::<Vec<_>>();
        let detail = format!(
            "aggregate snapshot incomplete in {}: completed {} of {} matrix nodes; missing [{}]; extra [{}]",
            snapshot_path.display(),
            completed_nodes.len(),
            expected_node_ids.len(),
            missing.join(", "),
            extra.join(", ")
        );
        if !extra.is_empty() {
            return Err(AggregateLoadError::Invalid(detail));
        }
        Some(detail)
    } else {
        None
    };

    let mut entries = BTreeMap::new();
    for entry in &snapshot.aggregate_entries {
        if entries.insert(entry.node_id.as_str(), entry).is_some() {
            return Err(AggregateLoadError::Invalid(format!(
                "{context}: duplicate aggregate entry for node {}",
                entry.node_id
            )));
        }
        let Some(node) = expected_nodes.get(entry.node_id.as_str()) else {
            return Err(AggregateLoadError::Invalid(format!(
                "{context}: aggregate entry names unknown node {}",
                entry.node_id
            )));
        };
        if entry.node_kind != node.node_kind
            || entry.filter != node.filter
            || entry.matrix_path != node.matrix_path
            || entry.total != node.total_cases
        {
            return Err(AggregateLoadError::Invalid(format!(
                "{context}: aggregate entry metadata does not match current matrix node {}",
                entry.node_id
            )));
        }
        let expected_hash = matrix_node_manifest_hash(&snapshot.pinned_revisions, node);
        if entry.manifest_hash != expected_hash {
            return Err(AggregateLoadError::Invalid(format!(
                "{context}: aggregate entry {} has manifest hash {}, expected {}",
                entry.node_id, entry.manifest_hash, expected_hash
            )));
        }
        validate_summary_count_contract(
            &format!("{context}: node {}", entry.node_id),
            entry.total,
            entry.passed,
            entry.failed,
            &entry.counts_per_kind,
            &entry.counts_per_outcome,
            &entry.counts_per_origin,
        )?;
    }
    if entries.keys().copied().collect::<BTreeSet<_>>() != completed_nodes {
        return Err(AggregateLoadError::Invalid(format!(
            "{context}: aggregate entries do not cover every completed matrix node"
        )));
    }

    let rebuilt = aggregate_from_entries(&snapshot.aggregate_entries);
    if snapshot.total != rebuilt.total
        || snapshot.passed != rebuilt.passed
        || snapshot.counts_per_kind != rebuilt.counts_per_kind
        || snapshot.counts_per_outcome != rebuilt.counts_per_outcome
        || snapshot.aggregate_counts_so_far != rebuilt.counts_per_kind
    {
        return Err(AggregateLoadError::Invalid(format!(
            "{context}: aggregate totals do not equal the sum of its node entries"
        )));
    }
    validate_summary_count_contract(
        &context,
        rebuilt.total,
        rebuilt.passed,
        rebuilt.failed,
        &rebuilt.counts_per_kind,
        &rebuilt.counts_per_outcome,
        &rebuilt.counts_per_origin,
    )?;
    match incomplete {
        Some(detail) => Err(AggregateLoadError::Incomplete(detail)),
        None => Ok(()),
    }
}

enum CaseSetRequirement {
    UniqueSubset,
    Exact,
}

#[derive(Debug)]
struct SnapshotCaseCounts {
    counts_per_kind: BTreeMap<FailureKind, usize>,
    counts_per_outcome: BTreeMap<OutcomeKind, usize>,
    counts_per_origin: BTreeMap<FailureOrigin, usize>,
}

fn validate_case_snapshot_contract(
    snapshot: &ProgressSnapshot,
    allowed_test_ids: &[TestExecutionId],
    requirement: CaseSetRequirement,
    context: &str,
) -> Result<SnapshotCaseCounts, String> {
    if !snapshot.completed_nodes.is_empty()
        || !snapshot.aggregate_entries.is_empty()
        || snapshot
            .aggregate_counts_so_far
            .values()
            .any(|count| *count != 0)
    {
        return Err(format!(
            "{context}: case snapshot contains aggregate-only fields"
        ));
    }

    let allowed_ids = allowed_test_ids.iter().collect::<BTreeSet<_>>();
    if allowed_ids.len() != allowed_test_ids.len() {
        return Err(format!(
            "{context}: selected execution set contains duplicates"
        ));
    }
    let completed_ids = snapshot.completed_test_ids.iter().collect::<BTreeSet<_>>();
    let (requires_exact_set, case_set_description) = match requirement {
        CaseSetRequirement::UniqueSubset => (false, "subset"),
        CaseSetRequirement::Exact => (true, "exact copy"),
    };
    if snapshot.total != snapshot.completed_test_ids.len()
        || completed_ids.len() != snapshot.completed_test_ids.len()
        || !completed_ids.is_subset(&allowed_ids)
        || (requires_exact_set && completed_ids != allowed_ids)
    {
        return Err(format!(
            "{context}: completed_test_ids must be a unique {} of the selected execution set",
            case_set_description
        ));
    }

    let mut failure_ids = BTreeSet::new();
    let mut counts_per_kind = FailureKind::ALL
        .into_iter()
        .map(|kind| (kind, 0usize))
        .collect::<BTreeMap<_, _>>();
    let mut counts_per_outcome = empty_outcome_counts();
    counts_per_outcome.insert(OutcomeKind::Success, snapshot.passed);
    let mut counts_per_origin = FailureOrigin::ALL
        .into_iter()
        .map(|origin| (origin, 0usize))
        .collect::<BTreeMap<_, _>>();
    for failure in &snapshot.failures {
        if failure.test_id.path() != failure.test_path {
            return Err(format!(
                "{context}: failure execution {} disagrees with physical path {}",
                failure.test_id, failure.test_path
            ));
        }
        if !completed_ids.contains(&failure.test_id) {
            return Err(format!(
                "{context}: failure names execution outside completed set: {}",
                failure.test_id
            ));
        }
        if !failure_ids.insert(&failure.test_id) {
            return Err(format!(
                "{context}: duplicate failure record for {}",
                failure.test_id
            ));
        }
        *counts_per_kind.entry(failure.kind).or_insert(0) += 1;
        *counts_per_outcome.entry(failure.outcome).or_insert(0) += 1;
        *counts_per_origin.entry(failure.origin).or_insert(0) += 1;
    }
    let failed = snapshot.total.checked_sub(snapshot.passed).ok_or_else(|| {
        format!(
            "{context}: passed count {} exceeds total {}",
            snapshot.passed, snapshot.total
        )
    })?;
    if snapshot.failures.len() != failed
        || snapshot.counts_per_kind != counts_per_kind
        || snapshot.counts_per_outcome != counts_per_outcome
    {
        return Err(format!(
            "{context}: totals and classifications do not equal the recorded case results"
        ));
    }

    let timeout_ids = snapshot.timeout_list.iter().collect::<BTreeSet<_>>();
    let expected_timeout_ids = snapshot
        .failures
        .iter()
        .filter(|failure| failure_is_timeout(failure))
        .map(|failure| &failure.test_id)
        .collect::<BTreeSet<_>>();
    if timeout_ids.len() != snapshot.timeout_list.len() || timeout_ids != expected_timeout_ids {
        return Err(format!(
            "{context}: timeout_list must equal the failures classified as timeout"
        ));
    }
    let slowest_ids = snapshot
        .slowest_tests
        .iter()
        .map(|(test_id, _)| test_id)
        .collect::<BTreeSet<_>>();
    if slowest_ids.len() != snapshot.slowest_tests.len() || !slowest_ids.is_subset(&completed_ids) {
        return Err(format!(
            "{context}: slowest_tests must contain unique completed executions only"
        ));
    }

    Ok(SnapshotCaseCounts {
        counts_per_kind,
        counts_per_outcome,
        counts_per_origin,
    })
}

fn validate_complete_node_contract(
    snapshot: &ProgressSnapshot,
    node: &RunMatrixNode,
    entry: &TopLevelRunSummary,
    snapshot_path: &Path,
) -> Result<(), String> {
    let context = format!(
        "matrix node snapshot integrity failure in {}",
        snapshot_path.display()
    );
    if entry.node_id != node.node_id
        || entry.node_kind != node.node_kind
        || entry.filter != node.filter
        || entry.matrix_path != node.matrix_path
        || entry.total != node.total_cases
        || entry.manifest_hash != snapshot.manifest_hash
    {
        return Err(format!(
            "{context}: aggregate entry metadata does not match matrix node {} and its snapshot",
            node.node_id
        ));
    }
    if snapshot.total != node.total_cases || snapshot.completed_test_ids.len() != node.total_cases {
        return Err(format!(
            "{context}: node {} expected {} completed executions, found total={} completed_test_ids={}",
            node.node_id,
            node.total_cases,
            snapshot.total,
            snapshot.completed_test_ids.len()
        ));
    }
    let checkpoint_run_identity = CheckpointRunIdentity::matrix(node.node_kind, &node.matrix_path)?;
    direct_snapshot_case_requirement(
        DirectSnapshotKind::ResumeCheckpoint,
        &checkpoint_run_identity,
        &snapshot.run_kind,
        snapshot.checkpoint_identity.as_ref(),
        &snapshot.matrix_path,
    )
    .map_err(|err| format!("{context}: {err}"))?;
    let counts = validate_case_snapshot_contract(
        snapshot,
        &node.case_ids,
        CaseSetRequirement::Exact,
        &context,
    )?;

    if entry.total != snapshot.total
        || entry.passed != snapshot.passed
        || entry.failed != snapshot.failures.len()
        || entry.counts_per_kind != counts.counts_per_kind
        || entry.counts_per_outcome != counts.counts_per_outcome
        || entry.counts_per_origin != counts.counts_per_origin
    {
        return Err(format!(
            "{context}: aggregate entry {} does not equal its node evidence",
            entry.node_id
        ));
    }
    validate_summary_count_contract(
        &context,
        entry.total,
        entry.passed,
        entry.failed,
        &entry.counts_per_kind,
        &entry.counts_per_outcome,
        &entry.counts_per_origin,
    )
}

fn validate_complete_aggregate_evidence(
    config: &SuiteConfig,
    snapshot_name: &str,
    snapshot_path: &Path,
    snapshot: &ProgressSnapshot,
    nodes: &[RunMatrixNode],
    execution_backend: ExecutionBackend,
) -> Result<(), AggregateLoadError> {
    let suite_test_ids = discover_suite(config, None)?
        .cases
        .into_iter()
        .map(|case| case.execution_id)
        .collect::<Vec<_>>();
    validate_run_matrix_contract(nodes, &suite_test_ids)?;
    let completeness = validate_complete_aggregate_contract(snapshot, nodes, snapshot_path);
    if let Err(error) = &completeness {
        if !matches!(error, AggregateLoadError::Incomplete(_)) {
            return completeness;
        }
    }
    // Even a partial aggregate must prove every recorded node before a caller
    // may resume it. Missing work is recoverable; damaged evidence is not.
    let recorded_nodes = nodes
        .iter()
        .filter(|node| snapshot.completed_nodes.contains(&node.node_id))
        .cloned()
        .collect::<Vec<_>>();
    validate_aggregate_node_evidence(
        config,
        snapshot_name,
        snapshot_path,
        snapshot,
        &recorded_nodes,
        execution_backend,
    )?;
    completeness
}

fn validate_aggregate_node_evidence(
    config: &SuiteConfig,
    snapshot_name: &str,
    snapshot_path: &Path,
    snapshot: &ProgressSnapshot,
    nodes: &[RunMatrixNode],
    execution_backend: ExecutionBackend,
) -> Result<(), String> {
    let entries = snapshot
        .aggregate_entries
        .iter()
        .map(|entry| (entry.node_id.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    for node in nodes {
        let entry = entries
            .get(node.node_id.as_str())
            .expect("aggregate contract proved one entry per node");
        let Some((node_path, file)) = locate_node_snapshot(
            config,
            snapshot_name,
            node,
            execution_backend,
            entry,
            snapshot
                .provenance
                .require_current("complete aggregate evidence")?,
        )?
        else {
            return Err(format!(
                "aggregate snapshot integrity failure in {}: missing node evidence for {}",
                snapshot_path.display(),
                node.node_id
            ));
        };
        let node_snapshot = snapshot_from_file(file)
            .map_err(|err| format!("invalid snapshot data in {}: {err}", node_path.display()))?;
        validate_complete_node_contract(&node_snapshot, node, entry, &node_path)?;
    }
    Ok(())
}

fn load_and_validate_resolved_aggregate_evidence(
    config: &SuiteConfig,
    resolved: &ResolvedAggregateSnapshot,
    nodes: &[RunMatrixNode],
    execution_backend: ExecutionBackend,
) -> Result<ProgressSnapshot, AggregateLoadError> {
    let snapshot = snapshot_from_file(resolved.file.clone()).map_err(|err| {
        format!(
            "invalid snapshot data in {}: {err}",
            resolved.snapshot_paths.json_path.display()
        )
    })?;
    validate_complete_aggregate_evidence(
        config,
        &resolved.snapshot_name,
        &resolved.snapshot_paths.json_path,
        &snapshot,
        nodes,
        execution_backend,
    )?;
    Ok(snapshot)
}

/// Loads complete current aggregate and node evidence.
///
/// Legacy envelopes remain available only through the explicitly metadata-only
/// progress and pin-report workflows; complete evidence is never upgraded from
/// a path-era schema.
fn load_verified_aggregate_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<VerifiedAggregateSummary, String> {
    load_verified_aggregate_summary_for_use(
        config,
        snapshot_name,
        execution_backend,
        SnapshotUse::CurrentState,
    )
    .map_err(Into::into)
}

/// Loads the only aggregate schema that may feed a new publication.
///
/// Publication rejects every legacy version: it must be based on a compiler-bound version-8
/// aggregate whose producer is the closed `Scriptw` identity and whose cases
/// carry execution identity.
fn load_publishable_aggregate_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    publication_backend: PublicationBackend,
) -> Result<VerifiedAggregateSummary, AggregateLoadError> {
    load_verified_aggregate_summary_for_use(
        config,
        snapshot_name,
        publication_backend.as_execution_backend(),
        SnapshotUse::CurrentState,
    )
}

fn load_current_aggregate_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<VerifiedAggregateSummary, String> {
    load_verified_aggregate_summary_for_use(
        config,
        snapshot_name,
        execution_backend,
        SnapshotUse::CurrentState,
    )
    .map_err(Into::into)
}

fn load_verified_aggregate_summary_for_use(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
    snapshot_use: SnapshotUse,
) -> Result<VerifiedAggregateSummary, AggregateLoadError> {
    let nodes = load_or_build_run_matrix(config, execution_backend)?;
    let manifest_hash = hash_matrix_nodes(&nodes, execution_backend);
    let expected_pinned = pinned_revisions(config);
    let resolved = resolve_aggregate_snapshot(
        config,
        snapshot_name,
        manifest_hash,
        execution_backend,
        &expected_pinned,
        snapshot_use,
        &nodes,
        AggregateEvidenceRequirement::Complete,
    )?;
    let recorded_pinned = PinnedRevisions {
        ecma262: resolved.file.pinned_revisions.ecma262.clone(),
        test262: resolved.file.pinned_revisions.test262.clone(),
    };
    let snapshot = load_and_validate_resolved_aggregate_evidence(
        config,
        &resolved,
        &nodes,
        execution_backend,
    )?;
    Ok(VerifiedAggregateSummary {
        compiler_identity: snapshot
            .provenance
            .require_current("aggregate summary")?
            .clone(),
        pinned_revisions: expected_pinned,
        recorded_pinned_revisions: recorded_pinned,
        resolved_snapshot_name: resolved.snapshot_name,
        manifest_hash,
        snapshot_paths: resolved.snapshot_paths,
        summary: aggregate_summary_from_snapshot(&snapshot),
    })
}

fn load_aggregate_progress_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<AggregateProgressSummary, String> {
    let nodes = load_or_build_run_matrix(config, execution_backend)?;
    let expected_node_ids = nodes
        .iter()
        .map(|node| node.node_id.clone())
        .collect::<BTreeSet<_>>();
    let target_total = nodes.iter().map(|node| node.total_cases).sum();
    let manifest_hash = hash_matrix_nodes(&nodes, execution_backend);
    let expected_pinned = pinned_revisions(config);
    let resolved = resolve_aggregate_snapshot(
        config,
        snapshot_name,
        manifest_hash,
        execution_backend,
        &expected_pinned,
        SnapshotUse::CurrentState,
        &nodes,
        AggregateEvidenceRequirement::Envelope,
    )?;
    let recorded_pinned = PinnedRevisions {
        ecma262: resolved.file.pinned_revisions.ecma262.clone(),
        test262: resolved.file.pinned_revisions.test262.clone(),
    };
    let snapshot = snapshot_from_file(resolved.file).map_err(|err| {
        format!(
            "invalid snapshot data in {}: {err}",
            resolved.snapshot_paths.json_path.display()
        )
    })?;
    let recorded_nodes = nodes
        .iter()
        .filter(|node| snapshot.completed_nodes.contains(&node.node_id))
        .cloned()
        .collect::<Vec<_>>();
    validate_complete_aggregate_contract(
        &snapshot,
        &recorded_nodes,
        &resolved.snapshot_paths.json_path,
    )?;
    validate_aggregate_node_evidence(
        config,
        &resolved.snapshot_name,
        &resolved.snapshot_paths.json_path,
        &snapshot,
        &recorded_nodes,
        execution_backend,
    )?;
    let progress = AggregateProgress::from_completed_nodes(
        target_total,
        &snapshot.completed_nodes,
        &expected_node_ids,
    )?;
    Ok(AggregateProgressSummary {
        compiler_identity: snapshot
            .provenance
            .require_current("aggregate summary")?
            .clone(),
        pinned_revisions: expected_pinned,
        recorded_pinned_revisions: recorded_pinned,
        resolved_snapshot_name: resolved.snapshot_name,
        manifest_hash,
        snapshot_paths: resolved.snapshot_paths,
        summary: aggregate_summary_from_snapshot(&snapshot),
        progress,
    })
}

fn load_matrix_triage_entries(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<Vec<MatrixTriageEntry>, String> {
    let progress = load_aggregate_progress_summary(config, snapshot_name, execution_backend)?;
    let mut entries = progress
        .summary
        .entries
        .iter()
        .filter(|entry| entry.failed > 0)
        .map(|entry| MatrixTriageEntry {
            node_id: entry.node_id.clone(),
            filter: entry.filter.clone(),
            matrix_path: entry.matrix_path.clone(),
            total: entry.total,
            passed: entry.passed,
            failed: entry.failed,
            not_implemented: entry
                .counts_per_outcome
                .get(&OutcomeKind::NotImplemented)
                .copied()
                .unwrap_or(0),
            crash: entry
                .counts_per_outcome
                .get(&OutcomeKind::Crash)
                .copied()
                .unwrap_or(0),
            bug: entry
                .counts_per_outcome
                .get(&OutcomeKind::Bug)
                .copied()
                .unwrap_or(0),
        })
        .collect::<Vec<_>>();
    entries.sort_by(|left, right| {
        right
            .crash
            .cmp(&left.crash)
            .then_with(|| right.bug.cmp(&left.bug))
            .then_with(|| right.not_implemented.cmp(&left.not_implemented))
            .then_with(|| right.failed.cmp(&left.failed))
            .then_with(|| left.node_id.cmp(&right.node_id))
    });
    Ok(entries)
}

fn load_matrix_failure_details(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
    node_selector: &str,
) -> Result<MatrixFailureDetails, String> {
    let nodes = load_or_build_run_matrix(config, execution_backend)?;
    let node = select_run_matrix_node(&nodes, node_selector)?;

    let expected_pinned = pinned_revisions(config);
    let aggregate_manifest_hash = hash_matrix_nodes(&nodes, execution_backend);
    let resolved = resolve_aggregate_snapshot(
        config,
        snapshot_name,
        aggregate_manifest_hash,
        execution_backend,
        &expected_pinned,
        SnapshotUse::CurrentState,
        &nodes,
        AggregateEvidenceRequirement::Envelope,
    )?;
    let aggregate = snapshot_from_file(resolved.file.clone()).map_err(|err| {
        format!(
            "invalid snapshot data in {}: {err}",
            resolved.snapshot_paths.json_path.display()
        )
    })?;
    let entry = aggregate
        .aggregate_entries
        .iter()
        .find(|entry| entry.node_id == node.node_id)
        .ok_or_else(|| {
            format!(
                "matrix node {} has no completed entry in aggregate snapshot {}; run that node first",
                node.node_id,
                resolved.snapshot_paths.json_path.display()
            )
        })?;
    let Some(snapshot) = load_completed_node_snapshot(
        config,
        &resolved.snapshot_name,
        node,
        execution_backend,
        entry,
        aggregate
            .provenance
            .require_current("matrix failure details")?,
    )?
    else {
        let node_snapshot_name = format!(
            "{}-{}",
            resolved.snapshot_name,
            sanitize_filter_for_snapshot(&node.node_id)
        );
        let path = config.snapshot_dir.join(format!(
            "{}-{}.json",
            node_snapshot_name, entry.manifest_hash
        ));
        return Err(format!("missing matrix node snapshot {}", path.display()));
    };

    let groups = group_failures_by_detail_identity(&snapshot.failures);

    Ok(MatrixFailureDetails {
        node_id: node.node_id.clone(),
        filter: node.filter.clone(),
        matrix_path: node.matrix_path.clone(),
        total: snapshot.total,
        passed: snapshot.passed,
        failed: snapshot.total.saturating_sub(snapshot.passed),
        groups,
    })
}

/// Group failures by *identity*, not by the stored `detail_hash` and not by the
/// raw detail text.
///
/// Two reasons, and neither is cosmetic. The raw detail embeds a heap address,
/// so keying on it splits one defect into one group per case — the exact
/// failure this grouping exists to prevent. And the stored `detail_hash` was
/// computed by whichever binary wrote the snapshot, so a snapshot recorded
/// before this normalization landed still carries a per-address hash;
/// recomputing here is what lets the same `failure-details` invocation collapse
/// an *existing* corpus instead of only future runs.
///
/// The raw detail survives into the report, taken verbatim from the first
/// representative test, so the reader still sees a real address.
///
/// This is a free function rather than a closure inside
/// `load_matrix_failure_details` for one reason: that function needs a suite
/// config, a run matrix, an aggregate snapshot and a node snapshot on disk
/// before it reaches the grouping, so the grouping could not be tested at all
/// while it lived inline — and it was not. See
/// `failure_detail_grouping_tests`.
fn group_failures_by_detail_identity(failures: &[FailureRecord]) -> Vec<FailureDetailGroup> {
    let mut grouped = BTreeMap::<
        (u64, OutcomeKind, FailureKind, FailureOrigin, String),
        Vec<(String, String)>,
    >::new();
    for failure in failures {
        grouped
            .entry((
                hash_detail(&failure.detail),
                failure.outcome,
                failure.kind,
                failure.origin,
                FailureDetailIdentity::of(&failure.detail).into_string(),
            ))
            .or_default()
            .push((failure.test_id.wire_key(), failure.detail.clone()));
    }
    let mut groups = grouped
        .into_iter()
        .map(
            |((detail_hash, outcome, kind, origin, _identity), mut tests)| {
                tests.sort();
                let count = tests.len();
                let (_, detail) = tests
                    .first()
                    .cloned()
                    .expect("a grouping entry exists only because a failure was pushed into it");
                let mut tests = tests
                    .into_iter()
                    .map(|(test_id, _)| test_id)
                    .collect::<Vec<_>>();
                tests.truncate(5);
                FailureDetailGroup {
                    outcome,
                    kind,
                    origin,
                    detail,
                    detail_hash,
                    count,
                    representative_tests: tests,
                }
            },
        )
        .collect::<Vec<_>>();
    groups.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| outcome_rank(left.outcome).cmp(&outcome_rank(right.outcome)))
            .then_with(|| left.detail.cmp(&right.detail))
    });
    groups
}

fn generate_backlog(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<(BacklogArtifact, BacklogPaths), String> {
    let verified = load_current_aggregate_summary(config, snapshot_name, execution_backend)?;
    let nodes = load_or_build_run_matrix(config, execution_backend)?;
    let cases_by_id = discover_suite(config, None)?
        .cases
        .into_iter()
        .map(|case| (case.execution_id.clone(), case))
        .collect::<BTreeMap<_, _>>();
    let owner_rules = load_backlog_owner_rules(config)?;
    let entries = verified
        .summary
        .entries
        .iter()
        .map(|entry| (entry.node_id.as_str(), entry))
        .collect::<BTreeMap<_, _>>();

    let mut records = Vec::new();
    let mut duration_by_id = BTreeMap::new();
    let mut timeout_ids = BTreeSet::new();
    for node in &nodes {
        let Some(entry) = entries.get(node.node_id.as_str()).copied() else {
            continue;
        };
        let Some(snapshot) = load_completed_node_snapshot(
            config,
            &verified.resolved_snapshot_name,
            node,
            execution_backend,
            entry,
            &verified.compiler_identity,
        )?
        else {
            continue;
        };
        for (test_id, duration_ms) in snapshot.slowest_tests {
            duration_by_id.insert(test_id, duration_ms);
        }
        timeout_ids.extend(snapshot.timeout_list);
        for failure in snapshot.failures {
            let case = cases_by_id.get(&failure.test_id);
            let features = sorted_set_values(case.map(|case| &case.features));
            let flags = sorted_set_values(case.map(|case| &case.flags));
            let includes = case
                .map(|case| case.includes.clone())
                .unwrap_or_default()
                .into_iter()
                .collect::<Vec<_>>();
            let (negative_phase, negative_type) = case
                .and_then(|case| case.negative.as_ref())
                .map(|negative| {
                    (
                        Some(negative.phase.as_str().to_string()),
                        Some(negative.error_type.clone()),
                    )
                })
                .unwrap_or((None, None));
            let normalized_detail = normalize_backlog_detail(&failure.detail);
            let ownership = classify_backlog_owner(&failure, case, &owner_rules);
            records.push(BacklogRecord {
                test_id: failure.test_id.clone(),
                test_path: failure.test_path.clone(),
                features,
                flags,
                includes,
                negative_phase,
                negative_type,
                failure_kind: failure.kind,
                outcome: failure.outcome,
                origin: failure.origin,
                // Hash the normalized detail so the backlog is byte-identical
                // across machines even when raw details embed absolute paths
                // or timing data.
                detail_hash: hash_detail(&normalized_detail),
                normalized_detail,
                duration_ms: failure
                    .duration_ms
                    .or_else(|| duration_by_id.get(&failure.test_id).copied()),
                timed_out: timeout_ids.contains(&failure.test_id)
                    || failure.detail.to_ascii_lowercase().contains("timeout"),
                matrix_node: node.node_id.clone(),
                ownership,
            });
        }
    }
    records.sort_by(|left, right| left.test_id.cmp(&right.test_id));
    if records.len() != verified.summary.failed {
        return Err(format!(
            "backlog record count mismatch for {snapshot_name}: expected {} failures from verified aggregate, collected {} from node snapshots",
            verified.summary.failed,
            records.len()
        ));
    }

    let mut summary_by_task = BTreeMap::new();
    let mut summary_by_feature = BTreeMap::new();
    let mut summary_by_failure_hash = BTreeMap::new();
    let mut slow_by_subtree = BTreeMap::<String, u128>::new();
    for record in &records {
        *summary_by_task
            .entry(record.ownership.owner().to_string())
            .or_insert(0) += 1;
        if record.features.is_empty() {
            *summary_by_feature.entry("(none)".to_string()).or_insert(0) += 1;
        } else {
            for feature in &record.features {
                *summary_by_feature.entry(feature.clone()).or_insert(0) += 1;
            }
        }
        *summary_by_failure_hash
            .entry(format!("{:016x}", record.detail_hash))
            .or_insert(0) += 1;
        if let Some(duration_ms) = record.duration_ms {
            *slow_by_subtree
                .entry(top_level_subtree(&record.test_path))
                .or_insert(0) += duration_ms;
        }
    }
    let mut slowest_subtrees = slow_by_subtree
        .into_iter()
        .map(|(subtree, duration_ms)| BacklogSlowSubtree {
            subtree,
            duration_ms,
        })
        .collect::<Vec<_>>();
    slowest_subtrees.sort_by(|left, right| {
        right
            .duration_ms
            .cmp(&left.duration_ms)
            .then_with(|| left.subtree.cmp(&right.subtree))
    });
    slowest_subtrees.truncate(25);

    let artifact = BacklogArtifact {
        compiler_identity: verified.compiler_identity.clone(),
        snapshot_version: SNAPSHOT_VERSION,
        producer: ArtifactProducer::CURRENT,
        matrix_strategy_version: MATRIX_STRATEGY_VERSION,
        execution_backend,
        pinned_revisions: verified.pinned_revisions.clone(),
        manifest_hash: verified.manifest_hash,
        snapshot_name: verified.resolved_snapshot_name.clone(),
        total: verified.summary.total,
        passed: verified.summary.passed,
        failed: verified.summary.failed,
        records,
        summary_by_task,
        summary_by_feature,
        summary_by_failure_hash,
        slowest_subtrees,
    };
    let paths = write_backlog_artifact(config, &artifact)?;
    Ok((artifact, paths))
}

/// A comparison names two specific runs, not two discovery hints. In particular,
/// a missing baseline must not resolve to the candidate and manufacture an empty
/// diff. Keep the shared complete-evidence validation and discovery behavior for
/// other consumers, but require the requested identity at this boundary.
fn load_comparison_aggregate_summary(
    config: &SuiteConfig,
    snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<VerifiedAggregateSummary, String> {
    let verified = load_verified_aggregate_summary_for_use(
        config,
        snapshot_name,
        execution_backend,
        SnapshotUse::ReadOnlyEvidence,
    )?;
    if verified.resolved_snapshot_name != snapshot_name {
        return Err(format!(
            "snapshot comparison requires exact snapshot name `{snapshot_name}`; only `{}` resolved; refusing to compare a different snapshot",
            verified.resolved_snapshot_name
        ));
    }
    Ok(verified)
}

/// Compare two explicitly named, complete current snapshots.
/// Unlike status/backlog discovery, comparison never substitutes another name.
fn compare_snapshots(
    config: &SuiteConfig,
    base_snapshot_name: &str,
    candidate_snapshot_name: &str,
    execution_backend: ExecutionBackend,
) -> Result<SnapshotComparison, String> {
    let base = load_comparison_aggregate_summary(config, base_snapshot_name, execution_backend)?;
    let candidate =
        load_comparison_aggregate_summary(config, candidate_snapshot_name, execution_backend)?;
    // Refuse to compare snapshots whose suite pins are not verifiably the
    // same suite content. Textual pin differences are accepted only when the
    // git object store proves the vendored suite trees are identical.
    if !test262_pins_equivalent(
        config,
        &base.recorded_pinned_revisions,
        &candidate.recorded_pinned_revisions,
    ) {
        return Err(format!(
            "snapshot pin mismatch: base ecma262={} test262={}, candidate ecma262={} test262={}; refusing to compare snapshots whose test262 pins do not verify as identical suite content",
            base.recorded_pinned_revisions.ecma262,
            base.recorded_pinned_revisions.test262,
            candidate.recorded_pinned_revisions.ecma262,
            candidate.recorded_pinned_revisions.test262
        ));
    }
    if base.manifest_hash != candidate.manifest_hash {
        return Err(format!(
            "snapshot manifest mismatch: base {}, candidate {}",
            base.manifest_hash, candidate.manifest_hash
        ));
    }

    let base_failures = load_failure_map(config, &base, execution_backend)?;
    let candidate_failures = load_failure_map(config, &candidate, execution_backend)?;
    if base_failures.len() != base.summary.failed {
        return Err(format!(
            "failure snapshot count mismatch for {base_snapshot_name}: expected {} failures from verified aggregate, collected {} from node snapshots",
            base.summary.failed,
            base_failures.len()
        ));
    }
    if candidate_failures.len() != candidate.summary.failed {
        return Err(format!(
            "failure snapshot count mismatch for {candidate_snapshot_name}: expected {} failures from verified aggregate, collected {} from node snapshots",
            candidate.summary.failed,
            candidate_failures.len()
        ));
    }
    let mut added_passes = base_failures
        .keys()
        .filter(|test_id| !candidate_failures.contains_key(*test_id))
        .cloned()
        .collect::<Vec<_>>();
    added_passes.sort();
    let mut regressions = candidate_failures
        .keys()
        .filter(|test_id| !base_failures.contains_key(*test_id))
        .cloned()
        .collect::<Vec<_>>();
    regressions.sort();
    let mut changed_failure_hashes = Vec::new();
    for (key, base_failure) in &base_failures {
        let Some(candidate_failure) = candidate_failures.get(key) else {
            continue;
        };
        // Compare hashes of the *normalized* details so unstable data
        // (absolute paths, timestamps, durations) never reports a spurious
        // failure-mode change between two runs of the same suite.
        let base_hash = hash_detail(&normalize_backlog_detail(&base_failure.detail));
        let candidate_hash = hash_detail(&normalize_backlog_detail(&candidate_failure.detail));
        if base_hash != candidate_hash {
            changed_failure_hashes.push(ChangedFailureHash {
                test_id: base_failure.test_id.clone(),
                test_path: base_failure.test_path.clone(),
                base_hash,
                candidate_hash,
            });
        }
    }
    changed_failure_hashes.sort_by(|left, right| left.test_id.cmp(&right.test_id));

    Ok(SnapshotComparison {
        base_compiler_identity: base.compiler_identity.clone(),
        candidate_compiler_identity: candidate.compiler_identity.clone(),
        base_snapshot_name: base_snapshot_name.to_string(),
        candidate_snapshot_name: candidate_snapshot_name.to_string(),
        execution_backend,
        pinned_revisions: base.pinned_revisions,
        base_total: base.summary.total,
        candidate_total: candidate.summary.total,
        added_passes,
        regressions,
        changed_failure_hashes,
    })
}

/// Build an explicit pin report over every aggregate snapshot on disk.
///
/// Each aggregate's recorded pins are classified against the current vendored
/// suite content: `Exact` (same pin string), `ContentEquivalent` (different
/// string, but the git object store verifies identical suite content), or
/// `Mismatch` (unverifiable — such snapshots are refused by merge/compare
/// paths). The report is deterministic (sorted by file name) and read-only.
fn snapshot_pin_report(config: &SuiteConfig) -> Result<SnapshotPinReport, String> {
    let current = pinned_revisions(config);
    let mut file_names = fs::read_dir(&config.snapshot_dir)
        .map_err(|err| {
            format!(
                "failed to read snapshot dir {}: {err}",
                config.snapshot_dir.display()
            )
        })?
        .filter_map(Result::ok)
        .filter_map(|entry| entry.file_name().to_str().map(str::to_string))
        .filter(|name| name.ends_with(".json") && name.contains("-aggregate-"))
        .collect::<Vec<_>>();
    file_names.sort();

    let mut entries = Vec::new();
    let mut mismatched = 0;
    for file_name in file_names {
        let path = config.snapshot_dir.join(&file_name);
        let file = read_snapshot_file(&path)?;
        if file.run_kind != "aggregate-matrix" {
            continue;
        }
        let recorded = PinnedRevisions {
            ecma262: file.pinned_revisions.ecma262.clone(),
            test262: file.pinned_revisions.test262.clone(),
        };
        let status = if recorded == current {
            SnapshotPinStatus::Exact
        } else if test262_pins_equivalent(config, &recorded, &current) {
            SnapshotPinStatus::ContentEquivalent
        } else {
            SnapshotPinStatus::Mismatch
        };
        if status == SnapshotPinStatus::Mismatch {
            mismatched += 1;
        }
        entries.push(SnapshotPinReportEntry {
            provenance: file.provenance().clone(),
            file_name,
            execution_backend: file.execution_backend.clone(),
            manifest_hash: file.manifest_hash,
            matrix_strategy_version: file.matrix_strategy_version,
            recorded_ecma262: recorded.ecma262,
            recorded_test262: recorded.test262,
            status,
        });
    }
    Ok(SnapshotPinReport {
        current,
        entries,
        mismatched,
    })
}

fn load_failure_map(
    config: &SuiteConfig,
    verified: &VerifiedAggregateSummary,
    execution_backend: ExecutionBackend,
) -> Result<BTreeMap<TestExecutionId, FailureRecord>, String> {
    let nodes = load_or_build_run_matrix(config, execution_backend)?;
    let entries = verified
        .summary
        .entries
        .iter()
        .map(|entry| (entry.node_id.as_str(), entry))
        .collect::<BTreeMap<_, _>>();
    let mut map = BTreeMap::new();
    for node in &nodes {
        let Some(entry) = entries.get(node.node_id.as_str()).copied() else {
            continue;
        };
        let Some(snapshot) = load_completed_node_snapshot(
            config,
            &verified.resolved_snapshot_name,
            node,
            execution_backend,
            entry,
            &verified.compiler_identity,
        )?
        else {
            continue;
        };
        for failure in snapshot.failures {
            map.insert(failure.test_id.clone(), failure);
        }
    }
    Ok(map)
}

/// Locate the matrix node snapshot that an aggregate entry points at.
///
/// Aggregate snapshots record each completed node's manifest hash, which is
/// also embedded in the node snapshot's file name — that recorded hash is the
/// only honest join key, because node manifest hashes are derived from the
/// pin *string* and therefore changed with every legacy pin drift. The
/// located file must still prove itself: its own recorded pin must reproduce
/// the recorded manifest hash over the node's exact execution ids, and the pin
/// must verify as the current suite content.
fn locate_node_snapshot(
    config: &SuiteConfig,
    snapshot_name: &str,
    node: &RunMatrixNode,
    execution_backend: ExecutionBackend,
    entry: &TopLevelRunSummary,
    expected_compiler: &CompilerProvenance,
) -> Result<Option<(PathBuf, AdmittedSnapshot)>, String> {
    let expected_pinned = pinned_revisions(config);
    let node_snapshot_name = format!(
        "{}-{}",
        snapshot_name,
        sanitize_filter_for_snapshot(&node.node_id)
    );
    let path = config.snapshot_dir.join(format!(
        "{}-{}.json",
        node_snapshot_name, entry.manifest_hash
    ));
    if !path.exists() {
        return Ok(None);
    }
    let file = read_snapshot_file(&path)?;
    let recorded_pinned = PinnedRevisions {
        ecma262: file.pinned_revisions.ecma262.clone(),
        test262: file.pinned_revisions.test262.clone(),
    };
    let recomputed_hash = matrix_node_manifest_hash(&recorded_pinned, node);
    file.require_compiler(expected_compiler, &path)?;
    if recomputed_hash != file.manifest_hash {
        return Err(format!(
            "node snapshot integrity failure in {}: recorded pin does not reproduce manifest hash {} over the current case set for {} (recomputed {})",
            path.display(),
            file.manifest_hash,
            node.node_id,
            recomputed_hash
        ));
    }
    validate_resume_node_snapshot(
        config,
        &file,
        &path,
        node,
        entry.manifest_hash,
        execution_backend,
        &expected_pinned,
        expected_compiler,
    )
    .map_err(ResumeCheckpointLoadError::into_message)?;
    Ok(Some((path, file)))
}

fn load_completed_node_snapshot(
    config: &SuiteConfig,
    snapshot_name: &str,
    node: &RunMatrixNode,
    execution_backend: ExecutionBackend,
    entry: &TopLevelRunSummary,
    expected_compiler: &CompilerProvenance,
) -> Result<Option<ProgressSnapshot>, String> {
    let Some((path, file)) = locate_node_snapshot(
        config,
        snapshot_name,
        node,
        execution_backend,
        entry,
        expected_compiler,
    )?
    else {
        return Ok(None);
    };
    file.require_compiler(expected_compiler, &path)?;
    let snapshot = snapshot_from_file(file)
        .map_err(|err| format!("invalid snapshot data in {}: {err}", path.display()))?;
    validate_complete_node_contract(&snapshot, node, entry, &path)?;
    Ok(Some(snapshot))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BacklogOwnerRule {
    prefix: String,
    ownership: BacklogOwnership,
}

fn load_backlog_owner_rules(config: &SuiteConfig) -> Result<Vec<BacklogOwnerRule>, String> {
    let path = test262_root_from_config(config).join("backlog/ownership-map.tsv");
    let raw = fs::read_to_string(&path).unwrap_or_else(|_| DEFAULT_BACKLOG_OWNERSHIP.to_string());
    let mut rules = Vec::new();
    let mut prefixes = BTreeSet::new();
    for (index, line) in raw.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let parts = line.split('\t').collect::<Vec<_>>();
        if parts.len() != 3 {
            return Err(format!(
                "invalid backlog ownership map line {} in {}: expected prefix<TAB>task_id<TAB>debt_category",
                index + 1,
                path.display()
            ));
        }
        let prefix = parts[0].trim();
        let task_id = parts[1].trim();
        let debt_category = parts[2].trim();
        if prefix.is_empty() || task_id.is_empty() || debt_category.is_empty() {
            return Err(format!(
                "invalid backlog ownership map line {} in {}: fields must be non-empty",
                index + 1,
                path.display()
            ));
        }
        let owner = task_id.parse::<BacklogOwner>().map_err(|err| {
            format!(
                "invalid backlog ownership map line {} in {}: {err}",
                index + 1,
                path.display()
            )
        })?;
        let ownership = BacklogOwnership::parse(owner, debt_category).map_err(|err| {
            format!(
                "invalid backlog ownership map line {} in {}: {err}",
                index + 1,
                path.display()
            )
        })?;
        if !prefixes.insert(prefix.to_string()) {
            return Err(format!(
                "invalid backlog ownership map line {} in {}: duplicate prefix `{}`",
                index + 1,
                path.display(),
                prefix
            ));
        }
        rules.push(BacklogOwnerRule {
            prefix: prefix.to_string(),
            ownership,
        });
    }
    rules.sort_by(|left, right| right.prefix.len().cmp(&left.prefix.len()));
    Ok(rules)
}

const DEFAULT_BACKLOG_OWNERSHIP: &str = "language\tT07\tparser\nbuilt-ins\tT24\tsemantic\n";

fn classify_backlog_owner(
    failure: &FailureRecord,
    case: Option<&TestCase>,
    rules: &[BacklogOwnerRule],
) -> BacklogOwnership {
    if matches!(failure.kind, FailureKind::Parser | FailureKind::EarlyError) {
        return BacklogOwnership::assigned(ConformanceOwner::T07, BacklogDebtCategory::Parser);
    }
    if failure.kind == FailureKind::Lowering {
        return BacklogOwnership::assigned(ConformanceOwner::T04, BacklogDebtCategory::Semantic);
    }
    if failure.kind == FailureKind::HostHarness || failure.origin == FailureOrigin::LocalHarness {
        return BacklogOwnership::assigned(
            ConformanceOwner::T03,
            BacklogDebtCategory::Infrastructure,
        );
    }
    if case.is_some_and(|case| {
        case.features
            .iter()
            .any(|feature| feature == "eval" || feature == "dynamic-import")
    }) {
        return BacklogOwnership::assigned(
            ConformanceOwner::T13,
            BacklogDebtCategory::DynamicSource,
        );
    }
    for rule in rules {
        if failure.test_path == rule.prefix
            || failure.test_path.starts_with(&format!("{}/", rule.prefix))
        {
            return rule.ownership;
        }
    }
    BacklogOwnership::Unclassified
}

fn write_backlog_artifact(
    config: &SuiteConfig,
    artifact: &BacklogArtifact,
) -> Result<BacklogPaths, String> {
    if artifact.snapshot_version != SNAPSHOT_VERSION {
        return Err("backlog writes require the current compiler-bound snapshot schema".into());
    }
    artifact
        .compiler_identity
        .require_running("backlog writer")?;
    let backlog_dir = test262_root_from_config(config)
        .join("backlog")
        .join(&artifact.pinned_revisions.test262);
    fs::create_dir_all(&backlog_dir).map_err(|err| {
        format!(
            "failed to create backlog dir {}: {err}",
            backlog_dir.display()
        )
    })?;
    let json_path = backlog_dir.join(format!("{}.json", artifact.execution_backend.as_str()));
    let txt_path = backlog_dir.join(format!("{}.txt", artifact.execution_backend.as_str()));
    let json = serde_json::to_string_pretty(artifact)
        .map(|json| format!("{json}\n"))
        .map_err(|err| format!("failed to serialize backlog artifact: {err}"))?;
    fs::write(&json_path, json)
        .map_err(|err| format!("failed to write backlog {}: {err}", json_path.display()))?;
    fs::write(&txt_path, render_backlog_summary(artifact))
        .map_err(|err| format!("failed to write backlog {}: {err}", txt_path.display()))?;
    Ok(BacklogPaths {
        json_path,
        txt_path,
    })
}

fn render_backlog_summary(artifact: &BacklogArtifact) -> String {
    let mut out = String::new();
    writeln!(
        &mut out,
        "test262 backlog {} snapshot={}",
        artifact.execution_backend.as_str(),
        artifact.snapshot_name
    )
    .unwrap();
    writeln!(
        &mut out,
        "producer={} snapshot_version={}",
        artifact.producer.as_str(),
        artifact.snapshot_version
    )
    .unwrap();
    writeln!(
        &mut out,
        "compiler_identity={}",
        serde_json::to_string(&artifact.compiler_identity)
            .expect("checked compiler identity serializes")
    )
    .unwrap();
    writeln!(
        &mut out,
        "pinned: ecma262={} test262={}",
        artifact.pinned_revisions.ecma262, artifact.pinned_revisions.test262
    )
    .unwrap();
    writeln!(
        &mut out,
        "total={} passed={} failed={} records={}",
        artifact.total,
        artifact.passed,
        artifact.failed,
        artifact.records.len()
    )
    .unwrap();
    writeln!(&mut out, "by_task:").unwrap();
    for (task, count) in &artifact.summary_by_task {
        writeln!(&mut out, "  {task}: {count}").unwrap();
    }
    writeln!(&mut out, "by_feature:").unwrap();
    for (feature, count) in &artifact.summary_by_feature {
        writeln!(&mut out, "  {feature}: {count}").unwrap();
    }
    writeln!(&mut out, "top_failure_hashes:").unwrap();
    for (hash, count) in artifact.summary_by_failure_hash.iter().take(25) {
        writeln!(&mut out, "  {hash}: {count}").unwrap();
    }
    writeln!(&mut out, "slowest_subtrees:").unwrap();
    for entry in &artifact.slowest_subtrees {
        writeln!(&mut out, "  {}: {}ms", entry.subtree, entry.duration_ms).unwrap();
    }
    out
}

fn test262_root_from_config(config: &SuiteConfig) -> PathBuf {
    config
        .suite_root
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("test262"))
}

fn sorted_set_values(values: Option<&BTreeSet<String>>) -> Vec<String> {
    values
        .map(|values| values.iter().cloned().collect())
        .unwrap_or_default()
}

/// Normalize a failure detail for stable comparison and backlog output:
/// collapse whitespace, unify path separators, and scrub unstable data
/// (absolute filesystem paths, wall-clock timestamps, durations) that would
/// otherwise make identical failure modes hash differently across machines or
/// runs.
fn normalize_backlog_detail(detail: &str) -> String {
    // Heap handles belong in the same class as absolute paths and timestamps,
    // and for a stronger reason: they are unstable between two builds *on the
    // same machine*. This is not a token-level rule because the address arrives
    // embedded in `object(handle@5397552)`, which `normalize_detail_token` sees
    // as one opaque core.
    let detail = erase_volatile_handles(detail);
    detail
        .replace('\\', "/")
        .split_whitespace()
        .map(normalize_detail_token)
        .collect::<Vec<_>>()
        .join(" ")
}

fn normalize_detail_token(token: &str) -> String {
    const OPENERS: &[char] = &['(', '[', '{', '<', '"', '\''];
    const CLOSERS: &[char] = &[')', ']', '}', '>', '"', '\'', ',', ';', ':', '.'];
    let core_start = token
        .find(|c: char| !OPENERS.contains(&c))
        .unwrap_or(token.len());
    let (prefix, rest) = token.split_at(core_start);
    let core_end = rest
        .rfind(|c: char| !CLOSERS.contains(&c))
        .map(|index| index + rest[index..].chars().next().map_or(1, char::len_utf8))
        .unwrap_or(0);
    let (core, suffix) = rest.split_at(core_end);
    let replacement = if core.starts_with('/') {
        Some("<abs-path>")
    } else if is_timestamp_token(core) {
        Some("<timestamp>")
    } else if is_duration_token(core) {
        Some("<duration>")
    } else {
        None
    };
    match replacement {
        Some(replacement) => format!("{prefix}{replacement}{suffix}"),
        None => token.to_string(),
    }
}

/// Matches wall-clock timestamps of the shape `YYYY-MM-DD` optionally
/// followed by `T`/`t` and a time component (e.g. RFC 3339).
fn is_timestamp_token(token: &str) -> bool {
    let bytes = token.as_bytes();
    if bytes.len() < 10 {
        return false;
    }
    let date_ok = bytes[..4].iter().all(u8::is_ascii_digit)
        && bytes[4] == b'-'
        && bytes[5..7].iter().all(u8::is_ascii_digit)
        && bytes[7] == b'-'
        && bytes[8..10].iter().all(u8::is_ascii_digit);
    if !date_ok {
        return false;
    }
    match bytes.get(10) {
        None => true,
        Some(b'T') | Some(b't') => bytes[11..]
            .iter()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b':' | b'.' | b'+' | b'-' | b'Z')),
        Some(_) => false,
    }
}

/// Matches duration tokens like `123ms`, `4s`, or `1.5s`.
fn is_duration_token(token: &str) -> bool {
    let digits = token.strip_suffix("ms").or_else(|| token.strip_suffix('s'));
    let Some(digits) = digits else {
        return false;
    };
    !digits.is_empty()
        && digits.chars().filter(|c| *c == '.').count() <= 1
        && digits.chars().all(|c| c.is_ascii_digit() || c == '.')
}

fn outcome_rank(outcome: OutcomeKind) -> usize {
    match outcome {
        OutcomeKind::Crash => 0,
        OutcomeKind::Bug => 1,
        OutcomeKind::NotImplemented => 2,
        OutcomeKind::Success => 3,
    }
}

fn aggregate_summary_from_snapshot(snapshot: &ProgressSnapshot) -> AggregateRunSummary {
    let mut counts_per_origin = BTreeMap::new();
    for origin in FailureOrigin::ALL {
        counts_per_origin.insert(origin, 0);
    }
    for entry in &snapshot.aggregate_entries {
        for origin in FailureOrigin::ALL {
            *counts_per_origin.entry(origin).or_insert(0) +=
                entry.counts_per_origin.get(&origin).copied().unwrap_or(0);
        }
    }

    AggregateRunSummary {
        total: snapshot.total,
        passed: snapshot.passed,
        failed: snapshot.total.saturating_sub(snapshot.passed),
        counts_per_kind: snapshot.counts_per_kind.clone(),
        counts_per_outcome: snapshot.counts_per_outcome.clone(),
        counts_per_origin,
        entries: snapshot.aggregate_entries.clone(),
    }
}

fn baseline_report(summary: &RunSummary) -> BaselineReport {
    let mut subtree_by_kind: BTreeMap<FailureKind, BTreeMap<String, usize>> = BTreeMap::new();
    for failure in &summary.failures {
        let subtree = top_level_subtree(&failure.test_path);
        *subtree_by_kind
            .entry(failure.kind)
            .or_default()
            .entry(subtree)
            .or_insert(0) += 1;
    }

    let mut buckets = Vec::new();
    for kind in FailureKind::ALL {
        let total = summary.counts_per_kind.get(&kind).copied().unwrap_or(0);
        let mut top_subtrees = subtree_by_kind
            .remove(&kind)
            .unwrap_or_default()
            .into_iter()
            .collect::<Vec<_>>();
        top_subtrees.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
        top_subtrees.truncate(10);
        buckets.push(BaselineBucket {
            kind,
            total,
            top_subtrees,
        });
    }
    buckets.sort_by(|left, right| {
        right
            .total
            .cmp(&left.total)
            .then_with(|| left.kind.as_str().cmp(right.kind.as_str()))
    });

    BaselineReport {
        total: summary.total,
        passed: summary.passed,
        failed: summary.total.saturating_sub(summary.passed),
        buckets,
    }
}

fn aggregate_baseline_report(summary: &AggregateRunSummary) -> AggregateRunSummary {
    let mut grouped = BTreeMap::<String, TopLevelRunSummary>::new();
    for entry in &summary.entries {
        let aggregate = grouped.entry(entry.filter.clone()).or_insert_with(|| {
            let mut counts_per_kind = BTreeMap::new();
            for kind in FailureKind::ALL {
                counts_per_kind.insert(kind, 0);
            }
            let mut counts_per_origin = BTreeMap::new();
            for origin in FailureOrigin::ALL {
                counts_per_origin.insert(origin, 0);
            }
            TopLevelRunSummary {
                node_id: entry.filter.clone(),
                node_kind: MatrixNodeKind::FilterLeaf,
                filter: entry.filter.clone(),
                matrix_path: entry.matrix_path.clone(),
                total: 0,
                passed: 0,
                failed: 0,
                counts_per_kind,
                counts_per_outcome: empty_outcome_counts(),
                counts_per_origin,
                manifest_hash: entry.manifest_hash,
            }
        });
        aggregate.total += entry.total;
        aggregate.passed += entry.passed;
        aggregate.failed += entry.failed;
        for kind in FailureKind::ALL {
            *aggregate.counts_per_kind.entry(kind).or_insert(0) +=
                entry.counts_per_kind.get(&kind).copied().unwrap_or(0);
        }
        for outcome in OutcomeKind::ALL {
            *aggregate.counts_per_outcome.entry(outcome).or_insert(0) +=
                entry.counts_per_outcome.get(&outcome).copied().unwrap_or(0);
        }
        for origin in FailureOrigin::ALL {
            *aggregate.counts_per_origin.entry(origin).or_insert(0) +=
                entry.counts_per_origin.get(&origin).copied().unwrap_or(0);
        }
    }

    let mut entries = grouped.into_values().collect::<Vec<_>>();
    entries.sort_by(|left, right| left.filter.cmp(&right.filter));

    AggregateRunSummary {
        total: summary.total,
        passed: summary.passed,
        failed: summary.failed,
        counts_per_kind: summary.counts_per_kind.clone(),
        counts_per_outcome: summary.counts_per_outcome.clone(),
        counts_per_origin: summary.counts_per_origin.clone(),
        entries,
    }
}

fn top_level_subtree(test_path: &str) -> String {
    let mut parts = test_path.split('/');
    match (parts.next(), parts.next()) {
        (Some(first), Some(second)) => format!("{first}/{second}"),
        (Some(first), None) => first.to_string(),
        _ => "unknown".to_string(),
    }
}

fn shard_cases(
    cases: &[TestCase],
    shard_index: usize,
    shard_count: usize,
) -> Result<Vec<TestCase>, String> {
    if shard_count == 0 {
        return Err("shard count must be at least 1".to_string());
    }
    if shard_index >= shard_count {
        return Err(format!(
            "shard index {} out of range for shard count {}",
            shard_index, shard_count
        ));
    }

    Ok(cases
        .iter()
        .enumerate()
        .filter(|(index, _)| index % shard_count == shard_index)
        .map(|(_, case)| case.clone())
        .collect())
}

fn sorted_directory_entries(dir: &Path, owner: &str) -> Result<Vec<fs::DirEntry>, String> {
    let mut entries = fs::read_dir(dir)
        .map_err(|err| format!("failed to read {owner} dir {}: {err}", dir.display()))?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|err| format!("failed to iterate {owner} dir {}: {err}", dir.display()))?;
    entries.sort_by_key(|entry| entry.path());
    Ok(entries)
}

fn scan_tests(
    dir: &Path,
    test_root: &Path,
    filter: Option<&str>,
    boundary_filter: bool,
    cases: &mut Vec<TestCase>,
) -> Result<(), String> {
    let entries = sorted_directory_entries(dir, "test")?;

    for entry in entries {
        let path = entry.path();
        if entry
            .file_type()
            .map_err(|err| format!("failed to read file type {}: {err}", path.display()))?
            .is_dir()
        {
            if let Some(filter) = filter {
                let relative_dir = path
                    .strip_prefix(test_root)
                    .map_err(|err| {
                        format!("failed to make relative test dir {}: {err}", path.display())
                    })?
                    .to_string_lossy()
                    .replace('\\', "/");
                let matches = if boundary_filter {
                    filter_matches_directory(relative_dir.as_str(), filter)
                } else {
                    let subtree_prefix = format!("{relative_dir}/");
                    filter.starts_with(&subtree_prefix) || subtree_prefix.starts_with(filter)
                };
                if !matches {
                    continue;
                }
            }
            scan_tests(&path, test_root, filter, boundary_filter, cases)?;
            continue;
        }

        if path.extension().and_then(|value| value.to_str()) != Some("js") {
            continue;
        }

        let rel = path
            .strip_prefix(test_root)
            .map_err(|err| {
                format!(
                    "failed to make relative test path {}: {err}",
                    path.display()
                )
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if rel.contains("_FIXTURE") {
            continue;
        }
        if let Some(filter) = filter {
            let matches = if boundary_filter {
                filter_matches_path(rel.as_str(), filter)
            } else {
                rel.starts_with(filter)
            };
            if !matches {
                continue;
            }
        }

        let original_source = fs::read_to_string(&path)
            .map_err(|err| format!("failed to read test {}: {err}", path.display()))?;
        cases.extend(parse_test_executions(rel, path, original_source)?);
    }

    Ok(())
}

fn filter_matches_path(path: &str, filter: &str) -> bool {
    filter.is_empty() || path == filter || path.starts_with(&format!("{filter}/"))
}

fn filter_matches_directory(relative_dir: &str, filter: &str) -> bool {
    filter.is_empty()
        || relative_dir == filter
        || relative_dir.starts_with(&format!("{filter}/"))
        || filter.starts_with(&format!("{relative_dir}/"))
}

fn parse_test_executions(
    path: String,
    source_path: PathBuf,
    original_source: String,
) -> Result<Vec<TestCase>, String> {
    let frontmatter::Metadata {
        flags,
        features,
        includes,
        negative,
    } = frontmatter::parse(&original_source, &path)?;
    let negative = negative.map(Arc::new);
    let plan = TestExecutionPlan::from_flags(&path, &flags)?;
    let original_source: Arc<str> = original_source.into();

    Ok(plan
        .modes()
        .map(|execution_mode| TestCase {
            execution_id: TestExecutionId::new(path.clone(), execution_mode),
            source_path: source_path.clone(),
            original_source: Arc::clone(&original_source),
            flags: flags.clone(),
            features: features.clone(),
            includes: includes.clone(),
            negative: negative.clone(),
        })
        .collect())
}

/// Test helper for source-shape tests that need one representative execution.
/// Product discovery always uses `parse_test_executions` and keeps every mode.
#[cfg(test)]
fn parse_test_case(path: String, source_path: PathBuf, original_source: String) -> TestCase {
    parse_test_executions(path, source_path, original_source)
        .expect("test fixture flags should form a valid execution plan")
        .into_iter()
        .next()
        .expect("every valid Test262 execution plan is non-empty")
}

fn scan_harness_files(
    root: &Path,
    dir: &Path,
    files: &mut Vec<(String, PathBuf)>,
) -> Result<(), String> {
    let entries = sorted_directory_entries(dir, "harness")?;

    for entry in entries {
        let path = entry.path();
        let file_type = entry
            .file_type()
            .map_err(|err| format!("failed to read file type {}: {err}", path.display()))?;
        if file_type.is_dir() {
            scan_harness_files(root, &path, files)?;
            continue;
        }
        if file_type.is_file() && path.extension().and_then(|value| value.to_str()) == Some("js") {
            let name = path
                .strip_prefix(root)
                .map_err(|err| {
                    format!(
                        "failed to make relative harness path {}: {err}",
                        path.display()
                    )
                })?
                .to_string_lossy()
                .replace('\\', "/");
            files.push((name, path));
        }
    }

    Ok(())
}

fn git_capture(dir: &Path, args: &[&str]) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(dir)
        .args(args)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SuiteGitContext {
    toplevel: PathBuf,
    /// Path of the suite root relative to `toplevel`, without a trailing
    /// slash. Empty when the suite root is itself the repository toplevel.
    prefix: String,
}

fn suite_git_context(suite_root: &Path) -> Option<SuiteGitContext> {
    let canonical = suite_root.canonicalize().ok()?;
    let toplevel = git_capture(&canonical, &["rev-parse", "--show-toplevel"])?;
    let prefix = git_capture(&canonical, &["rev-parse", "--show-prefix"])?;
    Some(SuiteGitContext {
        toplevel: PathBuf::from(toplevel),
        prefix: prefix.trim_end_matches('/').to_string(),
    })
}

/// Content identity of the vendored Test262 suite.
///
/// Historically this was `git -C <suite_root> rev-parse HEAD`, which is only
/// honest when the suite root is its own git checkout. The vendored suite in
/// this repository is plain committed files, so git resolved the *enclosing*
/// repository HEAD instead: every unrelated Scriptw commit changed the
/// recorded "test262 pin" even though the suite content was untouched, which
/// is how the published snapshots ended up with mutually inconsistent pins.
///
/// The honest pin for a vendored suite is the git tree object id of the suite
/// directory: it identifies the exact file contents and stays stable until
/// the suite is actually re-vendored. Legacy pins that recorded an enclosing
/// repository commit are accepted only after `test262_pins_equivalent`
/// verifies (via the git object store) that the vendored suite tree at that
/// commit is byte-identical to the current one.
fn suite_test262_pin(config: &SuiteConfig) -> String {
    type CacheKey = (PathBuf, PathBuf, Option<PathBuf>);
    static CACHE: OnceLock<Mutex<BTreeMap<CacheKey, String>>> = OnceLock::new();
    let suite_root = &config.suite_root;
    // Public configuration fields may have changed since worker admission.
    // An invalid role never suppresses bytes or reuses an earlier cache hit.
    let output = match suite_identity::owned_output_root(config) {
        Ok(output) => output,
        Err(_) => return compute_suite_test262_pin(suite_root),
    };
    let key = suite_root.canonicalize().ok().and_then(|root| {
        let harness = match &config.local_harness {
            LocalHarnessSource::File(path) => Some(suite_identity::normalize(path).ok()?),
            _ => None,
        };
        Some((root, output.clone(), harness))
    });
    if let Some(key) = &key {
        if let Some(hit) = CACHE
            .get_or_init(Mutex::default)
            .lock()
            .expect("suite pin cache lock should not be poisoned")
            .get(key)
        {
            return hit.clone();
        }
    }
    let pin = suite_identity::compute_pin(suite_root, &output);
    if let Some(key) = key {
        CACHE
            .get_or_init(Mutex::default)
            .lock()
            .expect("suite pin cache lock should not be poisoned")
            .insert(key, pin.clone());
    }
    pin
}

fn compute_suite_test262_pin(suite_root: &Path) -> String {
    let Some(context) = suite_git_context(suite_root) else {
        return "missing-vendored-suite".to_string();
    };
    if context.prefix.is_empty() {
        // The suite root is its own repository checkout; HEAD is the honest
        // upstream pin.
        return git_capture(&context.toplevel, &["rev-parse", "HEAD"])
            .unwrap_or_else(|| "missing-vendored-suite".to_string());
    }
    let tree = git_capture(
        &context.toplevel,
        &["rev-parse", "--verify", &format!("HEAD:{}", context.prefix)],
    );
    let dirty = git_capture(
        &context.toplevel,
        &["status", "--porcelain", "--", &context.prefix],
    )
    .map(|status| !status.is_empty());
    match (tree, dirty) {
        (Some(tree), Some(false)) => tree,
        // Uncommitted/untracked vendored content: derive the pin from the
        // actual bytes on disk so it can never silently collide with a clean
        // committed pin. Such pins are process-local working states, never
        // publishable identities.
        _ => format!("worktree-{:016x}", hash_directory_content(suite_root)),
    }
}

fn hash_directory_content(root: &Path) -> u64 {
    hash_directory_content_excluding(root, None)
}

fn hash_directory_content_excluding(root: &Path, output: Option<&Path>) -> u64 {
    let mut relative_paths = Vec::new();
    collect_relative_files(root, root, &mut relative_paths, output);
    relative_paths.sort();
    let mut hasher = DefaultHasher::new();
    for relative in &relative_paths {
        relative.hash(&mut hasher);
        fs::read(root.join(relative))
            .unwrap_or_default()
            .hash(&mut hasher);
    }
    hasher.finish()
}

fn collect_relative_files(root: &Path, dir: &Path, out: &mut Vec<String>, output: Option<&Path>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.filter_map(Result::ok) {
        let path = entry.path();
        if output.is_some_and(|output| path.canonicalize().is_ok_and(|path| path == output)) {
            continue;
        }
        if path.is_dir() {
            collect_relative_files(root, &path, out, output);
        } else if let Ok(relative) = path.strip_prefix(root) {
            out.push(relative.to_string_lossy().replace('\\', "/"));
        }
    }
}

fn is_full_hex_oid(value: &str) -> bool {
    value.len() == 40 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

/// Resolve a recorded test262 pin to the git tree object id of the suite
/// content it described, when that is verifiable from the local object store.
fn resolve_pin_to_suite_tree(context: &SuiteGitContext, pin: &str) -> Option<String> {
    if !is_full_hex_oid(pin) {
        return None;
    }
    let object_type = git_capture(&context.toplevel, &["cat-file", "-t", pin])?;
    match object_type.as_str() {
        "tree" => Some(pin.to_string()),
        "commit" => {
            let spec = if context.prefix.is_empty() {
                format!("{pin}^{{tree}}")
            } else {
                format!("{pin}:{}", context.prefix)
            };
            git_capture(&context.toplevel, &["rev-parse", "--verify", &spec])
        }
        _ => None,
    }
}

/// Verified pin equivalence: two pins are equivalent only when they are equal
/// strings, or when both can be resolved through the local git object store
/// to the same suite content tree. Legacy snapshots recorded the enclosing
/// repository HEAD commit as the "test262 pin"; those verify against the
/// current content pin exactly when the vendored suite tree at that commit is
/// identical to the current tree. Nothing is ever assumed: unresolvable pins
/// are a mismatch.
fn test262_pins_equivalent(
    config: &SuiteConfig,
    recorded: &PinnedRevisions,
    expected: &PinnedRevisions,
) -> bool {
    if recorded.ecma262 != expected.ecma262 {
        return false;
    }
    if recorded.test262 == expected.test262 {
        return true;
    }
    static CACHE: OnceLock<Mutex<BTreeMap<(PathBuf, String, String), bool>>> = OnceLock::new();
    let cache_key = config
        .suite_root
        .canonicalize()
        .ok()
        .map(|root| (root, recorded.test262.clone(), expected.test262.clone()));
    if let Some(cache_key) = &cache_key {
        if let Some(hit) = CACHE
            .get_or_init(Mutex::default)
            .lock()
            .expect("pin equivalence cache lock should not be poisoned")
            .get(cache_key)
        {
            return *hit;
        }
    }
    let equivalent = suite_git_context(&config.suite_root).is_some_and(|context| {
        match (
            resolve_pin_to_suite_tree(&context, &recorded.test262),
            resolve_pin_to_suite_tree(&context, &expected.test262),
        ) {
            (Some(recorded_tree), Some(expected_tree)) => recorded_tree == expected_tree,
            _ => false,
        }
    });
    if let Some(cache_key) = cache_key {
        CACHE
            .get_or_init(Mutex::default)
            .lock()
            .expect("pin equivalence cache lock should not be poisoned")
            .insert(cache_key, equivalent);
    }
    equivalent
}

fn hash_manifest(
    pinned_revisions: &PinnedRevisions,
    cases: &[TestCase],
    filter: Option<&str>,
) -> u64 {
    hash_manifest_execution_ids(
        pinned_revisions,
        &cases
            .iter()
            .map(|case| case.execution_id.clone())
            .collect::<Vec<_>>(),
        filter,
    )
}

fn hash_manifest_execution_ids(
    pinned_revisions: &PinnedRevisions,
    case_ids: &[TestExecutionId],
    filter: Option<&str>,
) -> u64 {
    let mut hasher = DefaultHasher::new();
    pinned_revisions.ecma262.hash(&mut hasher);
    pinned_revisions.test262.hash(&mut hasher);
    filter.hash(&mut hasher);
    for case_id in case_ids {
        case_id.hash(&mut hasher);
    }
    hasher.finish()
}

/// The one identity function for a matrix leaf's persisted snapshot.
///
/// A chunk leaf shares its discovery filter with every sibling chunk, so the
/// filter is not a node identity. Keeping the node id here prevents writers,
/// resumable readers, and backlog readers from silently deriving different
/// hashes for the same chunk.
fn matrix_node_manifest_hash(pinned_revisions: &PinnedRevisions, node: &RunMatrixNode) -> u64 {
    hash_manifest_execution_ids(
        pinned_revisions,
        &node.case_ids,
        Some(node.node_id.as_str()),
    )
}

/// The identity of a failure detail: the detail text with every value that is
/// an artefact of *this build* erased, and nothing else changed.
///
/// This type exists because `detail_hash` is supposed to name a *defect*, and a
/// failure family is the unit a fix lane owns. A hash that carries a nonce does
/// not name anything: it mints one singleton group per case, so a list of
/// failure families reads as a list of cases and every triage pass re-derives
/// the same shared cause by hand.
///
/// The nonce is the heap handle. The Wasm-AOT engine renders a thrown heap
/// object as `handle@<raw linear-memory address>`, and that address is:
///
/// - **not stable across builds** — batch 3 measured every `Temporal.
///   ZonedDateTime` handle in a fixed set of cases shifting by exactly `+136`
///   bytes between two builds of the same source, from a bootstrap layout
///   change alone; and
/// - **not resolvable to anything** — no handle-to-allocation-site mapping
///   exists anywhere in this tree, and none of the `SCRIPTW_*` knobs
///   (`WASM_DUMP`, `WASM_TRACE`, `WASM_TRACE_DUMP`, `LOWER_TRACE`,
///   `EMIT_SIZE_REPORT[_PATH]`) touch the heap.
///
/// Measured basis: ~2,488 Wasm-AOT cases carry
/// `uncaught throw: <Name>: wasm-aot completion: <kind>(handle@N)` across
/// ~1,743 distinct addresses.
///
/// The raw detail is **not** modified for display — see
/// `FailureDetailGroup::detail`, which keeps a representative case's verbatim
/// text. The address is deleted from the identity, never from the report.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct FailureDetailIdentity(String);

impl FailureDetailIdentity {
    /// The only constructor. Taking one is the whole point: a caller cannot
    /// hash a raw detail by accident, because the hashing entry point below
    /// builds this first.
    fn of(detail: &str) -> Self {
        Self(erase_volatile_handles(detail))
    }

    fn into_string(self) -> String {
        self.0
    }
}

/// Renderings whose numeric tail is a raw address, produced by
/// `render_wasmtime_completion` in `scriptw-engine`.
///
/// Closed list, and deliberately spelled with the `@` so it cannot match a
/// spec message that happens to contain the word "handle".
const VOLATILE_ADDRESS_PREFIXES: &[&str] = &["handle@", "symbol@"];

/// What replaces the digits. Kept in the string rather than dropped so a reader
/// of a normalized detail can see that an address *was* there.
const VOLATILE_ADDRESS_PLACEHOLDER: &str = "<addr>";

fn erase_volatile_handles(detail: &str) -> String {
    let mut out = String::with_capacity(detail.len());
    let mut rest = detail;
    'scan: while !rest.is_empty() {
        for &prefix in VOLATILE_ADDRESS_PREFIXES {
            let Some(after) = rest.strip_prefix(prefix) else {
                continue;
            };
            let tail = after.trim_start_matches(|character: char| character.is_ascii_digit());
            let digits = after.len() - tail.len();
            if digits == 0 {
                continue;
            }
            out.push_str(prefix);
            out.push_str(VOLATILE_ADDRESS_PLACEHOLDER);
            rest = &after[digits..];
            continue 'scan;
        }
        let character = rest
            .chars()
            .next()
            .expect("loop guard proved the remainder is non-empty");
        out.push(character);
        rest = &rest[character.len_utf8()..];
    }
    out
}

/// Hash a failure detail *by identity*, so two cases that fail the same way
/// land in the same group whatever addresses their handles happened to get.
fn hash_detail(detail: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    let identity = FailureDetailIdentity::of(detail);
    identity.into_string().hash(&mut hasher);
    hasher.finish()
}

/// Hash a case path. Separate from `hash_detail` on purpose: this one feeds
/// child-snapshot *file names*, it is not a defect identity, and normalizing it
/// would be meaningless. Keeping the two apart is what stops a later change to
/// detail normalization from quietly renaming every child snapshot.
fn hash_case_path(case_path: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    case_path.hash(&mut hasher);
    hasher.finish()
}

fn json_escape(input: &str) -> String {
    input
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
}

/// The process-level meaning of one completed conformance selection.
///
/// A zero-case selection is evidence of nothing, so it is distinct from a
/// pass. Both terminal verdicts carry a non-zero denominator, and a failed
/// verdict carries a non-zero failure count. Callers obtain this domain only
/// after the summary's total, pass count and failure records reconcile.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConformanceRunVerdict {
    NoEvidence,
    Passed {
        total: NonZeroUsize,
    },
    Failed {
        total: NonZeroUsize,
        failed: NonZeroUsize,
    },
}

impl ConformanceRunVerdict {
    fn from_counts(
        context: &str,
        total: usize,
        passed: usize,
        failure_records: usize,
    ) -> Result<Self, String> {
        let failed = total.checked_sub(passed).ok_or_else(|| {
            format!("{context} integrity failure: passed count {passed} exceeds total {total}")
        })?;
        if failed != failure_records {
            return Err(format!(
                "{context} integrity failure: total {total} minus passed {passed} is {failed}, but {failure_records} failure records exist"
            ));
        }

        match (NonZeroUsize::new(total), NonZeroUsize::new(failed)) {
            (None, None) => Ok(Self::NoEvidence),
            (Some(total), None) => Ok(Self::Passed { total }),
            (Some(total), Some(failed)) => Ok(Self::Failed { total, failed }),
            (None, Some(_)) => unreachable!(
                "a non-zero failure count cannot remain after reconciling a zero total"
            ),
        }
    }
}

impl ShardSummary {
    pub fn one_based_shard_index(&self) -> Result<NonZeroUsize, String> {
        self.shard_index
            .checked_add(1)
            .and_then(NonZeroUsize::new)
            .ok_or_else(|| {
                format!(
                    "test262 shard summary integrity failure: zero-based shard index {} cannot be represented as one-based",
                    self.shard_index
                )
            })
    }

    pub fn verdict(&self) -> Result<ConformanceRunVerdict, String> {
        let shard_number = self.one_based_shard_index()?;
        ConformanceRunVerdict::from_counts(
            &format!(
                "test262 shard {}/{} summary",
                shard_number, self.shard_count
            ),
            self.total,
            self.passed,
            self.failures.len(),
        )
    }
}

impl RunSummary {
    pub fn verdict(&self) -> Result<ConformanceRunVerdict, String> {
        ConformanceRunVerdict::from_counts(
            "test262 run summary",
            self.total,
            self.passed,
            self.failures.len(),
        )
    }
}

