    #[test]
    fn wasm_aot_host_and_named_harness_assets_have_exact_separate_ownership() {
        let section = |name: &str| {
            WASM_AOT_HARNESS
                .split("///")
                .skip(1)
                .find_map(|contents| {
                    let mut lines = contents.lines();
                    (lines.next()?.trim() == name)
                        .then(|| format!("{}\n", lines.collect::<Vec<_>>().join("\n")))
                })
                .unwrap_or_else(|| panic!("missing {name} in Wasm-AOT harness"))
        };
        let sta = section("sta.js");
        let sta_preamble = section("sta-preamble.js");

        assert_eq!(WASM_AOT_HOST_PRELUDE.len(), 2_219);
        assert_eq!(fnv1a(WASM_AOT_HOST_PRELUDE), 0x58ca_c928_d580_3302);
        assert_eq!(sta, sta_preamble);
        assert_eq!(sta.len(), 793);
        assert_eq!(fnv1a(&sta), 0xd1de_6d61_b24b_c195);
        assert!(!WASM_AOT_HOST_PRELUDE.contains("///"));
        assert!(!WASM_AOT_HARNESS.contains("var $262 ="));
        assert!(!WASM_AOT_HARNESS.contains("__scriptwAgentStart"));
        CompleteWasmAotHostPrelude::load_embedded()
            .expect("the exact embedded host should load as one complete capability");
    }

