    #[test]
    fn wasm_aot_host_tracker_preserves_sync_completion_and_async_failures() {
        let preludes = async_done_preludes();
        for source in [
            "Promise.any([]);",
            "var source = Promise.resolve(); source.constructor = null; if (Promise.resolve(source) === source) throw 'identity';",
            "Promise.reject({toString() { throw 'diagnostic conversion'; }}); Promise.reject('second');",
        ] {
            let mut case = synthetic_case("harness/wasm-promise-host-completion.js");
            case.original_source = Arc::from(source);
            let result = run_one_case(&case, &preludes, 30_000, ExecutionBackend::WasmAot);
            assert!(
                matches!(result.status, TestStatus::Passed),
                "{source}: {:?}",
                result.status
            );
        }
        for (source, passing, detail) in [
            (
                "Promise.reject('ignored'); Promise.resolve().then(() => $DONE());",
                true,
                "",
            ),
            (
                "Promise.resolve().then(() => $DONE('rejection marker'));",
                false,
                "rejection marker",
            ),
            (
                "Promise.resolve().then(() => { throw 'before done'; });",
                false,
                "was not called",
            ),
            (
                "Promise.resolve().then(() => { $DONE(); $DONE(); });",
                false,
                "called multiple times",
            ),
            (
                "$DONE(); Promise.resolve().then(() => $DONE('late error'));",
                false,
                "called multiple times",
            ),
        ] {
            let mut case = synthetic_case("harness/wasm-promise-async-completion.js");
            case.flags.insert("async".into());
            case.original_source = Arc::from(source);
            let result = run_one_case(&case, &preludes, 30_000, ExecutionBackend::WasmAot);
            match result.status {
                TestStatus::Passed => assert!(passing, "{source} must fail"),
                TestStatus::Failed(failure) => {
                    assert!(!passing, "{source}: {failure:?}");
                    assert!(failure.detail.contains(detail), "{source}: {failure:?}");
                }
            }
        }
    }

    #[test]
    fn wasm_aot_enforces_async_done_output_after_jobs_drain() {
        let preludes = async_done_preludes();

        let mut passing = synthetic_case("harness/wasm-async-done-pass.js");
        passing.flags.insert("async".to_string());
        passing.original_source = Arc::from("$DONE();".to_string());
        let result = run_one_case(&passing, &preludes, 30_000, ExecutionBackend::WasmAot);
        assert!(
            matches!(result.status, TestStatus::Passed),
            "one async completion should pass, got {:?}",
            result.status
        );

        let mut rejected = synthetic_case("harness/wasm-async-done-reject.js");
        rejected.flags.insert("async".to_string());
        rejected.original_source = Arc::from("$DONE('boom');".to_string());
        let result = run_one_case(&rejected, &preludes, 30_000, ExecutionBackend::WasmAot);
        let TestStatus::Failed(failure) = result.status else {
            panic!("async failure output should fail");
        };
        assert_eq!(failure.kind, FailureKind::Runtime);
        assert!(failure.detail.contains("Test262:AsyncTestFailure"));

        let mut missing = synthetic_case("harness/wasm-async-done-missing.js");
        missing.flags.insert("async".to_string());
        let result = run_one_case(&missing, &preludes, 30_000, ExecutionBackend::WasmAot);
        let TestStatus::Failed(failure) = result.status else {
            panic!("missing async completion should fail");
        };
        assert_eq!(failure.kind, FailureKind::HostHarness);
        assert!(failure.detail.contains("was not called"));
        assert!(failure.detail.contains("job queue drained"));

        let mut repeated = synthetic_case("harness/wasm-async-done-repeated.js");
        repeated.flags.insert("async".to_string());
        repeated.original_source = Arc::from(
            r#"
print('Test262:AsyncTestComplete');
print('Test262:AsyncTestComplete');
"#
            .to_string(),
        );
        let result = run_one_case(&repeated, &preludes, 30_000, ExecutionBackend::WasmAot);
        let TestStatus::Failed(failure) = result.status else {
            panic!("repeated async completion should fail");
        };
        assert_eq!(failure.kind, FailureKind::HostHarness);
        assert!(failure.detail.contains("exactly once"));
        assert!(failure.detail.contains("observed 2"));
    }

    #[test]
    fn wasm_aot_retains_async_done_failures_alongside_execution_failures() {
        let preludes = async_done_preludes();
        for (path, source, negative_error, outcome, execution_detail, timeout_ms) in [
            (
                "harness/wasm-async-done-runtime-capability.js",
                "var realm = new ShadowRealm(); \
                 var hook = new Proxy(function() {}, {}); hook(); \
                 realm.evaluate('1/*' + Math.random() + '*/');",
                None,
                OutcomeKind::Bug,
                Some("unsupported dynamic-source operation `ShadowRealm.evaluate`"),
                60_000,
            ),
            (
                "harness/wasm-async-done-runtime-available.js",
                "var holder = { invoke: eval }; \
                 var hook = new Proxy(function() {}, {}); hook(); \
                 holder.invoke('1/*' + Math.random() + '*/');",
                None,
                OutcomeKind::Bug,
                None,
                60_000,
            ),
            (
                "harness/wasm-async-done-runtime-negative.js",
                "throw new TypeError('execution marker');",
                Some("TypeError"),
                OutcomeKind::Bug,
                Some("execution marker"),
                60_000,
            ),
            (
                "harness/wasm-async-done-runtime-timeout.js",
                "while (true) {}",
                None,
                OutcomeKind::Crash,
                Some("timeout exceeded"),
                1_000,
            ),
        ] {
            let mut case = synthetic_case(path);
            case.flags.insert("async".to_string());
            case.original_source = Arc::from(format!(
                "$DONE('ICU runtime TypeError done marker'); {source}"
            ));
            case.negative = negative_error.map(|error_type| {
                Arc::new(NegativeExpectation {
                    phase: NegativePhase::Runtime,
                    error_type: error_type.to_string(),
                })
            });
            let result = run_one_case(&case, &preludes, timeout_ms, ExecutionBackend::WasmAot);
            let TestStatus::Failed(failure) = result.status else {
                panic!("{path} must retain its async failure");
            };
            assert_eq!(failure.kind, FailureKind::Runtime, "{path}: {failure:?}");
            assert_eq!(failure.outcome, outcome, "{path}: {failure:?}");
            assert_eq!(
                failure.origin,
                FailureOrigin::Unknown,
                "{path}: {failure:?}"
            );
            for expected in ["Test262:AsyncTestFailure:", "done marker"] {
                assert!(failure.detail.contains(expected), "{path}: {failure:?}");
            }
            if let Some(execution_detail) = execution_detail {
                assert!(
                    failure.detail.contains(execution_detail),
                    "{path}: {failure:?}"
                );
            } else {
                // Successful execution must retain just the actual $DONE
                // failure, without inventing an obsolete eval capability error.
                assert_eq!(
                    failure.detail,
                    "[origin:unknown] Test262:AsyncTestFailure:Test262Error: ICU runtime TypeError done marker",
                    "{path}"
                );
            }
        }
    }

