    #[test]
    fn materialize_wasm_aot_same_value_only_uses_full_assert_prelude() {
        let mut store = PreludeStore::default();
        store.insert(
            "assert.js".to_string(),
            "function __scriptwAssertToString(value) { return String(value); }\nassert.sameValue = function() {};\nassert.notSameValue = function() { throw 'full assert'; };\nassert.compareArray = function() { throw 'full compare'; };\n".to_string(),
            PreludeOrigin::LocalMerged,
        );
        let mut case = synthetic_case("built-ins/Array/prototype/map/same-value-only.js");
        case.original_source =
            Arc::from("var value = true;\nassert.sameValue(value, true, 'value');\n".to_string());

        let materialized = materialize_test(&case, &store).expect("materialization should work");
        assert!(script_fixture_ledger(&case, &materialized).contains("__scriptwAssertToString"));
        assert!(script_fixture_ledger(&case, &materialized).contains("assert.sameValue"));
        assert!(script_fixture_ledger(&case, &materialized).contains("full assert"));
        assert!(script_fixture_ledger(&case, &materialized).contains("assert.notSameValue"));
        assert!(materialized.source.contains("assert.sameValue(value, true"));
    }

