    #[test]
    fn iterator_for_each_cases_preserve_pinned_sources_and_exact_preludes() {
        const NO_INCLUDES: &[&str] = &[];
        const COMPARE_ARRAY: &[&str] = &["compareArray.js"];

        let repo_root = repo_root();
        let test_root = repo_root.join("test262/vendor/test262/test");
        let local_store = real_wasm_aot_preludes();
        let vendored_store = real_wasm_aot_host_only_preludes();
        let local_assert = local_store
            .get("assert.js")
            .expect("LocalMerged assertion prelude should exist");
        let local_sta = local_store
            .get("sta.js")
            .expect("LocalMerged sta prelude should exist");
        let local_compare_array = local_store
            .get("compareArray.js")
            .expect("local profile should expose compareArray.js");
        let vendored_assert = vendored_store
            .get("assert.js")
            .expect("vendored assertion prelude should exist");
        let vendored_sta = vendored_store
            .get("sta.js")
            .expect("vendored sta prelude should exist");
        let vendored_compare_array = vendored_store
            .get("compareArray.js")
            .expect("vendored compareArray.js should exist");
        let active_host = validated_wasm_aot_host().render(WasmAotRealmActivation::Active);

        assert_eq!(local_assert.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_sta.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_compare_array.origin, PreludeOrigin::VendoredHarness);
        for prelude in [vendored_assert, vendored_sta, vendored_compare_array] {
            assert_eq!(prelude.origin, PreludeOrigin::VendoredHarness);
            let source = fs::read_to_string(
                repo_root
                    .join("test262/vendor/test262/harness")
                    .join(&prelude.name),
            )
            .unwrap_or_else(|error| panic!("vendored {} should read: {error}", prelude.name));
            assert_eq!(prelude.contents, format!("{source}\n"), "{}", prelude.name);
        }

        for (path, expected_includes, requires_active_host) in [
            (
                "built-ins/Iterator/prototype/forEach/iterator-already-exhausted.js",
                NO_INCLUDES,
                false,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/error-from-correct-realm.js",
                NO_INCLUDES,
                true,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/check-fn-after-getting-iterator.js",
                COMPARE_ARRAY,
                false,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/proxy.js",
                NO_INCLUDES,
                false,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/fn-throws-close-iterator.js",
                NO_INCLUDES,
                false,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/next-throws-iterator-not-closed.js",
                NO_INCLUDES,
                false,
            ),
            (
                "staging/sm/Iterator/prototype/forEach/value-throws-iterator-not-closed.js",
                NO_INCLUDES,
                false,
            ),
        ] {
            let source_path = test_root.join(path);
            let original_source = fs::read_to_string(&source_path)
                .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
            let cases =
                parse_test_executions(path.to_string(), source_path, original_source.clone())
                    .unwrap_or_else(|error| {
                        panic!("pinned {path} executions should parse: {error}")
                    });

            assert_eq!(
                cases
                    .iter()
                    .map(TestCase::execution_mode)
                    .collect::<Vec<_>>(),
                vec![
                    TestExecutionMode::SloppyScript,
                    TestExecutionMode::StrictScript,
                ],
                "{path}"
            );

            for case in cases {
                let strict_prefix = match case.execution_mode() {
                    TestExecutionMode::SloppyScript => "",
                    TestExecutionMode::StrictScript => "\"use strict\";\n",
                    execution_mode => {
                        panic!("unexpected {path} execution mode: {execution_mode:?}")
                    }
                };

                assert_eq!(
                    case.original_source.as_bytes(),
                    original_source.as_bytes(),
                    "{path}"
                );
                assert_eq!(
                    case.includes.iter().map(String::as_str).collect::<Vec<_>>(),
                    expected_includes,
                    "{path}"
                );
                assert_eq!(
                    case.features.iter().map(String::as_str).collect::<Vec<_>>(),
                    ["iterator-helpers"],
                    "{path}"
                );
                assert!(case.flags.is_empty(), "{path}");
                assert!(case.negative.is_none(), "{path}");

                let local_materialized =
                    materialize_test(&case, &local_store).unwrap_or_else(|error| {
                        panic!("local {} should materialize: {error}", case.execution_id())
                    });
                let mut expected_local_source = String::from(strict_prefix);
                if requires_active_host {
                    expected_local_source.push_str(&active_host);
                }
                expected_local_source.push_str(&local_assert.contents);
                if !requires_active_host {
                    expected_local_source.push_str(&local_sta.contents);
                }
                let expected_local_preludes = if requires_active_host {
                    expected_local_source.push_str(&local_sta.contents);
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                        ("sta.js".to_string(), PreludeOrigin::LocalMerged),
                    ]
                } else if expected_includes == COMPARE_ARRAY {
                    expected_local_source.push_str(&local_compare_array.contents);
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                        ("sta-preamble.js".to_string(), PreludeOrigin::LocalMerged),
                        (
                            "compareArray.js".to_string(),
                            PreludeOrigin::VendoredHarness,
                        ),
                    ]
                } else {
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                        ("sta-preamble.js".to_string(), PreludeOrigin::LocalMerged),
                    ]
                };
                expected_local_source.push_str(&original_source);
                assert_eq!(
                    local_materialized.used_preludes,
                    expected_local_preludes,
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &local_materialized).as_bytes(),
                    expected_local_source.as_bytes(),
                    "{}",
                    case.execution_id()
                );

                let vendored_materialized = materialize_test(&case, &vendored_store)
                    .unwrap_or_else(|error| {
                        panic!(
                            "vendored {} should materialize: {error}",
                            case.execution_id()
                        )
                    });
                let mut expected_vendored_source = String::from(strict_prefix);
                if requires_active_host {
                    expected_vendored_source.push_str(&active_host);
                }
                expected_vendored_source.push_str(&vendored_assert.contents);
                expected_vendored_source.push_str(&vendored_sta.contents);
                let mut expected_vendored_preludes = vec![
                    ("assert.js".to_string(), PreludeOrigin::VendoredHarness),
                    ("sta.js".to_string(), PreludeOrigin::VendoredHarness),
                ];
                if expected_includes == COMPARE_ARRAY {
                    expected_vendored_source.push_str(&vendored_compare_array.contents);
                    expected_vendored_preludes.push((
                        "compareArray.js".to_string(),
                        PreludeOrigin::VendoredHarness,
                    ));
                }
                expected_vendored_source.push_str(&original_source);
                assert_eq!(
                    vendored_materialized.used_preludes,
                    expected_vendored_preludes,
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &vendored_materialized).as_bytes(),
                    expected_vendored_source.as_bytes(),
                    "{}",
                    case.execution_id()
                );
            }
        }
    }

    #[test]
    fn materialize_wasm_aot_full_assert_uses_sta_when_it_references_test262_error() {
        let mut store = PreludeStore::default();
        store.insert(
            "sta.js".to_string(),
            "function Test262Error(message) { throw 'sta should be skipped'; }\n".to_string(),
            PreludeOrigin::LocalMerged,
        );
        store.insert(
            "assert.js".to_string(),
            "function __scriptwAssertToString(value) { return String(value); }\nfunction Test262Error(message) {}\nassert.sameValue = function() {};\nassert.notSameValue = function() { throw 'full assert'; };\n".to_string(),
            PreludeOrigin::LocalMerged,
        );
        let mut case = synthetic_case("built-ins/Array/prototype/map/same-value-sta.js");
        case.original_source = Arc::from("assert.sameValue(true, true, 'value');\n".to_string());

        let materialized = materialize_test(&case, &store).expect("materialization should work");
        assert!(script_fixture_ledger(&case, &materialized).contains("sta should be skipped"));
        assert!(script_fixture_ledger(&case, &materialized).contains("full assert"));
        assert!(script_fixture_ledger(&case, &materialized).contains("assert.sameValue"));
    }

