    #[test]
    fn string_prepared_source_cases_preserve_pinned_sources_and_emit_wasm() {
        const CASES: [(
            &str,
            usize,
            u64,
            u64,
            &str,
            usize,
            scriptw_ir::DynamicSourceKind,
        ); 5] = [
            (
                "built-ins/String/prototype/charAt/S15.5.4.4_A1.1.js",
                805,
                0xb89d_51c2_9d1d_aaa7,
                0xdc56_6ccc_73b8_d63a,
                "eval(\"1\")",
                3,
                scriptw_ir::DynamicSourceKind::DirectEval,
            ),
            (
                "built-ins/String/prototype/charCodeAt/S15.5.4.5_A1.1.js",
                879,
                0x7386_0e06_db33_7b3e,
                0xe465_a19a_ec47_8515,
                "eval(\"1\")",
                4,
                scriptw_ir::DynamicSourceKind::DirectEval,
            ),
            (
                "built-ins/String/prototype/indexOf/S15.5.4.7_A3_T2.js",
                736,
                0x2fa0_5c59_cd7c_7752,
                0xe93e_432b_c7ac_cac4,
                "eval(\"\\\"-99\\\"\")",
                3,
                scriptw_ir::DynamicSourceKind::DirectEval,
            ),
            (
                "built-ins/String/prototype/match/S15.5.4.10_A1_T3.js",
                826,
                0x6299_f2d1_f435_fe55,
                0x5b74_76c3_74be_a1f8,
                "eval(\"\\\"bj\\\"\")",
                2,
                scriptw_ir::DynamicSourceKind::DirectEval,
            ),
            (
                "built-ins/String/prototype/slice/S15.5.4.13_A1_T5.js",
                969,
                0x6bd3_9ffc_8fe2_b383,
                0xa175_930a_6dbd_9c0e,
                "Function()",
                3,
                scriptw_ir::DynamicSourceKind::Function(scriptw_ir::DynamicFunctionKind::Ordinary),
            ),
        ];
        const COMBINED_PATH_SOURCE_FNV1A: u64 = 0xa8d8_8f84_b00e_6dcb;

        let test_root = repo_root().join("test262/vendor/test262/test");
        let local_store = real_wasm_aot_preludes();
        let vendored_store = real_wasm_aot_host_only_preludes();
        let mut combined_path_source_fingerprint = 0xcbf2_9ce4_8422_2325;
        let mut source_kind_counts = [0usize; 2];
        let mut physical_count = 0;
        let mut execution_count = 0;
        let mut materialization_count = 0;

        for (
            path,
            expected_source_bytes,
            expected_source_fingerprint,
            expected_contract_fingerprint,
            dynamic_source_needle,
            expected_dynamic_source_needle_count,
            dynamic_source_kind,
        ) in CASES
        {
            physical_count += 1;
            let source_path = test_root.join(path);
            let original_source = fs::read_to_string(&source_path)
                .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
            assert_eq!(
                original_source.len(),
                expected_source_bytes,
                "{path} source bytes"
            );
            assert_eq!(
                fnv1a(&original_source),
                expected_source_fingerprint,
                "{path} source fingerprint"
            );
            assert_eq!(
                original_source.matches(dynamic_source_needle).count(),
                expected_dynamic_source_needle_count,
                "{path} dynamic source call sites"
            );
            combined_path_source_fingerprint =
                fnv1a_extend(combined_path_source_fingerprint, path.as_bytes());
            combined_path_source_fingerprint = fnv1a_extend(combined_path_source_fingerprint, &[0]);
            combined_path_source_fingerprint =
                fnv1a_extend(combined_path_source_fingerprint, original_source.as_bytes());
            combined_path_source_fingerprint =
                fnv1a_extend(combined_path_source_fingerprint, &[u8::MAX]);

            match dynamic_source_kind {
                scriptw_ir::DynamicSourceKind::DirectEval => source_kind_counts[0] += 1,
                scriptw_ir::DynamicSourceKind::Function(
                    scriptw_ir::DynamicFunctionKind::Ordinary,
                ) => source_kind_counts[1] += 1,
                unexpected => panic!("unexpected {path} dynamic source kind: {unexpected:?}"),
            }

            let cases = parse_test_executions(
                path.to_string(),
                source_path.clone(),
                original_source.clone(),
            )
            .unwrap_or_else(|error| panic!("pinned {path} executions should parse: {error}"));
            assert_eq!(
                cases
                    .iter()
                    .map(TestCase::execution_mode)
                    .collect::<Vec<_>>(),
                vec![
                    TestExecutionMode::SloppyScript,
                    TestExecutionMode::StrictScript,
                ],
                "{path} execution modes"
            );

            for case in cases {
                execution_count += 1;
                assert_eq!(case.path(), path, "{path}");
                assert_eq!(case.source_path, source_path, "{path}");
                assert_eq!(
                    case.original_source.as_bytes(),
                    original_source.as_bytes(),
                    "{}",
                    case.execution_id()
                );
                assert!(case.flags.is_empty(), "{}", case.execution_id());
                assert!(case.features.is_empty(), "{}", case.execution_id());
                assert!(case.includes.is_empty(), "{}", case.execution_id());
                assert!(case.negative.is_none(), "{}", case.execution_id());
                assert_eq!(
                    test_case_contract_fingerprint(&case),
                    expected_contract_fingerprint,
                    "{}",
                    case.execution_id()
                );
                assert!(case_needs_test262_error_prelude(&case), "{path}");

                let strict_prefix = match case.execution_mode() {
                    TestExecutionMode::SloppyScript => "",
                    TestExecutionMode::StrictScript => "\"use strict\";\n",
                    unexpected => panic!("unexpected {path} execution mode: {unexpected:?}"),
                };
                for (store_name, store, sta_name, expected_origin) in [
                    (
                        "local",
                        &local_store,
                        "sta-preamble.js",
                        PreludeOrigin::LocalMerged,
                    ),
                    (
                        "vendored",
                        &vendored_store,
                        "sta.js",
                        PreludeOrigin::VendoredHarness,
                    ),
                ] {
                    materialization_count += 1;
                    let assert_prelude = store
                        .get("assert.js")
                        .unwrap_or_else(|| panic!("{store_name} store should contain assert.js"));
                    let sta_prelude = store
                        .get(sta_name)
                        .unwrap_or_else(|| panic!("{store_name} store should contain {sta_name}"));
                    assert_eq!(assert_prelude.origin, expected_origin, "{store_name}");
                    assert_eq!(sta_prelude.origin, expected_origin, "{store_name}");

                    let materialized = materialize_test(&case, store).unwrap_or_else(|error| {
                        panic!(
                            "{store_name} {} should materialize: {error}",
                            case.execution_id()
                        )
                    });
                    assert_eq!(materialized.execution_id(), case.execution_id());
                    assert_eq!(
                        materialized.used_preludes,
                        vec![
                            ("assert.js".to_string(), expected_origin),
                            (sta_name.to_string(), expected_origin),
                        ],
                        "{store_name} {}",
                        case.execution_id()
                    );
                    assert_eq!(
                        script_fixture_ledger(&case, &materialized).as_bytes(),
                        format!(
                            "{strict_prefix}{}{}{original_source}",
                            assert_prelude.contents, sta_prelude.contents
                        )
                        .as_bytes(),
                        "{store_name} {}",
                        case.execution_id()
                    );

                    let engine = Engine::new(RealmBuilder::new().build());
                    let unit = engine
                        .compile_script(
                            &materialized.source,
                            compile_options_for_materialized_case(&case, &materialized),
                        )
                        .unwrap_or_else(|error| {
                            panic!(
                                "{store_name} {} should reach typed IR: {error}",
                                case.execution_id()
                            )
                        });
                    engine.emit_wasm(&unit).unwrap_or_else(|error| {
                        panic!(
                            "{store_name} {} prepared source should emit Wasm: {error}",
                            case.execution_id()
                        )
                    });
                }
            }
        }

        assert_eq!(combined_path_source_fingerprint, COMBINED_PATH_SOURCE_FNV1A);
        assert_eq!(source_kind_counts, [4, 1]);
        assert_eq!(physical_count, 5);
        assert_eq!(execution_count, 10);
        assert_eq!(materialization_count, 20);
    }

