    fn assert_proxy_dynamic_source_case(path: &str, dynamic_source_needle: &str) {
        let preludes = real_wasm_aot_preludes();
        let test_root = repo_root().join("test262/vendor/test262/test");
        let source_path = test_root.join(path);
        let original_source = fs::read_to_string(&source_path)
            .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
        assert_eq!(
            original_source.matches(dynamic_source_needle).count(),
            1,
            "{path} dynamic source call sites"
        );

        let cases = parse_test_executions(
            path.to_string(),
            source_path.clone(),
            original_source.clone(),
        )
        .unwrap_or_else(|error| panic!("pinned {path} executions should parse: {error}"));
        assert_eq!(
            cases
                .iter()
                .map(TestCase::execution_mode)
                .collect::<Vec<_>>(),
            vec![
                TestExecutionMode::SloppyScript,
                TestExecutionMode::StrictScript,
            ],
            "{path} execution modes"
        );

        let active_host = validated_wasm_aot_host().render(WasmAotRealmActivation::Active);
        let assert_prelude = preludes
            .get("assert.js")
            .expect("merged assertion prelude should exist");
        let sta_prelude = preludes
            .get("sta.js")
            .expect("merged sta prelude should exist");
        assert_eq!(assert_prelude.origin, PreludeOrigin::LocalMerged);
        assert_eq!(sta_prelude.origin, PreludeOrigin::LocalMerged);

        for case in cases {
            assert_eq!(case.path(), path);
            assert_eq!(case.source_path, source_path);
            assert_eq!(case.original_source.as_ref(), original_source);
            assert!(case.includes.is_empty(), "{}", case.execution_id());
            assert!(case.negative.is_none(), "{}", case.execution_id());

            let strict_prefix = match case.execution_mode() {
                TestExecutionMode::SloppyScript => "",
                TestExecutionMode::StrictScript => "\"use strict\";\n",
                unexpected => panic!("unexpected {path} execution mode: {unexpected:?}"),
            };
            let materialized = materialize_test(&case, &preludes).unwrap_or_else(|error| {
                panic!("{} should materialize: {error}", case.execution_id())
            });
            assert_eq!(
                materialized.used_preludes,
                vec![
                    ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                    ("sta.js".to_string(), PreludeOrigin::LocalMerged),
                ],
                "{}",
                case.execution_id()
            );
            assert_eq!(
                script_fixture_ledger(&case, &materialized),
                format!(
                    "{strict_prefix}{active_host}{}{}{original_source}",
                    assert_prelude.contents, sta_prelude.contents
                ),
                "{}",
                case.execution_id()
            );
        }
    }

