    fn array_prototype_method_metadata_cases_preserve_pinned_sources_and_full_property_helpers() {
        let local_store = real_wasm_aot_preludes();
        let local_sta = local_store
            .get("sta-preamble.js")
            .expect("local Test262Error preamble should exist");
        let repo_root = repo_root();
        let test_root = repo_root.join("test262/vendor/test262/test");
        let local_harness_section = |name: &str| {
            let contents = WASM_AOT_HARNESS
                .split("///")
                .skip(1)
                .find_map(|contents| {
                    let mut lines = contents.lines();
                    (lines.next()?.trim() == name).then(|| lines.collect::<Vec<_>>().join("\n"))
                })
                .unwrap_or_else(|| panic!("missing {name} in Wasm-AOT harness"));
            format!("{contents}\n")
        };
        let local_assert = local_store
            .get("assert.js")
            .expect("local assertion helper should exist");
        let local_property = local_store
            .get("propertyHelper.js")
            .expect("local property helper should exist");
        let vendored_property_source =
            fs::read_to_string(repo_root.join("test262/vendor/test262/harness/propertyHelper.js"))
                .expect("vendored property helper should read");
        let mut vendored_store = vendored_assert_preludes();
        vendored_store.insert(
            "propertyHelper.js".to_string(),
            format!("{vendored_property_source}\n"),
            PreludeOrigin::VendoredHarness,
        );
        let vendored_property = vendored_store
            .get("propertyHelper.js")
            .expect("vendored property helper should exist");
        let vendored_assert = vendored_store
            .get("assert.js")
            .expect("vendored assertion helper should exist");

        assert_eq!(local_assert.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_assert.contents, local_harness_section("assert.js"));
        assert_eq!(local_property.origin, PreludeOrigin::LocalMerged);
        assert_eq!(
            local_property.contents,
            local_harness_section("propertyHelper.js")
        );
        assert_eq!(vendored_property.origin, PreludeOrigin::VendoredHarness);
        assert_eq!(
            vendored_property.contents,
            format!("{vendored_property_source}\n")
        );

        let mut source_count = 0;
        for method in [
            "at",
            "every",
            "filter",
            "find",
            "findIndex",
            "findLast",
            "findLastIndex",
            "forEach",
            "includes",
            "indexOf",
            "lastIndexOf",
            "map",
            "flat",
            "flatMap",
            "some",
            "toString",
        ] {
            for file_name in ["prop-desc.js", "length.js", "name.js"] {
                let path = format!("built-ins/Array/prototype/{method}/{file_name}");
                let source_path = test_root.join(&path);
                let original_source = fs::read_to_string(&source_path)
                    .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
                let case = parse_test_case(path.clone(), source_path, original_source);

                source_count += 1;
                assert_eq!(case.includes, ["propertyHelper.js"], "{path}");

                let local_materialized = materialize_test(&case, &local_store)
                    .unwrap_or_else(|error| panic!("local {path} should materialize: {error}"));
                assert_eq!(
                    local_materialized.used_preludes,
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                        ("sta-preamble.js".to_string(), PreludeOrigin::LocalMerged),
                        ("propertyHelper.js".to_string(), PreludeOrigin::LocalMerged),
                    ],
                    "{path}"
                );
                assert_eq!(
                    script_fixture_ledger(&case, &local_materialized),
                    format!(
                        "{}{}{}{}",
                        local_assert.contents,
                        local_sta.contents,
                        local_property.contents,
                        case.original_source
                    ),
                    "{path}"
                );

                let vendored_materialized = materialize_test(&case, &vendored_store)
                    .unwrap_or_else(|error| panic!("vendored {path} should materialize: {error}"));
                assert_eq!(
                    vendored_materialized.used_preludes,
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::VendoredHarness),
                        (
                            "propertyHelper.js".to_string(),
                            PreludeOrigin::VendoredHarness,
                        ),
                    ],
                    "{path}"
                );
                assert_eq!(
                    script_fixture_ledger(&case, &vendored_materialized),
                    format!(
                        "{}{}{}",
                        vendored_assert.contents, vendored_property.contents, case.original_source
                    ),
                    "{path}"
                );
            }
        }

        assert_eq!(source_count, 48);
    }

    #[test]
    fn typed_array_to_string_cases_use_full_vendored_preludes() {
        let mut store = vendored_test_typed_array_store();
        for prelude_name in ["propertyHelper.js", "isConstructor.js"] {
            let contents = fs::read_to_string(
                repo_root()
                    .join("test262/vendor/test262/harness")
                    .join(prelude_name),
            )
            .unwrap_or_else(|error| panic!("vendored {prelude_name} should read: {error}"));
            store.insert(
                prelude_name.to_string(),
                format!("{contents}\n"),
                PreludeOrigin::VendoredHarness,
            );
        }

        let test_root = repo_root().join("test262/vendor/test262/test");
        for path in [
            "built-ins/TypedArray/prototype/toString.js",
            "built-ins/TypedArray/prototype/toString/not-a-constructor.js",
        ] {
            let source_path = test_root.join(path);
            let original_source = fs::read_to_string(&source_path)
                .unwrap_or_else(|error| panic!("vendored {path} should read: {error}"));
            let case = parse_test_case(path.to_string(), source_path, original_source);

            let materialized =
                materialize_test(&case, &store).expect("vendored case should materialize");

            assert!(
                materialized.source.ends_with(case.original_source.as_ref()),
                "{path}"
            );
            assert!(
                script_fixture_ledger(&case, &materialized)
                    .contains("function testWithAllTypedArrayConstructors"),
                "{path}"
            );
            assert!(
                script_fixture_ledger(&case, &materialized)
                    .contains("Only values between 0 and 2**53 - 1"),
                "{path}"
            );

            if path.ends_with("prototype/toString.js") {
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("function verifyProperty(obj, name, desc, options)"),
                    "{path}"
                );
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("function verifyCallableProperty"),
                    "{path}"
                );
            } else {
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("function isConstructor(f)"),
                    "{path}"
                );
            }
        }
    }

