    #[test]
    fn error_is_error_errors_other_realm_preserves_pinned_source_and_preludes() {
        let preludes = real_wasm_aot_preludes();
        let path = "built-ins/Error/isError/errors-other-realm.js";
        let source_path = repo_root().join("test262/vendor/test262/test").join(path);
        let original_source = fs::read_to_string(&source_path)
            .expect("pinned Error.isError other-Realm case should read");
        let cases = parse_test_executions(path.to_string(), source_path, original_source.clone())
            .expect("pinned Error.isError other-Realm executions should parse");
        let sta_prelude = preludes
            .get("sta.js")
            .expect("merged sta prelude should exist");
        let assert_prelude = preludes
            .get("assert.js")
            .expect("merged assertion prelude should exist");
        let active_host = validated_wasm_aot_host().render(WasmAotRealmActivation::Active);

        assert_eq!(sta_prelude.origin, PreludeOrigin::LocalMerged);
        assert_eq!(assert_prelude.origin, PreludeOrigin::LocalMerged);
        assert!(active_host.contains(WASM_AOT_ACTIVE_REALM_GLOBAL));
        assert!(active_host.contains(WASM_AOT_ACTIVE_CREATE_REALM));
        assert!(!active_host.contains(WASM_AOT_INACTIVE_REALM_GLOBAL));
        assert!(!active_host.contains(WASM_AOT_INACTIVE_CREATE_REALM));
        assert_eq!(
            cases
                .iter()
                .map(|case| case.execution_mode())
                .collect::<Vec<_>>(),
            vec![
                TestExecutionMode::SloppyScript,
                TestExecutionMode::StrictScript,
            ]
        );
        assert!(
            original_source
                .contains("assert.sameValue(Error.isError(new other.SuppressedError()), true);")
        );

        for case in cases {
            assert!(case.includes.is_empty(), "{}", case.execution_id());

            let strict_prefix = match case.execution_mode() {
                TestExecutionMode::SloppyScript => "",
                TestExecutionMode::StrictScript => "\"use strict\";\n",
                execution_mode => panic!(
                    "unexpected Error.isError other-Realm execution mode: {execution_mode:?}"
                ),
            };
            let materialized = materialize_test(&case, &preludes)
                .expect("Error.isError other-Realm case should materialize");
            let expected_source = format!(
                "{strict_prefix}{active_host}{}{}{original_source}",
                assert_prelude.contents, sta_prelude.contents
            );

            assert!(
                script_fixture_ledger(&case, &materialized).contains(WASM_AOT_ACTIVE_REALM_GLOBAL)
            );
            assert!(
                script_fixture_ledger(&case, &materialized).contains(WASM_AOT_ACTIVE_CREATE_REALM)
            );
            assert!(
                !script_fixture_ledger(&case, &materialized)
                    .contains(WASM_AOT_INACTIVE_REALM_GLOBAL)
            );
            assert!(
                !script_fixture_ledger(&case, &materialized)
                    .contains(WASM_AOT_INACTIVE_CREATE_REALM)
            );
            assert_eq!(
                materialized.used_preludes,
                vec![
                    ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                    ("sta.js".to_string(), PreludeOrigin::LocalMerged),
                ],
                "{}",
                case.execution_id()
            );
            assert_eq!(
                script_fixture_ledger(&case, &materialized).as_bytes(),
                expected_source.as_bytes(),
                "{}",
                case.execution_id()
            );
        }
    }

