    #[test]
    fn aggregate_and_suppressed_error_core_cases_preserve_pinned_sources_and_full_preludes() {
        let repo_root = repo_root();
        let test_root = repo_root.join("test262/vendor/test262/test");
        let local_store = real_wasm_aot_preludes();
        let local_sta = local_store
            .get("sta-preamble.js")
            .expect("local Test262Error preamble should exist");
        let local_harness_section = |name: &str| {
            let contents = WASM_AOT_HARNESS
                .split("///")
                .skip(1)
                .find_map(|contents| {
                    let mut lines = contents.lines();
                    (lines.next()?.trim() == name).then(|| lines.collect::<Vec<_>>().join("\n"))
                })
                .unwrap_or_else(|| panic!("missing {name} in Wasm-AOT harness"));
            format!("{contents}\n")
        };
        let local_assert = local_store
            .get("assert.js")
            .expect("local assertion prelude should exist");
        let local_property = local_store
            .get("propertyHelper.js")
            .expect("local property prelude should exist");

        let vendored_store = real_wasm_aot_host_only_preludes();
        let vendored_sta = vendored_store
            .get("sta.js")
            .expect("vendored sta prelude should exist");
        let vendored_assert = vendored_store
            .get("assert.js")
            .expect("vendored assertion prelude should exist");
        let vendored_property = vendored_store
            .get("propertyHelper.js")
            .expect("vendored property prelude should exist");

        assert_eq!(local_assert.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_assert.contents, local_harness_section("assert.js"));
        assert_eq!(local_property.origin, PreludeOrigin::LocalMerged);
        assert_eq!(
            local_property.contents,
            local_harness_section("propertyHelper.js")
        );
        for prelude in [vendored_sta, vendored_assert, vendored_property] {
            let source = fs::read_to_string(
                repo_root
                    .join("test262/vendor/test262/harness")
                    .join(&prelude.name),
            )
            .unwrap_or_else(|error| panic!("vendored {} should read: {error}", prelude.name));
            assert_eq!(prelude.origin, PreludeOrigin::VendoredHarness);
            assert_eq!(prelude.contents, format!("{source}\n"));
        }

        let paths: [(&str, &[&str]); 14] = [
            (
                "built-ins/AggregateError/cause-property.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/message-method-prop.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/message-method-prop-cast.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/prototype/constructor.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/prototype/message.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/prototype/name.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/AggregateError/prototype/prop-desc.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/SuppressedError/message-method-prop.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/SuppressedError/message-method-prop-cast.js",
                &["propertyHelper.js"],
            ),
            ("built-ins/SuppressedError/order-of-args-evaluation.js", &[]),
            (
                "built-ins/SuppressedError/prototype/constructor.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/SuppressedError/prototype/message.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/SuppressedError/prototype/name.js",
                &["propertyHelper.js"],
            ),
            (
                "built-ins/SuppressedError/prototype/prop-desc.js",
                &["propertyHelper.js"],
            ),
        ];

        for (path, declared_includes) in paths {
            let source_path = test_root.join(path);
            let original_source = fs::read_to_string(&source_path)
                .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
            let cases =
                parse_test_executions(path.to_string(), source_path, original_source.clone())
                    .unwrap_or_else(|error| {
                        panic!("pinned {path} executions should parse: {error}")
                    });

            assert_eq!(
                cases
                    .iter()
                    .map(TestCase::execution_mode)
                    .collect::<Vec<_>>(),
                vec![
                    TestExecutionMode::SloppyScript,
                    TestExecutionMode::StrictScript,
                ],
                "{path}"
            );

            for case in cases {
                let strict_prefix = match case.execution_mode() {
                    TestExecutionMode::SloppyScript => "",
                    TestExecutionMode::StrictScript => "\"use strict\";\n",
                    execution_mode => {
                        panic!("unexpected {path} execution mode: {execution_mode:?}")
                    }
                };
                let expected_includes = declared_includes
                    .iter()
                    .map(|include| include.to_string())
                    .collect::<Vec<_>>();

                assert_eq!(
                    case.original_source.as_bytes(),
                    original_source.as_bytes(),
                    "{path}"
                );
                assert_eq!(case.includes, expected_includes, "{path}");

                let mut local_prelude_source =
                    format!("{}{}", local_assert.contents, local_sta.contents);
                let mut local_provenance = vec![
                    ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                    ("sta-preamble.js".to_string(), PreludeOrigin::LocalMerged),
                ];
                if !expected_includes.is_empty() {
                    local_prelude_source.push_str(&local_property.contents);
                    local_provenance
                        .push(("propertyHelper.js".to_string(), PreludeOrigin::LocalMerged));
                }
                let local_materialized =
                    materialize_test(&case, &local_store).unwrap_or_else(|error| {
                        panic!("local {} should materialize: {error}", case.execution_id())
                    });
                assert_eq!(
                    local_materialized.used_preludes,
                    local_provenance,
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &local_materialized).as_bytes(),
                    format!("{strict_prefix}{local_prelude_source}{original_source}").as_bytes(),
                    "{}",
                    case.execution_id()
                );

                let mut vendored_prelude_source =
                    format!("{}{}", vendored_assert.contents, vendored_sta.contents);
                let mut vendored_provenance = vec![
                    ("assert.js".to_string(), PreludeOrigin::VendoredHarness),
                    ("sta.js".to_string(), PreludeOrigin::VendoredHarness),
                ];
                if !expected_includes.is_empty() {
                    vendored_prelude_source.push_str(&vendored_property.contents);
                    vendored_provenance.push((
                        "propertyHelper.js".to_string(),
                        PreludeOrigin::VendoredHarness,
                    ));
                }
                let vendored_materialized = materialize_test(&case, &vendored_store)
                    .unwrap_or_else(|error| {
                        panic!(
                            "vendored {} should materialize: {error}",
                            case.execution_id()
                        )
                    });
                assert_eq!(
                    vendored_materialized.used_preludes,
                    vendored_provenance,
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &vendored_materialized).as_bytes(),
                    format!("{strict_prefix}{vendored_prelude_source}{original_source}").as_bytes(),
                    "{}",
                    case.execution_id()
                );
            }
        }
    }

