    #[test]
    fn dataview_method_resizable_cases_preserve_pinned_sources_and_exact_preludes() {
        const CASE_CONTRACTS_FNV1A: [u64; 22] = [
            0x1284_d08b_6c37_7d3b,
            0x147a_f5ba_e6f9_9114,
            0x16c5_7b5d_b276_32ec,
            0x1dab_7a7e_23bd_8831,
            0x1dad_7277_e674_f597,
            0x2376_93ac_e71f_cf8d,
            0x42c7_0ed6_55a1_a62a,
            0x4cde_b025_9d48_6a7c,
            0x798d_3000_d24b_0e40,
            0x7fff_9541_a46d_a79e,
            0x9024_fe1e_73e7_99c9,
            0x9551_447e_b046_1616,
            0x9de4_b92d_4fb3_c864,
            0xa4bc_66e9_6c24_cfe5,
            0xa503_8e47_0d3b_1cde,
            0xb790_2c4e_c77d_1419,
            0xc1bf_8764_abe9_63db,
            0xc7fd_5654_81a7_3299,
            0xd601_8dd6_698d_0643,
            0xe0dd_549e_62c2_834a,
            0xe316_5e75_7875_0a86,
            0xf34c_6487_a9cd_b66c,
        ];
        const LOCAL_STA_PREAMBLE_FNV1A: u64 = 0xd1de_6d61_b24b_c195;
        const VENDORED_STA_PRELUDE_FNV1A: u64 = 0xd1de_6d61_b24b_c195;
        const VENDORED_ASSERT_PRELUDE_FNV1A: u64 = 0x9559_0b7f_7e59_fee1;

        let repo_root = repo_root();
        let test_root = repo_root.join("test262/vendor/test262/test");
        let harness_root = repo_root.join("test262/vendor/test262/harness");
        let local_store = real_wasm_aot_preludes();
        let local_harness_section = |name: &str| {
            let contents = WASM_AOT_HARNESS
                .split("///")
                .skip(1)
                .find_map(|contents| {
                    let mut lines = contents.lines();
                    (lines.next()?.trim() == name).then(|| lines.collect::<Vec<_>>().join("\n"))
                })
                .unwrap_or_else(|| panic!("missing {name} in Wasm-AOT harness"));
            format!("{contents}\n")
        };
        let vendored_harness_source = |name: &str| {
            let source = fs::read_to_string(harness_root.join(name))
                .unwrap_or_else(|error| panic!("vendored {name} should read: {error}"));
            format!("{source}\n")
        };

        let vendored_store = real_wasm_aot_host_only_preludes();

        let local_sta = local_store
            .get("sta-preamble.js")
            .expect("local Test262Error preamble should exist");
        let local_assert = local_store
            .get("assert.js")
            .expect("local assertion prelude should exist");
        let vendored_sta = vendored_store
            .get("sta.js")
            .expect("vendored sta prelude should exist");
        let vendored_assert = vendored_store
            .get("assert.js")
            .expect("vendored assertion prelude should exist");

        assert_eq!(local_sta.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_sta.contents, local_harness_section("sta-preamble.js"));
        assert_eq!(fnv1a(&local_sta.contents), LOCAL_STA_PREAMBLE_FNV1A);
        assert_eq!(local_assert.origin, PreludeOrigin::LocalMerged);
        assert_eq!(local_assert.contents, local_harness_section("assert.js"));
        assert_eq!(fnv1a(&local_assert.contents), LOCAL_ASSERT_PRELUDE_FNV1A);
        assert_eq!(vendored_sta.origin, PreludeOrigin::VendoredHarness);
        assert_eq!(vendored_sta.contents, vendored_harness_source("sta.js"));
        assert_eq!(fnv1a(&vendored_sta.contents), VENDORED_STA_PRELUDE_FNV1A);
        assert_eq!(vendored_assert.origin, PreludeOrigin::VendoredHarness);
        assert_eq!(
            vendored_assert.contents,
            vendored_harness_source("assert.js")
        );
        assert_eq!(
            fnv1a(&vendored_assert.contents),
            VENDORED_ASSERT_PRELUDE_FNV1A
        );

        let methods = [
            "getInt8",
            "getUint8",
            "getInt16",
            "getUint16",
            "getInt32",
            "getUint32",
            "getFloat16",
            "getFloat32",
            "getFloat64",
            "getBigInt64",
            "getBigUint64",
            "setInt8",
            "setUint8",
            "setInt16",
            "setUint16",
            "setInt32",
            "setUint32",
            "setFloat16",
            "setFloat32",
            "setFloat64",
            "setBigInt64",
            "setBigUint64",
        ];
        let physical_source_count = fs::read_dir(test_root.join("built-ins/DataView/prototype"))
            .expect("pinned DataView prototype directory should read")
            .map(|entry| entry.expect("pinned DataView method directory should read"))
            .filter(|entry| entry.path().join("resizable-buffer.js").is_file())
            .count();
        assert_eq!(
            physical_source_count,
            methods.len(),
            "the pinned suite should not silently expand the 22-source census"
        );

        let mut case_fingerprints = Vec::with_capacity(methods.len());
        for method in methods {
            let path = format!("built-ins/DataView/prototype/{method}/resizable-buffer.js");
            let source_path = test_root.join(&path);
            let original_source = fs::read_to_string(&source_path)
                .unwrap_or_else(|error| panic!("pinned {path} should read: {error}"));
            let cases = parse_test_executions(path.clone(), source_path, original_source.clone())
                .unwrap_or_else(|error| panic!("pinned {path} executions should parse: {error}"));

            assert_eq!(
                cases
                    .iter()
                    .map(TestCase::execution_mode)
                    .collect::<Vec<_>>(),
                vec![
                    TestExecutionMode::SloppyScript,
                    TestExecutionMode::StrictScript,
                ],
                "{path}"
            );
            case_fingerprints.push(test_case_contract_fingerprint(
                cases.first().expect("physical case should have executions"),
            ));

            let expected_features: BTreeSet<String> =
                if matches!(method, "getFloat16" | "setFloat16") {
                    &[
                        "Float16Array",
                        "DataView",
                        "ArrayBuffer",
                        "resizable-arraybuffer",
                    ][..]
                } else {
                    &["DataView", "ArrayBuffer", "resizable-arraybuffer"][..]
                }
                .iter()
                .map(|feature| (*feature).to_string())
                .collect();

            for case in cases {
                let strict_prefix = match case.execution_mode() {
                    TestExecutionMode::SloppyScript => "",
                    TestExecutionMode::StrictScript => "\"use strict\";\n",
                    execution_mode => {
                        panic!("unexpected {path} execution mode: {execution_mode:?}")
                    }
                };

                assert_eq!(
                    case.original_source.as_bytes(),
                    original_source.as_bytes(),
                    "{path}"
                );
                assert!(case.includes.is_empty(), "{path}");
                assert!(case.flags.is_empty(), "{path}");
                assert_eq!(&case.features, &expected_features, "{path}");
                assert!(case.negative.is_none(), "{path}");

                let local_materialized =
                    materialize_test(&case, &local_store).unwrap_or_else(|error| {
                        panic!("local {} should materialize: {error}", case.execution_id())
                    });
                assert_eq!(
                    local_materialized.used_preludes,
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::LocalMerged),
                        ("sta-preamble.js".to_string(), PreludeOrigin::LocalMerged),
                    ],
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &local_materialized).as_bytes(),
                    format!(
                        "{strict_prefix}{}{}{original_source}",
                        local_assert.contents, local_sta.contents
                    )
                    .as_bytes(),
                    "{}",
                    case.execution_id()
                );

                let vendored_materialized = materialize_test(&case, &vendored_store)
                    .unwrap_or_else(|error| {
                        panic!(
                            "vendored {} should materialize: {error}",
                            case.execution_id()
                        )
                    });
                assert_eq!(
                    vendored_materialized.used_preludes,
                    vec![
                        ("assert.js".to_string(), PreludeOrigin::VendoredHarness),
                        ("sta.js".to_string(), PreludeOrigin::VendoredHarness),
                    ],
                    "{}",
                    case.execution_id()
                );
                assert_eq!(
                    script_fixture_ledger(&case, &vendored_materialized).as_bytes(),
                    format!(
                        "{strict_prefix}{}{}{original_source}",
                        vendored_assert.contents, vendored_sta.contents
                    )
                    .as_bytes(),
                    "{}",
                    case.execution_id()
                );
            }
        }

        case_fingerprints.sort_unstable();
        assert_eq!(case_fingerprints.as_slice(), CASE_CONTRACTS_FNV1A);
    }

    #[test]
    fn materialize_arraybuffer_slice_wrong_receiver_preserves_vendored_bodies() {
        let store = fixture_preludes();

        for file in [
            "context-is-not-object.js",
            "context-is-not-arraybuffer-object.js",
        ] {
            let path = format!("built-ins/ArrayBuffer/prototype/slice/{file}");
            let source_path = repo_root().join("test262/vendor/test262/test").join(&path);
            let original_source = fs::read_to_string(&source_path)
                .expect("vendored ArrayBuffer slice receiver case should read");
            let case = parse_test_case(path.clone(), source_path, original_source);

            let materialized =
                materialize_test(&case, &store).expect("materialization should work");

            assert!(
                materialized.source.ends_with(case.original_source.as_ref()),
                "{path}"
            );
            assert!(
                script_fixture_ledger(&case, &materialized).contains("assert.throws(TypeError")
            );
            if file == "context-is-not-object.js" {
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("ArrayBuffer.prototype.slice.call(undefined)")
                );
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("ArrayBuffer.prototype.slice.call(Symbol())")
                );
            } else {
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("ArrayBuffer.prototype.slice.call({})")
                );
                assert!(
                    script_fixture_ledger(&case, &materialized)
                        .contains("ArrayBuffer.prototype.slice.call([])")
                );
            }
        }

        let path = "built-ins/ArrayBuffer/prototype/slice/context-is-not-object.js";
        let source_path = repo_root().join("test262/vendor/test262/test").join(path);
        let mut changed_source = fs::read_to_string(&source_path)
            .expect("vendored ArrayBuffer slice receiver case should read");
        changed_source.push_str("\nvar sourceDriftMarker = true;\n");
        let changed_case = parse_test_case(path.to_string(), source_path, changed_source);
        let materialized =
            materialize_test(&changed_case, &store).expect("changed case should materialize");

        assert!(
            materialized
                .source
                .ends_with(changed_case.original_source.as_ref())
        );
        assert!(
            script_fixture_ledger(&changed_case, &materialized)
                .contains("var sourceDriftMarker = true;")
        );
    }

