    #[test]
    fn generate_backlog_writes_deterministic_failure_inventory() {
        let config = tiny_failing_suite_config("backlog-inventory");
        let run_config = RunConfig {
            snapshot_name: "backlog-inventory".to_string(),
            execution_backend: ExecutionBackend::SpecExec,
            ..RunConfig::default()
        };
        let summary = run_top_level_matrix(&config, run_config.clone()).expect("matrix should run");
        assert_eq!(summary.failed, 1);

        let (artifact, paths) = generate_backlog(
            &config,
            &run_config.snapshot_name,
            ExecutionBackend::SpecExec,
        )
        .expect("backlog should generate");
        assert_eq!(artifact.snapshot_version, SNAPSHOT_VERSION);
        assert_eq!(artifact.producer, ArtifactProducer::CURRENT);
        assert_eq!(artifact.execution_backend, ExecutionBackend::SpecExec);
        assert_eq!(artifact.records.len(), 1);
        let record = &artifact.records[0];
        assert_eq!(record.test_path, "built-ins/Array/intentional-failure.js");
        assert_eq!(
            record.ownership,
            BacklogOwnership::assigned(ConformanceOwner::T16, BacklogDebtCategory::Semantic)
        );
        assert_eq!(record.features, vec!["resizable-arraybuffer".to_string()]);
        assert!(record.duration_ms.is_some());
        assert!(!record.timed_out);
        assert!(paths.json_path.exists());
        assert!(paths.txt_path.exists());

        let first = fs::read_to_string(&paths.json_path).expect("backlog json should read");
        assert!(first.contains("\"producer\": \"scriptw\""));
        let first_json: serde_json::Value =
            serde_json::from_str(&first).expect("backlog json should parse");
        assert_eq!(first_json["execution_backend"], "spec-exec");
        assert_eq!(first_json["records"][0]["owner_task_id"], "T16");
        assert_eq!(first_json["records"][0]["debt_category"], "semantic");
        assert_eq!(
            first_json["records"][0]["failure_kind"],
            record.failure_kind.as_str()
        );
        assert_eq!(first_json["records"][0]["outcome"], record.outcome.as_str());
        assert_eq!(first_json["records"][0]["origin"], record.origin.as_str());
        assert_eq!(
            serde_json::from_str::<BacklogArtifact>(&first)
                .expect("generated backlog should deserialize"),
            artifact
        );
        for (field, label) in [
            ("failure_kind", "FutureKind"),
            ("outcome", "FutureOutcome"),
            ("origin", "future-origin"),
        ] {
            let mut tampered = first_json.clone();
            tampered["records"][0][field] = serde_json::json!(label);
            let err = serde_json::from_value::<BacklogArtifact>(tampered)
                .expect_err("unknown backlog taxonomy labels must be rejected");
            assert!(
                err.to_string().contains(label),
                "expected {label:?} in {err:?}"
            );
        }
        let mut unknown_backend = first_json.clone();
        unknown_backend["execution_backend"] = serde_json::json!("future-backend");
        let err = serde_json::from_value::<BacklogArtifact>(unknown_backend)
            .expect_err("unknown backlog execution backend must be rejected");
        assert!(err.to_string().contains("future-backend"), "{err}");
        let (second_artifact, second_paths) = generate_backlog(
            &config,
            &run_config.snapshot_name,
            ExecutionBackend::SpecExec,
        )
        .expect("second backlog should generate");
        assert_eq!(second_artifact, artifact);
        let second = fs::read_to_string(&second_paths.json_path).expect("backlog json should read");
        assert_eq!(second, first);
    }

